window.BUNDLED_COURSES = [{"id": "bilisim_teknolojileri", "name": "BİLİŞİM TEKNOLOJİLERİ", "code": "YBS101U", "icon": "fa-laptop-code", "color": "#38bdf8", "file": "bilisim_teknolojileri.json", "unit_count": 8, "question_count": 80, "flashcard_count": 30}, {"id": "genel_muhasebe", "name": "GENEL MUHASEBE", "code": "MUH101U", "icon": "fa-calculator", "color": "#10b981", "file": "genel_muhasebe.json", "unit_count": 8, "question_count": 80, "flashcard_count": 30}, {"id": "matematik_1", "name": "MATEMATİK I", "code": "MAT105U", "icon": "fa-square-root-variable", "color": "#f59e0b", "file": "matematik_1.json", "unit_count": 8, "question_count": 80, "flashcard_count": 30}, {"id": "iktisada_giris", "name": "İKTİSADA GİRİŞ", "code": "İKT101U", "icon": "fa-chart-line", "color": "#8b5cf6", "file": "iktisada_giris.json", "unit_count": 8, "question_count": 80, "flashcard_count": 30}, {"id": "isletme_ilkeleri", "name": "İŞLETME İLKELERİ", "code": "İŞL101U", "icon": "fa-briefcase", "color": "#ec4899", "file": "isletme_ilkeleri.json", "unit_count": 8, "question_count": 80, "flashcard_count": 30}];
window.BUNDLED_DATA = {"bilisim_teknolojileri": {"course_name": "BİLİŞİM TEKNOLOJİLERİ", "course_code": "YBS101U", "faculty": "İşletme / İktisat Fakültesi - Yönetim Bilişim Sistemleri (YBS)", "term": "1. Sınıf Güz Dönemi", "description": "Bilgisayar donanımı, yazılımı, işletim sistemleri, ağlar, güvenlik, programlama mantığı ve güncel bilişim yönelimleri.", "units": [{"unit_number": 1, "title": "Bilişim Teknolojilerinin Gelişimi", "is_vize": true, "key_topics": ["Tarihsel Süreç", "Bilgisayar Kuşakları", "DIKW Hiyerarşisi", "Moore Yasası", "Önemli Öncüler"], "hap_bilgiler": ["DIKW Piramidi: Veri (Data - işlenmemiş ham gerçekler) -> Enformasyon (Information - anlamlandırılmış veri) -> Bilgi (Knowledge - deneyim ve bağlamla harmanlanmış enformasyon) -> Bilgelik (Wisdom - bilgiyi doğru ve etik kullanma yetisi).", "İlk Mekanik Hesap Makineleri: Blaise Pascal (Pascaline - sadece toplama ve çıkarma), Gottfried Wilhelm Leibniz (Leibniz Çarkı - 4 işlem yapabilen).", "Modern Bilgisayarın Babası: Charles Babbage (Fark Motoru ve Analitik Motor). Analitik Motor için ilk algoritmayı yazan Ada Lovelace ise 'İlk Bilgisayar Programcısı' kabul edilir.", "Herman Hollerith: 1890 ABD nüfus sayımı için delikli kart sistemini geliştirdi ve daha sonra IBM'e dönüşecek şirketin temelini attı.", "ENIAC (1946): J. Presper Eckert ve John Mauchly tarafından geliştirilen, ilk genel amaçlı, tamamen elektronik, ondalık tabanlı devasa bilgisayardır (Vakum tüpleri kullanılmıştır).", "EDVAC ve Von Neumann: John von Neumann tarafından ortaya atılan 'Saklı Program' mimarisini (program ve verinin aynı bellekte tutulması) kullanan ilk tasarımdır.", "1. Kuşak (1940-1956): Vakum (Elektron) tüpleri kullanıldı. Çok büyük, çok ısı üreten, sık arızalanan ve makine diliyle programlanan makinelerdir.", "2. Kuşak (1956-1963): Transistörün icadı (1947, Bell Labs - Shockley, Bardeen, Brattain). Bilgisayarlar küçüldü, hızlandı ve Assembly/FORTRAN gibi diller doğdu.", "3. Kuşak (1964-1971): Entegre Devreler (Mikroçipler - Jack Kilby ve Robert Noyce). Klavye, monitör ve işletim sistemleri kullanılmaya başlandı.", "4. Kuşak (1971-Günümüz): Mikroişlemciler (Intel 4004 - 1971). Tek bir silikon çip üzerine tüm CPU yerleştirildi; kişisel bilgisayarlar (PC) devrimi başladı.", "5. Kuşak (Gelecek/Günümüz): Yapay zeka, paralel işlemciler, kuantum hesaplama ve doğal dil işleme.", "Moore Yasası: Intel'in kurucularından Gordon Moore'a göre bir mikroçip üzerindeki transistör sayısı yaklaşık her 18-24 ayda bir iki katına çıkacaktır."]}, {"unit_number": 2, "title": "Bilgisayar Donanımı", "is_vize": true, "key_topics": ["Von Neumann Mimarisi", "Merkezi İşlem Birimi (CPU)", "Bellek Hiyerarşisi", "Giriş-Çıkış Birimleri", "Veri Birimleri"], "hap_bilgiler": ["Von Neumann Mimarisi 4 Temel Bölüm: Giriş Birimleri, Çıkış Birimleri, Merkezi İşlem Birimi (CPU) ve Bellek (Memory).", "CPU Bileşenleri: 1. Aritmetik ve Mantık Birimi (ALU - matematiksel ve mantıksal işlemleri yapar), 2. Denetim Birimi (Control Unit / CU - komutları çözer, diğer birimleri senkronize yönetir), 3. Yazmaçlar (Registers - CPU içindeki en küçük ve en hızlı geçici depolama alanları).", "Saat Hızı (Clock Speed): İşlemcinin saniyede yaptığı döngü sayısını ifade eder (Hertz/GHz). 1 GHz = saniyede 1 milyar çevrim.", "Bellek Hiyerarşisi (Hız ve Maliyet Sıralaması: En Hızlı ve En Pahalıdan En Yavaşa): Yazmaçlar (Registers) -> L1 Önbellek -> L2 Önbellek -> L3 Önbellek -> RAM -> SSD / Sabit Disk (HDD) -> Optik/Manyetik Teyp.", "RAM (Random Access Memory): Geçici (uçucu/volatile) ana bellektir. Elektrik kesildiğinde veriler silinir. DRAM (Dinamik - yenileme gerekir, ucuz, ana RAM) ve SRAM (Statik - yenileme gerekmez, çok hızlı, önbellek olarak kullanılır).", "ROM (Read Only Memory): Kalıcı (uçucu olmayan/non-volatile) bellektir. Fabrika çıkışı BIOS/UEFI yazılımını tutar. Çeşitleri: PROM (bir kez programlanır), EPROM (morötesi ışıkla silinir), EEPROM (elektriksel olarak silinip yazılır, Flash bellekler bu yapıdadır).", "Giriş Birimleri: Klavye, fare, mikrofon, optik okuyucu, barkod okuyucu, tarayıcı.", "Çıkış Birimleri: Monitör, yazıcı, hoparlör, projeksiyon.", "Hem Giriş Hem Çıkış Birimleri: Dokunmatik ekranlar (Touchscreen), modemler, ağ kartları (NIC), ses kartları.", "Veri Ölçü Birimleri (İkili Sistem - 2^10 = 1024 kuralı): 1 Byte = 8 Bit. 1 Kilobyte (KB) = 1024 Byte. 1 Megabyte (MB) = 1024 KB. 1 Gigabyte (GB) = 1024 MB. 1 Terabyte (TB) = 1024 GB. 1 Petabyte (PB) = 1024 TB."]}, {"unit_number": 3, "title": "İşletim Sistemleri ve Dosya Yönetimi", "is_vize": true, "key_topics": ["İşletim Sisteminin Görevleri", "Çekirdek (Kernel) ve Kabuk (Shell)", "İşletim Sistemi Türleri", "Dosya Sistemleri"], "hap_bilgiler": ["İşletim Sistemi (OS): Kullanıcı ve uygulama programları ile bilgisayar donanımı arasındaki iletişimi sağlayan, donanım kaynaklarını yöneten temel sistem yazılımıdır.", "İşletim Sisteminin 4 Temel Yönetim Fonksiyonu: 1. İşlemci Yönetimi (Process Management / Görev Zamanlama), 2. Bellek Yönetimi (RAM tahsisi ve Sanal Bellek), 3. Aygıt (Giriş/Çıkış) Yönetimi, 4. Dosya ve Depolama Yönetimi.", "Çekirdek (Kernel): İşletim sisteminin kalbidir; doğrudan donanım seviyesinde çalışır ve bellek, CPU ve aygıt erişimlerini yönetir.", "Kabuk (Shell) ve Arayüz: Kullanıcının komut girdiği arayüzdür. CLI (Komut Satırı Arayüzü - terminal/bash/cmd) ve GUI (Grafiksel Kullanıcı Arayüzü - pencereler, ikonlar).", "Sanal Bellek (Virtual Memory): RAM yetersiz kaldığında sabit diskin (paging file / swap alanı) bir bölümünün geçici olarak RAM gibi kullanılması tekniğidir.", "İşletim Sistemi Sınıfları: Tek Kullanıcılı - Tek Görevli (MS-DOS), Tek Kullanıcılı - Çok Görevli (Windows 10/11, macOS), Çok Kullanıcılı - Çok Görevli (Unix, Linux sunucular), Gerçek Zamanlı (RTOS - savunma sanayii, otomotiv, robotik).", "Açık Kaynak Kodlu İşletim Sistemleri: Linux (1991'de Linus Torvalds tarafından geliştirilen çekirdek üzerine kuruludur). Dağıtımlar: Ubuntu, Fedora, Debian, Pardus (TÜBİTAK).", "Dosya Sistemleri: FAT32 (maksimum 4 GB tek dosya boyutu sınırı vardır), NTFS (Windows standartı, güvenlik izinleri, şifreleme ve günlükleme destekler), exFAT (USB bellekler için evrensel), ext4 (modern Linux), APFS (Apple Dosya Sistemi).", "Dosya Yolları: Mutlak Yol (Absolute Path - Kök dizinden başlar: 'C:\\Users\\Belgeler\\rapor.docx'), Göreceli Yol (Relative Path - bulunulan dizinden başlar: '..\\rapor.docx')."]}, {"unit_number": 4, "title": "Uygulama Yazılımları", "is_vize": true, "key_topics": ["Yazılım Türleri", "Ofis Yazılımları", "Yazılım Lisanslama Türleri", "SaaS ve Bulut Uygulamaları"], "hap_bilgiler": ["Yazılım Türleri: Sistem Yazılımları (İşletim sistemleri, aygıt sürücüleri, BIOS) ve Uygulama Yazılımları (Kullanıcının belirli bir işi yapmasını sağlayan yazılımlar: Word, Excel, Photoshop, ERP).", "Kelime İşlemci (Word Processors): Metin oluşturma, düzenleme, biçimlendirme ve raporlama (MS Word, Google Docs, LibreOffice Writer).", "Hesap Tablosu (Spreadsheet): Satır ve sütunlardan oluşan hücreler yapısı. Hücre adresi sütun harfi ve satır numarasından oluşur (örn: B4). Formüller daima '=' (eşittir) işareti ile başlar (MS Excel, Google Sheets, LibreOffice Calc).", "Sunum Yazılımları: Slaytlar, animasyonlar ve görsel anlatım (PowerPoint, Keynote, Prezi).", "Veritabanı Yönetim Sistemleri (DBMS): Büyük verilerin yapısal olarak saklanması ve SQL ile sorgulanması (MS Access, Oracle, MySQL, PostgreSQL).", "Yazılım Lisanslama Modelleri:", "  - Ticari (Proprietary) Yazılım: Telif hakkı saklıdır, kaynak kod kapalıdır, ücret ödenerek kullanım lisansı alınır (MS Windows, Photoshop).", "  - Açık Kaynak Kodlu (Open Source): Kaynak kodları herkese açıktır; incelenebilir, değiştirilebilir ve dağıtılabilir (Linux, LibreOffice, GIMP, Apache). GNU Genel Kamu Lisansı (GPL) yaygındır.", "  - Paylaşılan Yazılım (Shareware): Belirli bir süre (örneğin 30 gün) veya kısıtlı özellikle ücretsiz denenebilen, süre sonunda ücret talep eden yazılımlardır.", "  - Ücretsiz Yazılım (Freeware): Kullanımı tamamen ücretsiz olan ancak kaynak kodu kapalı olan yazılımlardır (Adobe Acrobat Reader).", "  - Kamu Malı (Public Domain): Telif hakkı süresi dolmuş veya bilinçli olarak kamuya bağışlanmış, hiçbir kısıtlaması olmayan yazılımlar.", "SaaS (Software as a Service - Hizmet Olarak Yazılım): Yazılımın bilgisayara kurulmadan doğrudan web tarayıcısı üzerinden bulut sunuculardan çalıştırılması modelidir (Office 365, Google Workspace, Canva)."]}, {"unit_number": 5, "title": "İnternet ve Mobil Teknolojiler", "is_vize": false, "key_topics": ["İnternetin Tarihi", "ARPANET ve TCP/IP", "WWW ve Web Nesilleri", "Mobil İletişim Kuşakları (1G-5G)", "Bulut Bilişim"], "hap_bilgiler": ["İnternetin Doğuşu: 1969 yılında ABD Savunma Bakanlığı İleri Araştırma Projeleri Ajansı (DARPA) tarafından kurulan 'ARPANET' internetin ilk atasıdır.", "TCP/IP: İnternetin ortak iletişim protokolü kümesidir. Vinton Cerf ve Robert Kahn tarafından geliştirilmiştir.", "World Wide Web (WWW): 1989 yılında CERN laboratuvarlarında İngiliz bilim insanı Tim Berners-Lee tarafından bilgi paylaşımını kolaylaştırmak amacıyla icat edilmiştir (HTTP, HTML ve URL standartlarını belirlemiştir).", "Web 1.0 (Statik Web): Tek taraflı iletişim. Kullanıcı sadece okuyucudur, içerik üreticileri web yöneticileridir.", "Web 2.0 (Sosyal ve Etkileşimli Web): Çift taraflı iletişim. Kullanıcılar içerik üretir, paylaşır ve etkileşime girer (Bloglar, Wikipedia, Sosyal Medya, YouTube).", "Web 3.0 (Semantik Web / Anlamsal Web): Makinelerin verileri anlayıp yorumlayabildiği, yapay zeka destekli ve merkeziyetsiz web yapısıdır.", "Mobil İletişim Nesilleri:", "  - 1G: Analog sinyaller, sadece ses iletimi.", "  - 2G: Dijital iletişim (GSM), SMS (kısa mesaj) ve çok düşük hızlı veri transferi (GPRS/EDGE).", "  - 3G: Mobil internet, görüntülü görüşme, veri hızında büyük artış (UMTS/HSPA).", "  - 4G (LTE): Yüksek hızlı mobil genişbant, HD video akışı, düşük gecikme süresi.", "  - 5G: Ultra yüksek hız (Gigabit seviyesi), 1 milisaniyenin altında ultra düşük gecikme, kitlesel IoT bağlantı kapasitesi.", "Bulut Bilişim Hizmet Modelleri:", "  - IaaS (Altyapı): Sunucu, sanal makine, ağ ve depolama kiralama (AWS EC2, Google Compute Engine).", "  - PaaS (Platform): Geliştiricilere işletim sistemi, veritabanı ve çalışma ortamı sunma (Heroku, Google App Engine).", "  - SaaS (Yazılım): Son kullanıcılara internet üzerinden hazır yazılım sunma (Gmail, Dropbox, Salesforce)."]}, {"unit_number": 6, "title": "İletişim Alt Yapısı ve Güvenlik", "is_vize": false, "key_topics": ["Ağ Türleri ve Topolojileri", "Ağ Donanımları", "OSI ve TCP/IP Modeli", "Bilgi Güvenliği (CIA)", "Siber Tehditler"], "hap_bilgiler": ["Ağ Türleri (Coğrafi Boyuta Göre): PAN (Kişisel Alan Ağı - Bluetooth), LAN (Yerel Alan Ağı - Ev/Ofis), CAN (Kampüs Alan Ağı - Üniversite), MAN (Metropol Alan Ağı - Şehir çapında), WAN (Geniş Alan Ağı - Şehirler/ülkeler arası; en büyük WAN İnternettir).", "Ağ Topolojileri: Yol (Bus - tek bir ana hat), Halka (Ring - jeton mantığı), Yıldız (Star - tüm cihazlar merkezi bir Switch/Hub'a bağlıdır, en yaygın kullanılanıdır), Ağaç (Tree), Örgü (Mesh - her düğüm diğerine bağlıdır, en yüksek hata toleransına sahiptir ancak en maliyetlisidir).", "Ağ Cihazları: Hub (Veriyi tüm portlara yayar/broadcast, verimsizdir), Switch (Anahtar - MAC adresine bakarak veriyi sadece ilgili hedefe iletir, Katman 2), Router (Yönlendirici - IP adreslerine bakarak farklı ağlar arasında yönlendirme yapar, Katman 3), Modem (Analog ve dijital sinyal dönüşümü yapar).", "OSI Modeli (7 Katman - Aşağıdan Yukarıya): 1. Fiziksel, 2. Veri Bağı (Data Link - MAC adresi, Switch), 3. Ağ (Network - IP adresi, Router), 4. İletim (Transport - TCP, UDP), 5. Oturum (Session), 6. Sunum (Presentation - şifreleme, sıkıştırma, format), 7. Uygulama (Application - HTTP, FTP, SMTP, DNS).", "Bilgi Güvenliğinin 3 Temel İlkesi (CIA Triad):", "  - Gizlilik (Confidentiality): Bilgiye sadece yetkili kişilerin erişebilmesi.", "  - Bütünlük (Integrity): Bilginin yetkisiz kişilerce değiştirilmemesi, doğruluğunun korunması.", "  - Erişilebilirlik (Availability): Yetkili kullanıcıların ihtiyaç duyduklarında bilgiye kesintisiz ulaşabilmesi.", "Zararlı Yazılımlar (Malware):", "  - Virüs: Kendi kendine çalışamaz, bir çalıştırılabilir dosyaya veya programa bulaşarak kullanıcı etkisiyle yayılır.", "  - Solucan (Worm): İnsan müdahalesi olmadan ağ bağlantılarını kullanarak kendi kendini kopyalayıp yayılan bağımsız programdır.", "  - Truva Atı (Trojan): Masum veya faydalı bir yazılım gibi görünüp arka planda arka kapı (backdoor) açan zararlıdır.", "  - Ransomware (Fidye Yazılımı): Dosyaları şifreleyerek açılması için fidye talep eden zararlı yazılımdır.", "Siber Saldırı Türleri: Oltalama (Phishing - sahte e-posta/web sitesiyle kimlik avı), DoS / DDoS (Hizmeti aksatmak için sunucuyu sahte trafik bombardımanına tutma), Ortadaki Adam (Man-in-the-Middle)."]}, {"unit_number": 7, "title": "Bilgisayar Programlama", "is_vize": false, "key_topics": ["Algoritma Kavramı", "Akış Şemaları", "Programlama Dilleri Düzeyleri", "Derleyici vs Yorumlayıcı", "Temel Programlama Mantığı"], "hap_bilgiler": ["Algoritma: Bir problemin çözümü için adım adım tanımlanmış, sonlu, açık, net ve uygulanabilir işlem basamakları dizisidir.", "Akış Şeması (Flowchart) Sembolleri: Oval (Başla / Dur), Paralelkenar (Veri Girişi / Çıkışı), Dikdörtgen (İşlem / Hesaplama / Atama), Eşkenar Dörtgen / Baklava (Karar / Karşılaştırma / Koşul).", "Dillerin Düzeyleri (İnsan Diline Yakınlık):", "  - Düşük Düzey Diller: Makine dili (0 ve 1'lerden oluşur, donanıma doğrudan bağlıdır) ve Assembly dili (sembolik kısaltmalar: MOV, ADD).", "  - Orta Düzey Diller: C dili (hem sistem programlama hem kullanıcı uygulamaları için elverişlidir).", "  - Yüksek Düzey Diller: İnsan diline çok yakın, donanımdan bağımsız dillerdir (Python, Java, C#, C++).", "Derleyici (Compiler) vs Yorumlayıcı (Interpreter):", "  - Derleyici: Kaynak kodun tamamını tek seferde makine diline çevirir ve çalıştırılabilir bir dosya (.exe vb.) oluşturur (C, C++, Go). Kod derlendikten sonra çok hızlı çalışır.", "  - Yorumlayıcı: Kaynak kodları satır satır okur, anında makine diline çevirip çalıştırır (Python, JavaScript, PHP). Hata ayıklama kolaydır ancak çalışma hızı genellikle derlenen dillere göre yavaştır.", "Temel Programlama Yapıları: Değişkenler (int, float, string, boolean), Koşul Blokları (if-else, switch-case), Döngüler (for, while - belirli işlemi tekrar ettirme), Fonksiyonlar/Metotlar (kodun tekrar kullanılabilir modüllere ayrılması).", "Nesne Yönelimli Programlama (OOP) Temel Kavramları: Sınıf (Class - şablon), Nesne (Object - sınıftan türetilen somut örnek), Kapsülleme (Encapsulation), Kalıtım (Inheritance - miras alma), Çok Biçimlilik (Polymorphism)."]}, {"unit_number": 8, "title": "Bilişim Teknolojilerinde Yeni Yönelimler", "is_vize": false, "key_topics": ["Endüstri 4.0", "Yapay Zeka ve Makine Öğrenmesi", "Büyük Veri (5V)", "Nesnelerin İnterneti (IoT)", "Blokzincir"], "hap_bilgiler": ["Sanayi Devrimleri: Endüstri 1.0 (Buhar makinesi ve mekanizasyon), Endüstri 2.0 (Elektrik enerjisi ve seri üretim bantları), Endüstri 3.0 (Elektronik, bilgisayarlar ve otomasyon), Endüstri 4.0 (Siber-fiziksel sistemler, akıllı fabrikalar, IoT, yapay zeka).", "Yapay Zeka (Artificial Intelligence - AI): İnsan zekasına özgü algılama, öğrenme, akıl yürütme ve problem çözme gibi işlevleri bilgisayarların gerçekleştirmesidir. Alan Turing (1950 - Turing Testi).", "Makine Öğrenmesi (Machine Learning) Türleri:", "  - Denetimli Öğrenme (Supervised Learning): Etiketli veriler kullanılarak sınıflandırma veya regresyon yapılması.", "  - Denetimsiz Öğrenme (Unsupervised Learning): Etiketsiz veriler arasındaki gizli örüntülerin ve kümelerin bulunması (Kümeleme).", "  - Pekiştirmeli Öğrenme (Reinforcement Learning): Ödül ve ceza mekanizmasıyla ajanın çevreyle etkileşime girerek en uygun kararları öğrenmesi.", "Büyük Veri (Big Data) 5V Bileşeni: Volume (Hacim / Boyut), Velocity (Hız / Veri üretim hızı), Variety (Çeşitlilik / Metin, ses, video), Veracity (Doğruluk / Güvenilirlik), Value (Değer / İş zekasına dönüşme).", "Nesnelerin İnterneti (IoT - Internet of Things): Fiziksel nesnelerin (sensörler, ev aletleri, araçlar) internet üzerinden birbirleriyle ve merkezi sistemlerle veri alışverişi yapabilmesidir. Kavramı ilk kez 1999'da Kevin Ashton kullanmıştır.", "Blokzincir (Blockchain): Dağıtık, merkeziyetsiz, şifrelenmiş ve değiştirilemez bir dijital defter teknolojisidir. İlk olarak Bitcoin ile 2008'de 'Satoshi Nakamoto' rumuzlu kişi/grup tarafından ortaya atılmıştır. Veriler bloklar halinde kriptografik özetlerle (hash) birbirine zincirlenir.", "Genişletilmiş Gerçeklik: Sanal Gerçeklik (VR - tamamen sanal bir ortama girme), Artırılmış Gerçeklik (AR - gerçek dünya görüntüsünün üzerine dijital nesneler bindirme, örn: Pokemon Go), Karma Gerçeklik (MR)."]}], "sinav_tuzaklari": [{"id": 1, "title": "Veri (Data) ile Enformasyon (Information) Karışıklığı", "mistake": "Öğrenci işlenmemiş ham veriler ile anlamlı hale getirilmiş bilgiyi birbirine karıştırır.", "truth": "Veri (Data) tek başına bir anlam ifade etmeyen, bağlamdan yoksun ham ölçümlerdir (örn: '28', 'Ali'). Enformasyon ise bu verilerin işlenip organize edilmiş halidir (örn: 'Ali'nin vize notu 28'dir').", "tip": "'İşlenmiş' veya 'anlamlandırılmış' kelimesini gördüğün anda cevap Enformasyon'dur!"}, {"id": 2, "title": "RAM ile ROM Arasındaki 'Uçuculuk' (Volatility) Tuzağı", "mistake": "Sınavda 'Elektrik kesildiğinde silinmeyen bellek' sorulduğunda öğrencinin doğrudan RAM'i işaretlemesi.", "truth": "RAM geçicidir (volatile), elektrik kesilince içindeki veriler UÇAR. ROM ise kalıcıdır (non-volatile), elektrik kesilse bile içindeki BIOS/üretici verileri silinmez.", "tip": "RAM = 'Rüzgar gibi Uçar' (Geçici); ROM = 'Rıza göstermez, Kalır' (Kalıcı)."}, {"id": 3, "title": "ALU ile Control Unit (CU) Görev Çatışması", "mistake": "Aritmetik Mantık Biriminin (ALU) bilgisayardaki tüm diğer parçalara komut gönderip onları yönettiğini düşünmek.", "truth": "Yönetim, senkronizasyon ve komut çözme işi Denetim Birimi'ne (Control Unit) aittir. ALU sadece dört işlem ve mantıksal (BÜYÜK, KÜÇÜK, EŞİT) karşılaştırmaları yapar.", "tip": "Hesap yapıyorsa ALU, emir verip orkestra şefliği yapıyorsa CU (Denetim Birimi)."}, {"id": 4, "title": "İşletim Sisteminin 'Uygulama Yazılımı' Olarak Düşünülmesi", "mistake": "Windows veya Linux'un bir uygulama yazılımı olduğu yanılgısı.", "truth": "İşletim sistemleri temel 'SİSTEM YAZILIMI'dır. Uygulama yazılımları (Word, Excel, Photoshop) işletim sisteminin sunduğu altyapı üzerinde çalışır.", "tip": "Bilgisayarın çalışması için şart olan ve donanımı yöneten her şey Sistem Yazılımıdır."}, {"id": 5, "title": "Hub ile Switch (Anahtar) Farkı", "mistake": "İkisinin de yerel ağda bilgisayarları birbirine bağlayan aynı mantıkta kutular olduğunu zannetmek.", "truth": "Hub aptaldır; bir porttan gelen veriyi bütün portlara yayınlar (Broadcast), ağda çakışma ve yavaşlık yaratır. Switch ise akıllıdır; gelen verinin MAC adresine bakar ve sadece ilgili hedef bilgisayara iletir.", "tip": "Sadece hedefe yollayan akıllı kutu: SWITCH. Herkese saçan: HUB."}, {"id": 6, "title": "OSI Modeli Katman Sırası ve Görevleri", "mistake": "Ağ (Network) katmanında MAC adreslerinin kullanıldığını sanmak.", "truth": "MAC adresleri 2. Katman olan 'Veri Bağı (Data Link)' katmanında kullanılır. IP adresleri ve yönlendirme (routing) ise 3. Katman olan 'Ağ (Network)' katmanında gerçekleşir.", "tip": "MAC = 2. Katman (Veri Bağı); IP = 3. Katman (Ağ Katmanı)."}, {"id": 7, "title": "Virüs ile Solucan (Worm) Ayırımı", "mistake": "İkisini eş anlamlı kabul etmek.", "truth": "Virüs kendi başına çalışamaz; bir taşıyıcı dosyaya (.exe, .doc vb.) ihtiyaç duyar ve kullanıcının o dosyayı açması gerekir. Solucan (Worm) ise kullanıcı müdahalesi olmadan ağ üzerinden kendi kendini kopyalar ve yayılır.", "tip": "Kendi kendine bağımsız yayılan: SOLUCAN; Kullanıcı çalıştırınca bulaşan: VİRÜS."}, {"id": 8, "title": "Derleyici (Compiler) ile Yorumlayıcı (Interpreter) Farkı", "mistake": "Python'ın derleyici kullandığını, C'nin yorumlayıcı olduğunu düşünmek.", "truth": "C, C++ derleyicidir (tüm kodu bir kerede makine diline çevirip .exe üretir). Python ve JavaScript ise yorumlayıcıdır (kodu satır satır okur ve hemen icra eder).", "tip": "Tek seferde toplu çeviri: Derleyici (Compiler). Satır satır anlık çeviri: Yorumlayıcı (Interpreter)."}, {"id": 9, "title": "Açık Kaynak Kod (Open Source) ile Ücretsiz Yazılım (Freeware) Eşit Değildir", "mistake": "Ücretsiz olan her yazılımın açık kaynak kodlu olduğunu sanmak.", "truth": "Adobe Reader ücretsizdir (Freeware) ama kaynak kodları gizlidir (kapalı kaynak). Açık kaynak kodlu bir yazılım ise hem ücretsiz olabilir hem de kaynak kodları herkes tarafından görülebilir ve geliştirilebilir.", "tip": "Freeware = Kod kapalı ama bedava. Open Source = Kod açık, herkes geliştirebilir."}, {"id": 10, "title": "Web 2.0 ile Web 3.0 Ayrımı", "mistake": "Sosyal medyanın ve Wikipedia'nın Web 3.0 olduğunu varsaymak.", "truth": "Kullanıcıların içerik ürettiği blog, sosyal medya ve video paylaşım siteleri Web 2.0'dır. Web 3.0 ise semantik web (makinelerin anlamlandırdığı web), yapay zeka entegrasyonu ve merkeziyetsiz blokzincir yapılarıdır.", "tip": "Sosyal Medya = Web 2.0; Semantik Web ve Yapay Zeka = Web 3.0."}], "formuller_ve_kavramlar": [{"term": "DIKW Piramidi", "description": "Veri (Data) -> Enformasyon (Information) -> Bilgi (Knowledge) -> Bilgelik (Wisdom) hiyerarşik bilgi piramididir."}, {"term": "Von Neumann Mimarisi", "description": "Girdi, Çıktı, Bellek ve CPU'dan oluşan, komut ve verinin aynı hafızada tutulduğu modern bilgisayar mimarisi."}, {"term": "ALU (Arithmetic Logic Unit)", "description": "CPU içinde toplama, çıkarma gibi matematiksel ve AND, OR gibi mantıksal işlemleri yapan birim."}, {"term": "Control Unit (CU)", "description": "İşlemcideki komutların getirilmesi, kodunun çözülmesi ve diğer donanımlara sinyal gönderilmesini yöneten kontrol birimi."}, {"term": "Yazmaç (Register)", "description": "İşlemci içerisinde yer alan en hızlı ve en düşük kapasiteli geçici depolama gözleri."}, {"term": "Moore Yasası", "description": "Bir entegre devredeki transistör sayısının yaklaşık her iki yılda bir ikiye katlanacağını öngören kural."}, {"term": "RAM (Random Access Memory)", "description": "Rastgele erişimli, elektrik kesilince içeriği silinen (uçucu), işlemcinin doğrudan haberleştiği ana bellek."}, {"term": "ROM (Read Only Memory)", "description": "Sadece okunabilir, elektrik kesilse dahi silinmeyen, BIOS gibi kritik başlangıç kodlarını barındıran kalıcı bellek."}, {"term": "Sanal Bellek (Virtual Memory)", "description": "Fiziksel RAM dolduğunda işletim sisteminin sabit diskin bir bölümünü RAM gibi kullanması mekanizması."}, {"term": "Kernel (Çekirdek)", "description": "İşletim sisteminin donanım ile doğrudan etkileşime giren, kaynak yönetimini sağlayan en temel çekirdek katmanı."}, {"term": "GUI (Graphical User Interface)", "description": "Kullanıcının bilgisayarla ikonlar, pencereler ve fare işaretçisi ile etkileşime girmesini sağlayan görsel arayüz."}, {"term": "FAT32 / NTFS", "description": "FAT32 en fazla 4GB tek dosya boyutunu desteklerken, NTFS güvenlik, izinler ve dosya şifreleme özellikleri sunar."}, {"term": "Shareware", "description": "Belirli bir süre veya deneme amacıyla ücretsiz kullanılabilen, süre bitiminde lisans ücreti istenen yazılım türü."}, {"term": "Freeware", "description": "Kullanımı tamamen ücretsiz olan ancak kaynak kodları gizli tutulan mülkiyetli yazılım."}, {"term": "SaaS (Software as a Service)", "description": "Yazılımların yerel bilgisayara yüklenmeden bulut sunucular üzerinden internet tarayıcısıyla kullanılması (örn: Office 365)."}, {"term": "ARPANET", "description": "1969'da ABD Savunma Bakanlığı (DARPA) tarafından kurulan, internetin temeli sayılan ilk paket anahtarlamalı ağ."}, {"term": "TCP/IP", "description": "İnternet üzerindeki tüm cihazların haberleşmesini sağlayan standart iletişim protokol takımı (Transmission Control Protocol / Internet Protocol)."}, {"term": "Semantik Web (Web 3.0)", "description": "Web üzerindeki verilerin makineler ve yapay zeka ajanları tarafından anlamlandırılabildiği anlamsal ağ vizyonu."}, {"term": "OSI 7 Katman Modeli", "description": "Ağ haberleşmesini standartlaştıran 7 katman: Fiziksel, Veri Bağı, Ağ, İletim, Oturum, Sunum, Uygulama."}, {"term": "MAC Adresi", "description": "Ağ bağdaştırıcısına (Ethernet/Wi-Fi) üretici tarafından fiziksel olarak kazınan 48 bitlik benzersiz donanım kimlik adresi."}, {"term": "Router (Yönlendirici)", "description": "Farklı ağlar (örn: yerel ağ ile internet) arasında IP adreslerini kullanarak paket yönlendirmesi yapan 3. katman cihazı."}, {"term": "Switch (Anahtar)", "description": "Yerel ağdaki bilgisayarları bağlayan ve paketleri MAC adresine bakarak sadece hedef porta ileten 2. katman cihazı."}, {"term": "CIA Triad", "description": "Bilgi güvenliğinin üç sac ayağı: Confidentiality (Gizlilik), Integrity (Bütünlük) ve Availability (Erişilebilirlik)."}, {"term": "Phishing (Oltalama)", "description": "Güvenilir bir kurum (banka vb.) süsü verilerek kullanıcıların parola ve kredi kartı bilgilerini çalmayı hedefleyen sosyal mühendislik saldırısı."}, {"term": "Algoritma", "description": "Bir sorunu çözmek veya belirli bir amaca ulaşmak için tasarlanan mantıksal adımlar bütünü."}, {"term": "Derleyici (Compiler)", "description": "Yüksek seviyeli programlama diliyle yazılmış kodun tamamını bir kerede makine koduna çeviren program."}, {"term": "Büyük Veri 5V", "description": "Volume (Hacim), Velocity (Hız), Variety (Çeşitlilik), Veracity (Doğruluk) ve Value (Değer)."}, {"term": "IoT (Internet of Things)", "description": "Çeşitli sensörlerle donatılmış fiziksel nesnelerin internete bağlanarak veri alışverişi yapması."}, {"term": "Blokzincir (Blockchain)", "description": "Merkezi bir otoriteye ihtiyaç duymadan, şifreli ve değiştirilemez bloklar halinde veri tutan dağıtık defter teknolojisi."}], "flashcards": [{"id": 1, "unit": 1, "question": "DIKW piramidinde 'işlenmemiş ham gerçekler' olarak tanımlanan kavram nedir?", "answer": "Veri (Data)."}, {"id": 2, "unit": 1, "question": "Tarihteki ilk bilgisayar programcısı kim olarak kabul edilir?", "answer": "Ada Lovelace (Charles Babbage'ın Analitik Motoru için algoritma yazmıştır)."}, {"id": 3, "unit": 1, "question": "1946 yılında geliştirilen ilk genel amaçlı elektronik bilgisayarın adı nedir?", "answer": "ENIAC."}, {"id": 4, "unit": 1, "question": "İkinci kuşak bilgisayarların ortaya çıkmasını sağlayan ve vakum tüplerinin yerini alan icat nedir?", "answer": "Transistör (1947, Bell Labs)."}, {"id": 5, "unit": 1, "question": "Mikroçiplerdeki transistör sayısının her 18-24 ayda iki katına çıkacağını belirten ilke nedir?", "answer": "Moore Yasası (Gordon Moore)."}, {"id": 6, "unit": 2, "question": "Von Neumann mimarisine göre CPU'nun 3 temel iç bileşeni nelerdir?", "answer": "ALU (Aritmetik Mantık Birimi), CU (Denetim Birimi) ve Yazmaçlar (Registers)."}, {"id": 7, "unit": 2, "question": "Elektrik kesildiğinde içerisindeki tüm veriler kaybolan geçici ana bellek hangisidir?", "answer": "RAM (Random Access Memory)."}, {"id": 8, "unit": 2, "question": "İşlemci içinde bulunan ve hiyerarşideki en hızlı, en pahalı bellek türü nedir?", "answer": "Yazmaçlar (Registers)."}, {"id": 9, "unit": 2, "question": "Bilgisayarda 1 Megabyte (MB) kaç Kilobyte'a (KB) eşittir?", "answer": "1024 KB."}, {"id": 10, "unit": 2, "question": "Fabrika çıkışı üzerinde BIOS/UEFI kodlarını barındıran kalıcı bellek türü nedir?", "answer": "ROM (Read Only Memory)."}, {"id": 11, "unit": 3, "question": "İşletim sisteminin donanım ile doğrudan iletişim kuran en temel çekirdek katmanına ne denir?", "answer": "Kernel (Çekirdek)."}, {"id": 12, "unit": 3, "question": "RAM yetersiz kaldığında sabit diskin bir bölümünün RAM gibi kullanılmasına ne ad verilir?", "answer": "Sanal Bellek (Virtual Memory)."}, {"id": 13, "unit": 3, "question": "1991 yılında Linus Torvalds tarafından geliştirilen açık kaynak kodlu işletim sistemi çekirdeği nedir?", "answer": "Linux."}, {"id": 14, "unit": 3, "question": "FAT32 dosya sisteminde tek bir dosyanın maksimum boyutu kaç GB olabilir?", "answer": "4 GB."}, {"id": 15, "unit": 4, "question": "Elektronik tablolama yazılımlarında (Excel) formüller hangi işaretle başlar?", "answer": "= (Eşittir) işareti ile başlar."}, {"id": 16, "unit": 4, "question": "Belirli bir süre ücretsiz deneme imkanı sunup süre sonunda ücret talep eden yazılım lisans türü nedir?", "answer": "Shareware (Paylaşılan yazılım)."}, {"id": 17, "unit": 4, "question": "Yazılımların bilgisayara kurulmadan bulut üzerinden web tarayıcısıyla sunulması modeline ne denir?", "answer": "SaaS (Software as a Service - Hizmet Olarak Yazılım)."}, {"id": 18, "unit": 5, "question": "İnternetin temeli kabul edilen ve 1969'da kurulan ilk askeri araştırma ağı nedir?", "answer": "ARPANET (DARPA)."}, {"id": 19, "unit": 5, "question": "1989 yılında World Wide Web (WWW) standartlarını icat eden bilim insanı kimdir?", "answer": "Tim Berners-Lee (CERN)."}, {"id": 20, "unit": 5, "question": "Kullanıcıların sadece tüketici değil aynı zamanda içerik üreticisi olduğu web nesli hangisidir?", "answer": "Web 2.0 (Sosyal Medya, Bloglar, Vikiler)."}, {"id": 21, "unit": 6, "question": "Yerel ağda gelen veri paketini MAC adresine bakarak sadece ilgili hedefe ileten cihaz hangisidir?", "answer": "Switch (Ağ Anahtarı)."}, {"id": 22, "unit": 6, "question": "OSI 7 Katman Modelinde IP adreslerinin kullanıldığı 3. katman hangisidir?", "answer": "Ağ (Network) Katmanı."}, {"id": 23, "unit": 6, "question": "Bilgi güvenliğinin 3 temel unsuru (CIA Triad) nelerdir?", "answer": "Gizlilik (Confidentiality), Bütünlük (Integrity) ve Erişilebilirlik (Availability)."}, {"id": 24, "unit": 6, "question": "İnsan müdahalesi olmadan ağ bağlantıları üzerinden kendi kendine çoğalan zararlı yazılım türü nedir?", "answer": "Solucan (Worm)."}, {"id": 25, "unit": 7, "question": "Akış şemalarında (Flowchart) karar/koşul veya karşılaştırma işlemleri için hangi sembol kullanılır?", "answer": "Eşkenar Dörtgen (Baklava dilimi)."}, {"id": 26, "unit": 7, "question": "Yazılan kodun tamamını tek bir seferde makine diline çeviren yazılıma ne denir?", "answer": "Derleyici (Compiler)."}, {"id": 27, "unit": 8, "question": "Büyük Verinin (Big Data) 5V bileşeni nelerdir?", "answer": "Volume (Hacim), Velocity (Hız), Variety (Çeşitlilik), Veracity (Doğruluk), Value (Değer)."}, {"id": 28, "unit": 8, "question": "Fiziksel nesnelerin sensörlerle donatılıp internet üzerinden haberleşmesine ne ad verilir?", "answer": "Nesnelerin İnterneti (IoT - Internet of Things)."}, {"id": 29, "unit": 8, "question": "Blokzincir (Blockchain) teknolojisinin arkasındaki gizemli kurucu rumuzu nedir?", "answer": "Satoshi Nakamoto (2008 - Bitcoin teknik raporu)."}, {"id": 30, "unit": 8, "question": "Siber-fiziksel sistemler ve akıllı fabrikalar hangi sanayi devriminin temel özelliğidir?", "answer": "Endüstri 4.0."}], "exams": [{"title": "Vize Deneme Sınavı 1", "filename": "Vize_Deneme_1.md", "questions": [{"id": 1, "unit": 1, "question": "Veri (Data), Enformasyon (Information), Bilgi (Knowledge) ve Bilgelik (Wisdom) hiyerarşisine göre, aşağıdakilerden hangisi doğrudan 'Enformasyon'a örnek gösterilebilir?", "options": ["A) 39", "B) Bir sınıftaki öğrencilerin vize notu ortalamasının 68 olması", "C) Ankara kelimesi", "D) Bir ustanın yıllar süren tecrübeyle edindiği mesleki sezgileri", "E) Bir veri tabanındaki rastgele sayılar"], "correct_answer": "B", "explanation": "Enformasyon, verilerin işlenip anlamlı ve ilişkili hale getirilmiş şeklidir. '39' veya 'Ankara' ham veridir (Data). 'Öğrencilerin vize not ortalamasının 68 olması' ise verilerin işlenerek anlamlı hale geldiği Enformasyondur."}, {"id": 2, "unit": 1, "question": "1946 yılında geliştirilen ve ilk genel amaçlı elektronik bilgisayar kabul edilen sistem aşağıdakilerden hangisidir?", "options": ["A) UNIVAC", "B) Pascaline", "C) ENIAC", "D) EDVAC", "E) Altair 8800"], "correct_answer": "C", "explanation": "ENIAC (Electronic Numerical Integrator and Computer), J. Presper Eckert ve John Mauchly tarafından 1946'da tamamlanan ilk genel amaçlı elektronik bilgisayardır."}, {"id": 3, "unit": 1, "question": "Bilgisayar kuşakları göz önüne alındığında, ikinci kuşak bilgisayarların temel donanım yapıtaşı aşağıdakilerden hangisidir?", "options": ["A) Vakum tüpleri", "B) Transistörler", "C) Entegre devreler", "D) Mikroişlemciler", "E) Yapay zeka çipleri"], "correct_answer": "B", "explanation": "1. Kuşakta Vakum Tüpleri, 2. Kuşakta Transistörler, 3. Kuşakta Entegre Devreler, 4. Kuşakta Mikroişlemciler kullanılmıştır."}, {"id": 4, "unit": 1, "question": "Charles Babbage'ın tasarladığı Analitik Motor için algoritmalar geliştirerek tarihin ilk bilgisayar programcısı unvanını alan bilim insanı kimdir?", "options": ["A) Alan Turing", "B) Ada Lovelace", "C) Grace Hopper", "D) Blaise Pascal", "E) John von Neumann"], "correct_answer": "B", "explanation": "Lord Byron'ın kızı olan Ada Lovelace, Babbage'ın Analitik Motoru için yazdığı Bernoulli sayılarını hesaplayan algoritma sayesinde ilk bilgisayar programcısı sayılır."}, {"id": 5, "unit": 1, "question": "Mikroçip üzerindeki transistör sayısının yaklaşık her 18-24 ayda bir iki katına çıkacağını ifade eden kural aşağıdakilerden hangisidir?", "options": ["A) Amdahl Yasası", "B) Metcalfe Yasası", "C) Moore Yasası", "D) Bell Yasası", "E) Turing İlkesi"], "correct_answer": "C", "explanation": "Intel'in kurucularından Gordon Moore tarafından ortaya atılan kural Moore Yasası olarak bilinir."}, {"id": 6, "unit": 2, "question": "Von Neumann mimarisine göre bilgisayarın Merkezi İşlem Birimi (CPU) içinde yer alan ve matematiksel/mantıksal işlemleri yürüten birim hangisidir?", "options": ["A) Denetim Birimi (Control Unit)", "B) Aritmetik Mantık Birimi (ALU)", "C) RAM", "D) ROM", "E) Sabit Disk"], "correct_answer": "B", "explanation": "Aritmetik ve mantıksal işlemleri doğrudan gerçekleştiren birim ALU'dur (Arithmetic Logic Unit)."}, {"id": 7, "unit": 2, "question": "Bilgisayar mimarisinde en hızlı çalışan ve CPU içerisinde yer alan geçici depolama birimleri aşağıdakilerden hangisidir?", "options": ["A) RAM", "B) ROM", "C) Yazmaçlar (Registers)", "D) Sabit Disk (HDD)", "E) Optik Disk"], "correct_answer": "C", "explanation": "Bellek hiyerarşisinin en tepesinde, işlemci içinde bulunan ve en hızlı erişilen birim Yazmaçlardır (Registers)."}, {"id": 8, "unit": 2, "question": "Aşağıdakilerden hangisi elektrik kesildiğinde üzerindeki verileri kaybeden uçucu (volatile) bir bellektir?", "options": ["A) ROM", "B) EPROM", "C) Sabit Disk", "D) RAM", "E) Flash Bellek"], "correct_answer": "D", "explanation": "RAM geçici (volatile) bir bellektir; bilgisayar kapandığında veya elektrik kesildiğinde tüm içeriği sıfırlanır."}, {"id": 9, "unit": 2, "question": "Aşağıdakilerden hangisi hem giriş hem de çıkış birimi olarak işlev görür?", "options": ["A) Lazer yazıcı", "B) Dokunmatik ekran (Touchscreen)", "C) Klavye", "D) Optik tarayıcı", "E) Barkod okuyucu"], "correct_answer": "B", "explanation": "Dokunmatik ekranlar görüntüyü sundukları için çıkış birimi, dokunarak komut alabildikleri için giriş birimidir."}, {"id": 10, "unit": 2, "question": "İkili sayı sistemine göre 1 Megabyte (MB) tam olarak kaç Byte'a eşittir?", "options": ["A) 1.000 Byte", "B) 10.000 Byte", "C) 1.024 Byte", "D) 1.048.576 Byte", "E) 1.000.000 Byte"], "correct_answer": "D", "explanation": "1 KB = 1024 Byte, 1 MB = 1024 * 1024 = 1.048.576 Byte eder."}, {"id": 11, "unit": 3, "question": "İşletim sisteminin donanım ile doğrudan iletişim kurarak işlemci, bellek ve aygıt yönetimini yürüten en temel çekirdek bileşeni hangisidir?", "options": ["A) Shell (Kabuk)", "B) Kernel (Çekirdek)", "C) GUI", "D) BIOS", "E) Compiler"], "correct_answer": "B", "explanation": "İşletim sisteminin kalbi ve donanıma en yakın çalışan katmanı Kernel (Çekirdek)'dir."}, {"id": 12, "unit": 3, "question": "Fiziksel RAM belleğin yetersiz kaldığı durumlarda işletim sisteminin ikincil depolama aygıtının bir bölümünü RAM gibi kullanması işlemine ne ad verilir?", "options": ["A) Önbellekleme (Caching)", "B) Sanal Bellek (Virtual Memory)", "C) ROM yükleme", "D) Disk birleştirme (Defrag)", "E) RAID mimarisi"], "correct_answer": "B", "explanation": "Sanal bellek (Virtual Memory), RAM yetersizliğinde disk alanının takas (swap/paging) alanı olarak kullanılmasıdır."}, {"id": 13, "unit": 3, "question": "1991 yılında Linus Torvalds tarafından geliştirilen açık kaynak kodlu işletim sistemi çekirdeği aşağıdakilerden hangisidir?", "options": ["A) MS-DOS", "B) Windows NT", "C) Linux", "D) macOS", "E) OS/2"], "correct_answer": "C", "explanation": "Linus Torvalds, 1991 yılında üniversite öğrencisiyken Linux çekirdeğini geliştirmiş ve GPL lisansı altında kamuya açmıştır."}, {"id": 14, "unit": 3, "question": "FAT32 dosya sisteminde tek bir dosyanın alabileceği maksimum dosya boyutu sınırı aşağıdakilerden hangisidir?", "options": ["A) 2 GB", "B) 4 GB", "C) 16 GB", "D) 32 GB", "E) 64 GB"], "correct_answer": "B", "explanation": "FAT32 mimari sınırlaması gereği tek bir dosyanın boyutu en fazla 4 GB (4.294.967.295 byte) olabilir."}, {"id": 15, "unit": 3, "question": "TÜBİTAK tarafından geliştirilen Türkiye'nin yerli Linux dağıtımı aşağıdakilerden hangisidir?", "options": ["A) Pardus", "B) Ubuntu", "C) RedHat", "D) Debian", "E) Fedora"], "correct_answer": "A", "explanation": "TÜBİTAK ULAKBİM tarafından geliştirilen ulusal işletim sistemi dağıtımı Pardus'tur."}, {"id": 16, "unit": 4, "question": "Bir hesap tablosu (Excel) programında formül yazmaya başlarken kullanılan zorunlu karakter aşağıdakilerden hangisidir?", "options": ["A) ?", "B) #", "C) =", "D) %", "E) @"], "correct_answer": "C", "explanation": "Excel ve diğer elektronik tablolarda bir hücreye formül veya fonksiyon girerken '=' (eşittir) işareti kullanılır."}, {"id": 17, "unit": 4, "question": "Belirli bir süre boyunca (örneğin 30 gün) ücretsiz denenmesine izin verilen, süre sonunda tam kullanım için lisans ücreti talep eden yazılım lisans türü nedir?", "options": ["A) Freeware", "B) Shareware", "C) Açık Kaynak Kodlu", "D) Kamu Malı (Public Domain)", "E) Firmware"], "correct_answer": "B", "explanation": "Deneme süreli ve sonradan ücretlendirilen yazılımlar Shareware (Paylaşılan yazılım) olarak adlandırılır."}, {"id": 18, "unit": 4, "question": "Yazılımların kullanıcının bilgisayarına kurulmadan doğrudan internet tarayıcısı üzerinden bulut hizmeti olarak sunulması modeli aşağıdakilerden hangisidir?", "options": ["A) IaaS", "B) PaaS", "C) SaaS", "D) BIOS", "E) API"], "correct_answer": "C", "explanation": "SaaS (Software as a Service - Hizmet Olarak Yazılım), Office 365 veya Google Docs gibi uygulamaların doğrudan webden çalıştırılmasıdır."}, {"id": 19, "unit": 4, "question": "Aşağıdakilerden hangisi bir 'Kelime İşlemci' (Word Processor) yazılımına örnektir?", "options": ["A) MS Access", "B) MS Excel", "C) LibreOffice Writer", "D) MS PowerPoint", "E) MySQL"], "correct_answer": "C", "explanation": "LibreOffice Writer ve MS Word kelime işlemci yazılımlarıdır. Access veritabanı, Excel hesap tablosu, PowerPoint ise sunum yazılımıdır."}, {"id": 20, "unit": 4, "question": "Telif hakkı tamamen sona ermiş veya sahibi tarafından tüm hakları koşulsuz olarak kamuya devredilmiş yazılımlara ne ad verilir?", "options": ["A) Ticari Yazılım", "B) Shareware", "C) Kamu Malı (Public Domain)", "D) Demo Yazılım", "E) Beta Yazılım"], "correct_answer": "C", "explanation": "Hiçbir telif hakkı veya mülkiyet kısıtlaması bulunmayan yazılımlar Public Domain (Kamu Malı) olarak adlandırılır."}]}, {"title": "Vize Deneme Sınavı 2", "filename": "Vize_Deneme_2.md", "questions": [{"id": 1, "unit": 1, "question": "1890 ABD nüfus sayımında delikli kart teknolojisini kullanarak verileri başarıyla işleyen ve daha sonra IBM'e dönüşen şirketi kuran mucit kimdir?", "options": ["A) Charles Babbage", "B) Herman Hollerith", "C) John Atanasoff", "D) Blaise Pascal", "E) Alan Turing"], "correct_answer": "B", "explanation": "Herman Hollerith delikli kart makineleriyle nüfus sayımını birkaç yıldan birkaç aya indirmiş ve kurduğu şirket IBM'in temeli olmuştur."}, {"id": 2, "unit": 1, "question": "Entegre devrelerin (mikroçiplerin) kullanılmasıyla başlayan ve bilgisayarlarda ilk kez klavye ve işletim sistemlerinin devreye girdiği kuşak hangisidir?", "options": ["A) 1. Kuşak", "B) 2. Kuşak", "C) 3. Kuşak", "D) 4. Kuşak", "E) 5. Kuşak"], "correct_answer": "C", "explanation": "Entegre devreler (IC) 3. Kuşak bilgisayarların belirleyici özelliğidir."}, {"id": 3, "unit": 1, "question": "1642 yılında babasının vergi hesaplamalarına yardımcı olmak amacıyla sadece toplama ve çıkarma yapabilen ilk mekanik hesap makinesini geliştiren kimdir?", "options": ["A) Gottfried Leibniz", "B) Blaise Pascal", "C) John Napier", "D) Leonardo da Vinci", "E) René Descartes"], "correct_answer": "B", "explanation": "Blaise Pascal tarafından icat edilen mekanik makineye 'Pascaline' adı verilmiştir."}, {"id": 4, "unit": 1, "question": "Bilgisayarın hem komutlarını hem de üzerinde işlem yapacağı verileri aynı ana bellekte tutmasını öneren ve modern bilgisayarların temelini atan bilim insanı kimdir?", "options": ["A) John von Neumann", "B) Alan Turing", "C) Bill Gates", "D) Steve Jobs", "E) Linus Torvalds"], "correct_answer": "A", "explanation": "John von Neumann, 'Saklı Program' mimarisini geliştirerek veriler ile program komutlarının aynı bellekte tutulmasını sağlamıştır."}, {"id": 5, "unit": 1, "question": "1971 yılında dünyanın ilk tek çipli ticari mikroişlemcisi olan 4004'ü üreten teknoloji şirketi hangisidir?", "options": ["A) IBM", "B) Apple", "C) Intel", "D) Microsoft", "E) Texas Instruments"], "correct_answer": "C", "explanation": "Intel 4004, 1971'de piyasaya sürülen dünyanın ilk 4-bit mikroişlemcisidir."}, {"id": 6, "unit": 2, "question": "CPU içerisindeki komutların çözülmesini, yürütülme sırasını ve diğer donanım birimlerine kontrol sinyalleri gönderilmesini sağlayan birim hangisidir?", "options": ["A) Aritmetik Mantık Birimi (ALU)", "B) Denetim Birimi (Control Unit - CU)", "C) Önbellek (Cache)", "D) RAM", "E) Yazmaç"], "correct_answer": "B", "explanation": "Denetim Birimi (CU), CPU'nun beyni gibidir; komutları çözer ve diğer bileşenleri senkronize yönetir."}, {"id": 7, "unit": 2, "question": "Aşağıdaki bellek türlerinden hangisi 'Morötesi (UV) ışık' altında silinerek tekrar programlanabilme özelliğine sahiptir?", "options": ["A) ROM", "B) PROM", "C) EPROM", "D) EEPROM", "E) DRAM"], "correct_answer": "C", "explanation": "EPROM (Erasable Programmable ROM), penceresinden verilen morötesi ışıkla silinir."}, {"id": 8, "unit": 2, "question": "İşlemci ile ana bellek (RAM) arasındaki hız uçurumunu kapatmak ve sık kullanılan verileri hazır tutmak için kullanılan çok hızlı bellek hangisidir?", "options": ["A) Önbellek (Cache Memory)", "B) Sabit Disk", "C) Optik Disk", "D) Flash Bellek", "E) BIOS"], "correct_answer": "A", "explanation": "L1, L2, L3 önbellekler (Cache), CPU'nun ihtiyaç duyacağı verileri RAM'den önceden çekip işlemci hızında sunar."}, {"id": 9, "unit": 2, "question": "Aşağıdakilerden hangisi yalnızca bir 'Giriş' birimidir?", "options": ["A) Hoparlör", "B) Projeksiyon cihazı", "C) Barkod Okuyucu", "D) Monitör", "E) Çizici (Plotter)"], "correct_answer": "C", "explanation": "Barkod okuyucu bilgisayara dış ortamdan veri aktaran saf bir giriş birimidir. Diğerleri çıkış birimidir."}, {"id": 10, "unit": 2, "question": "1 Gigabyte (GB) kapasite kaç Megabyte (MB)'a eşittir?", "options": ["A) 100", "B) 512", "C) 1.000", "D) 1.024", "E) 2.048"], "correct_answer": "D", "explanation": "Bilgisayarda 2'nin üsleri kuralı gereği 1 GB = 1024 MB'dır."}, {"id": 11, "unit": 3, "question": "Kullanıcının işletim sistemine doğrudan klavyeden yazılı metin komutları girerek talimat verdiği arayüz türü nedir?", "options": ["A) GUI (Grafik Kullanıcı Arayüzü)", "B) CLI (Komut Satırı Arayüzü)", "C) Dokunmatik Arayüz", "D) Biyometrik Arayüz", "E) Web Arayüzü"], "correct_answer": "B", "explanation": "CLI (Command Line Interface), MS-DOS komut istemi veya Linux bash kabuğu gibi metin tabanlı komut arayüzüdür."}, {"id": 12, "unit": 3, "question": "Aşağıdaki işletim sistemi türlerinden hangisi hava yastığı, savunma sanayii ve tıbbi cihazlar gibi 'gecikmeye tahammülü olmayan' sistemlerde kullanılır?", "options": ["A) Masaüstü İşletim Sistemi", "B) Ağ İşletim Sistemi", "C) Gerçek Zamanlı İşletim Sistemi (RTOS)", "D) Dağıtık İşletim Sistemi", "E) Çok Kullanıcılı İşletim Sistemi"], "correct_answer": "C", "explanation": "RTOS (Real-Time Operating System), işlemlerin kesin zaman sınırları içinde hatasız tamamlanmasını garanti eder."}, {"id": 13, "unit": 3, "question": "Windows işletim sistemlerinde dosya güvenliği, kullanıcı izinleri ve günlükleme (journaling) özelliklerini destekleyen gelişmiş dosya sistemi hangisidir?", "options": ["A) FAT16", "B) FAT32", "C) NTFS", "D) ext2", "E) ISO 9660"], "correct_answer": "C", "explanation": "NTFS (New Technology File System), modern Windows sürümlerinin güvenlikli dosya sistemidir."}, {"id": 14, "unit": 3, "question": "'C:\\Universite\\YBS\\Dersler\\notlar.txt' şeklindeki bir dosya gösterimi ne tür bir dosya yoludur?", "options": ["A) Göreceli Yol (Relative Path)", "B) Mutlak Yol (Absolute Path)", "C) Ağ Yolu (UNC Path)", "D) Sanal Yol", "E) Köksüz Yol"], "correct_answer": "B", "explanation": "Kök sürücü harfinden (C:\\) başlayarak hedefe kadar tüm hiyerarşiyi gösteren yola Mutlak Yol (Absolute Path) denir."}, {"id": 15, "unit": 3, "question": "Aşağıdakilerden hangisi bir işletim sisteminin temel görevlerinden biri değildir?", "options": ["A) İşlemci yönetimi ve görev zamanlama", "B) Bellek tahsisi ve yönetimi", "C) Dosya ve dizin organizasyonu", "D) Muhasebe bilançosu hazırlama", "E) Giriş/Çıkış aygıtlarının denetimi"], "correct_answer": "D", "explanation": "Muhasebe bilançosu hazırlamak bir uygulama yazılımının (ERP veya muhasebe programı) görevidir; işletim sisteminin donanım yönetimi görevi değildir."}, {"id": 16, "unit": 4, "question": "Kullanımı tamamen ücretsiz olan ancak kaynak kodları kapalı tutulan yazılım lisans modeli aşağıdakilerden hangisidir?", "options": ["A) Shareware", "B) Freeware", "C) Açık Kaynak Kodlu", "D) GNU GPL", "E) Ticari Yazılım"], "correct_answer": "B", "explanation": "Freeware (Ücretsiz yazılım), son kullanıcıya bedelsiz sunulur ancak kaynak kodları gizlidir (örn: Adobe Reader)."}, {"id": 17, "unit": 4, "question": "Kaynak kodu herkesin erişimine açık olan, üzerinde değişiklik yapılıp yeniden dağıtılabilen yazılımlara ne ad verilir?", "options": ["A) Açık Kaynak Kodlu Yazılım", "B) Mülkiyetli Yazılım", "C) Demo Yazılım", "D) Casus Yazılım", "E) Kısıtlı Yazılım"], "correct_answer": "A", "explanation": "Open Source (Açık Kaynak Kodlu) yazılımların kaynak kodu açıktır ve denetlenebilir/geliştirilebilir."}, {"id": 18, "unit": 4, "question": "Aşağıdakilerden hangisi bir 'İlişkisel Veritabanı Yönetim Sistemi' (RDBMS) örneğidir?", "options": ["A) MS Word", "B) MS Excel", "C) MySQL", "D) Photoshop", "E) VLC Player"], "correct_answer": "C", "explanation": "MySQL, Oracle, PostgreSQL ve MS Access ilişkisel veritabanı yönetim sistemleridir."}, {"id": 19, "unit": 4, "question": "Bir elektronik tablolama programında (Excel) A1'den A5'e kadar olan hücrelerin toplamını hesaplayan formül hangisidir?", "options": ["A) =TOPLA(A1+A5)", "B) =TOPLA(A1:A5)", "C) =SUM(A1;A5)", "D) =ORTALAMA(A1:A5)", "E) =ÇARPIM(A1-A5)"], "correct_answer": "B", "explanation": "İki nokta üst üste ':' aralık belirtir. =TOPLA(A1:A5) formülü A1 ile A5 arasındaki tüm hücreleri toplar."}, {"id": 20, "unit": 4, "question": "Bir şirketin insan kaynakları, üretim, muhasebe ve satış gibi tüm departmanlarını tek bir entegre yazılım çatısında toplayan sistemlere ne ad verilir?", "options": ["A) CRM (Müşteri İlişkileri Yönetimi)", "B) ERP (Kurumsal Kaynak Planlaması)", "C) CAD (Bilgisayar Destekli Tasarım)", "D) CAM (Bilgisayar Destekli Üretim)", "E) CMS (İçerik Yönetim Sistemi)"], "correct_answer": "B", "explanation": "ERP (Enterprise Resource Planning - Kurumsal Kaynak Planlaması), bir işletmenin tüm iş süreçlerini ve verilerini tek çatı altında birleştiren entegre uygulama yazılımıdır."}]}, {"title": "Final Deneme Sınavı 1", "filename": "Final_Deneme_1.md", "questions": [{"id": 1, "unit": 1, "question": "(Vize Tekrarı) DIKW piramidinde en üstte yer alan ve bilgiyi doğru ve etik şekilde uygulayabilme becerisini ifade eden kavram nedir?", "options": ["A) Bilgi (Knowledge)", "B) Enformasyon (Information)", "C) Bilgelik (Wisdom)", "D) Veri (Data)", "E) Sezgi"], "correct_answer": "C", "explanation": "DIKW piramidinin zirvesinde Bilgelik (Wisdom) yer alır."}, {"id": 2, "unit": 2, "question": "(Vize Tekrarı) İşlemci saat hızı (Clock Speed) genellikle hangi birimle ölçülür?", "options": ["A) Byte", "B) Gigahertz (GHz)", "C) DPI", "D) Piksel", "E) Watt"], "correct_answer": "B", "explanation": "İşlemcinin saniyedeki çevrim hızı Hertz (GHz) ile ölçülür."}, {"id": 3, "unit": 3, "question": "(Vize Tekrarı) Birden fazla görevin işlemci tarafından belirli zaman dilimlerinde sırayla yürütülerek aynı anda çalışıyormuş gibi hissettirilmesine ne ad verilir?", "options": ["A) Multitasking (Çok Görevlilik)", "B) Multiprocessing", "C) Virtual Memory", "D) Booting", "E) Paging"], "correct_answer": "A", "explanation": "Multitasking (Çok görevlilik), işletim sisteminin birden çok uygulamayı eşzamanlı gibi çalıştırmasıdır."}, {"id": 4, "unit": 4, "question": "(Vize Tekrarı) GNU Genel Kamu Lisansı (GPL) aşağıdaki yazılım kategorilerinden hangisinde yaygın olarak kullanılır?", "options": ["A) Mülkiyetli Yazılım", "B) Açık Kaynak Kodlu Yazılım", "C) Shareware", "D) Firmware", "E) Demo Yazılım"], "correct_answer": "B", "explanation": "GNU GPL, açık kaynak kodlu yazılımların özgür kalmasını güvence altına alan en popüler lisanstır."}, {"id": 5, "unit": 5, "question": "1969 yılında ABD Savunma Bakanlığı tarafından başlatılan ve internetin atası sayılan ilk ağ projesi aşağıdakilerden hangisidir?", "options": ["A) BITNET", "B) NSFNET", "C) ARPANET", "D) USENET", "E) ETHERNET"], "correct_answer": "C", "explanation": "İnternetin temeli DARPA tarafından kurulan ARPANET'tir."}, {"id": 6, "unit": 5, "question": "1989 yılında CERN laboratuvarlarında World Wide Web (WWW) standartlarını geliştiren İngiliz bilim insanı kimdir?", "options": ["A) Alan Turing", "B) Vint Cerf", "C) Tim Berners-Lee", "D) Robert Kahn", "E) Marc Andreessen"], "correct_answer": "C", "explanation": "Tim Berners-Lee, HTML, HTTP ve URL teknolojilerini geliştirerek WWW'yi kurmuştur."}, {"id": 7, "unit": 5, "question": "Kullanıcıların sadece okuyucu olmakla kalmayıp bloglar, sosyal ağlar ve vikiler üzerinden bizzat içerik ürettiği web dönemi hangisidir?", "options": ["A) Web 1.0", "B) Web 2.0", "C) Web 3.0", "D) Web 4.0", "E) Dark Web"], "correct_answer": "B", "explanation": "Etkileşimli ve kullanıcı odaklı içerik üretimi Web 2.0 ile başlamıştır."}, {"id": 8, "unit": 5, "question": "Mobil iletişim nesillerinden hangisi ile 'Görüntülü Görüşme' ve 'Mobil İnternet' kitlesel olarak hayatımıza girmiştir?", "options": ["A) 1G", "B) 2G", "C) 3G", "D) 4G", "E) 5G"], "correct_answer": "C", "explanation": "3G mobil genişbant internet ve görüntülü arama dönemini başlatmıştır."}, {"id": 9, "unit": 6, "question": "Bir kurumun veya evin yerel ağındaki cihazları bağlayan, gelen veri paketini MAC adresini analiz ederek doğrudan hedef porta ileten 2. katman cihazı hangisidir?", "options": ["A) Hub", "B) Switch (Ağ Anahtarı)", "C) Modem", "D) Tekrarlayıcı (Repeater)", "E) Güvenlik Duvarı"], "correct_answer": "B", "explanation": "Switch, MAC adres tablosunu kullanarak veriyi yalnızca hedef cihaza iletir."}, {"id": 10, "unit": 6, "question": "OSI 7 Katman Modelinde IP adreslerinin kullanıldığı ve farklı ağlar arasında paket yönlendirmesinin (routing) yapıldığı katman hangisidir?", "options": ["A) Fiziksel Katman", "B) Veri Bağı Katmanı", "C) Ağ (Network) Katmanı", "D) İletim Katmanı", "E) Uygulama Katmanı"], "correct_answer": "C", "explanation": "Ağ (Network) Katmanı (3. Katman) IP protokolünün ve yönlendiricilerin çalıştığı katmandır."}, {"id": 11, "unit": 6, "question": "Bilgi güvenliğinin 3 temel ilkesi (CIA Triad) arasında aşağıdakilerden hangisi yer almaz?", "options": ["A) Gizlilik (Confidentiality)", "B) Bütünlük (Integrity)", "C) Erişilebilirlik (Availability)", "D) Maliyet (Cost)", "E) Hepsi güvenlik unsurudur"], "correct_answer": "D", "explanation": "CIA Triad: Gizlilik, Bütünlük ve Erişilebilirliktir. Maliyet bu üçlüye dahil değildir."}, {"id": 12, "unit": 6, "question": "İnsan müdahalesi veya bir kullanıcı çalıştırması gerekmeden ağdaki açıkları kullanarak kendi kendini kopyalayan zararlı yazılım türü nedir?", "options": ["A) Virüs", "B) Solucan (Worm)", "C) Truva Atı (Trojan)", "D) Casus Yazılım (Spyware)", "E) Adware"], "correct_answer": "B", "explanation": "Solucanlar (Worms), virüslerden farklı olarak bağımsız dosyalardır ve ağda kendiliğinden yayılırlar."}, {"id": 13, "unit": 6, "question": "Kullanıcının bilgisayarındaki dosyaları şifreleyerek erişimi engelleyen ve şifreyi çözmek için para talep eden siber tehdit hangisidir?", "options": ["A) Ransomware (Fidye Yazılımı)", "B) Keylogger", "C) Rootkit", "D) Phishing", "E) Spam"], "correct_answer": "A", "explanation": "Ransomware (Fidye yazılımı), verileri rehin alıp fidye talep eden zararlı yazılımdır."}, {"id": 14, "unit": 7, "question": "Bir problemin çözümü için adım adım tanımlanmış, sonlu ve kesin kurallardan oluşan işlem basamakları dizisine ne ad verilir?", "options": ["A) Derleyici", "B) Algoritma", "C) Akış Şeması", "D) İşletim Sistemi", "E) Değişken"], "correct_answer": "B", "explanation": "Problemi adım adım çözme mantığına Algoritma denir."}, {"id": 15, "unit": 7, "question": "Akış şemalarında (Flowchart) karar/koşul veya karşılaştırma işlemleri için hangi geometrik sembol kullanılır?", "options": ["A) Oval", "B) Dikdörtgen", "C) Eşkenar Dörtgen (Baklava)", "D) Paralelkenar", "E) Daire"], "correct_answer": "C", "explanation": "Karar ve koşul yapıları (if/else) Eşkenar Dörtgen içinde gösterilir."}, {"id": 16, "unit": 7, "question": "Yüksek seviyeli bir dille yazılmış kaynak kodları satır satır okuyarak anında çalıştıran yazılım türü hangisidir?", "options": ["A) Derleyici (Compiler)", "B) Yorumlayıcı (Interpreter)", "C) Bağlayıcı (Linker)", "D) İşletim Sistemi", "E) Yükleyici (Loader)"], "correct_answer": "B", "explanation": "Kodu satır satır anlık çalıştıran yazılımlara Yorumlayıcı (Interpreter) denir (Python, JS vb.)."}, {"id": 17, "unit": 8, "question": "Büyük Veri (Big Data) kavramını tanımlayan 5V bileşeni arasında aşağıdakilerden hangisi yer almaz?", "options": ["A) Volume (Hacim)", "B) Velocity (Hız)", "C) Variety (Çeşitlilik)", "D) Vector (Vektör)", "E) Value (Değer)"], "correct_answer": "D", "explanation": "5V: Volume, Velocity, Variety, Veracity ve Value'dur. Vector bunlardan biri değildir."}, {"id": 18, "unit": 8, "question": "Fiziksel nesnelerin (sensörler, makineler, akıllı ev aletleri) internet ağı üzerinden birbirleriyle veri alışverişi yapmasına ne ad verilir?", "options": ["A) Nesnelerin İnterneti (IoT)", "B) Blokzincir", "C) Derin Öğrenme", "D) Sanal Gerçeklik", "E) Kuantum Bilişim"], "correct_answer": "A", "explanation": "Fiziksel nesnelerin internete bağlanması 'Internet of Things (IoT)' olarak adlandırılır."}, {"id": 19, "unit": 8, "question": "Merkezi bir otoriteye ihtiyaç duymadan, dağıtık ve kriptografik olarak birbirine bağlı bloklar halinde güvenli veri tutulmasını sağlayan teknoloji hangisidir?", "options": ["A) Blokzincir (Blockchain)", "B) Bulut Bilişim", "C) İlişkisel Veritabanı", "D) FTP", "E) DNS"], "correct_answer": "A", "explanation": "Blokzincir (Blockchain), dağıtık defter teknolojisidir."}, {"id": 20, "unit": 8, "question": "Siber-fiziksel sistemler, nesnelerin interneti ve akıllı fabrikalar vizyonunu içeren sanayi devrimi aşağıdakilerden hangisidir?", "options": ["A) Endüstri 1.0", "B) Endüstri 2.0", "C) Endüstri 3.0", "D) Endüstri 4.0", "E) Endüstri 5.0"], "correct_answer": "D", "explanation": "Endüstri 4.0, akıllı fabrikalar ve siber-fiziksel sistemlerin entegrasyonunu ifade eder."}]}, {"title": "Final Deneme Sınavı 2", "filename": "Final_Deneme_2.md", "questions": [{"id": 1, "unit": 1, "question": "(Vize Tekrarı) İlk mekanik hesap makinesi olan Pascaline'i geliştiren Fransız matematikçi kimdir?", "options": ["A) Gottfried Leibniz", "B) Blaise Pascal", "C) Charles Babbage", "D) René Descartes", "E) Joseph Marie Jacquard"], "correct_answer": "B", "explanation": "Blaise Pascal 1642'de Pascaline'i geliştirmiştir."}, {"id": 2, "unit": 2, "question": "(Vize Tekrarı) Aşağıdaki bellek türlerinden hangisi elektrik kesildiğinde üzerindeki veriyi koruyan kalıcı bir bellektir?", "options": ["A) SRAM", "B) DRAM", "C) ROM", "D) Yazmaç (Register)", "E) L1 Önbellek"], "correct_answer": "C", "explanation": "ROM (Read Only Memory) kalıcı (non-volatile) bir bellektir."}, {"id": 3, "unit": 3, "question": "(Vize Tekrarı) Linux işletim sisteminin kurucusu kimdir?", "options": ["A) Steve Wozniak", "B) Bill Gates", "C) Linus Torvalds", "D) Ken Thompson", "E) Richard Stallman"], "correct_answer": "C", "explanation": "Linux çekirdeğini 1991'de Linus Torvalds yazmıştır."}, {"id": 4, "unit": 4, "question": "(Vize Tekrarı) Bir kurumda müşterilerle olan satış, pazarlama ve teknik destek süreçlerini takip etmek için kullanılan yazılımlara ne ad verilir?", "options": ["A) CRM (Müşteri İlişkileri Yönetimi)", "B) ERP", "C) CAD", "D) DBMS", "E) SCADA"], "correct_answer": "A", "explanation": "CRM (Customer Relationship Management), müşteri odaklı iş süreçlerini yöneten yazılımdır."}, {"id": 5, "unit": 5, "question": "İnternetin omurgasını oluşturan ve paketlerin hedefe güvenilir şekilde iletilmesini sağlayan protokol takımı hangisidir?", "options": ["A) HTTP", "B) FTP", "C) TCP/IP", "D) SMTP", "E) POP3"], "correct_answer": "C", "explanation": "TCP/IP internetin ana protokol kümesidir."}, {"id": 6, "unit": 5, "question": "Makinelerin verileri anlayabildiği, yapay zeka destekli ve anlamsal ilişkilerin kurulduğu web nesli hangisidir?", "options": ["A) Web 1.0", "B) Web 2.0", "C) Web 3.0 (Semantik Web)", "D) Web 1.5", "E) Statik Web"], "correct_answer": "C", "explanation": "Web 3.0, Semantik (anlamsal) web ve yapay zeka odaklıdır."}, {"id": 7, "unit": 5, "question": "1 milisaniyenin altında gecikme süresi ve gigabit seviyesinde veri transfer hızı sunan en güncel hücresel teknoloji hangisidir?", "options": ["A) 2G", "B) 3G", "C) 4G", "D) 5G", "E) GPRS"], "correct_answer": "D", "explanation": "5G ultra düşük gecikme ve devasa hız sunar."}, {"id": 8, "unit": 5, "question": "Bir firmanın kendi bünyesinde fiziksel sunucu barındırmayıp Amazon AWS veya Google Cloud'dan sanal sunucu ve depolama alanı kiralaması hangi bulut modelidir?", "options": ["A) SaaS", "B) PaaS", "C) IaaS (Altyapı Hizmeti)", "D) DaaS", "E) CaaS"], "correct_answer": "C", "explanation": "Donanım, sunucu ve ağ altyapısının kiralanması IaaS (Infrastructure as a Service) olarak adlandırılır."}, {"id": 9, "unit": 6, "question": "Tüm bilgisayarların merkezi bir cihaza (Switch veya Hub) bağlandığı ve günümüzde en yaygın kullanılan yerel ağ topolojisi hangisidir?", "options": ["A) Yol (Bus) Topolojisi", "B) Halka (Ring) Topolojisi", "C) Yıldız (Star) Topolojisi", "D) Örgü (Mesh) Topolojisi", "E) Karmaşık Topoloji"], "correct_answer": "C", "explanation": "Yıldız topolojisi (Star), kablo kopmalarının tüm ağı çökertmemesi ve yönetim kolaylığı nedeniyle en yaygın topolojidir."}, {"id": 10, "unit": 6, "question": "Ağ bağdaştırıcı kartına (Ethernet kartı) fabrikada donanımsal olarak atanan 48 bitlik fiziksel adrese ne ad verilir?", "options": ["A) IP Adresi", "B) Port Numarası", "C) MAC Adresi", "D) URL Adresi", "E) DNS Adresi"], "correct_answer": "C", "explanation": "Fiziksel donanım adresi MAC (Media Access Control) adresidir."}, {"id": 11, "unit": 6, "question": "Bir banka gibi görünerek sahte web sitesi veya e-posta aracılığıyla kullanıcıların şifrelerini çalmayı amaçlayan siber saldırı türü nedir?", "options": ["A) DDoS", "B) Oltalama (Phishing)", "C) SQL Injection", "D) Man in the Middle", "E) Brute Force"], "correct_answer": "B", "explanation": "Sahte yemlerle kimlik avı yapılmasına Phishing (Oltalama) denir."}, {"id": 12, "unit": 6, "question": "Bir web sunucusuna binlerce sahte istek göndererek sunucunun kilitlenmesini ve gerçek kullanıcılara hizmet verememesini sağlayan saldırı türü hangisidir?", "options": ["A) DoS / DDoS (Hizmet Engelleme)", "B) Truva Atı", "C) Solucan", "D) Ransomware", "E) Casus Yazılım"], "correct_answer": "A", "explanation": "DDoS (Distributed Denial of Service), dağıtık hizmet engelleme saldırısıdır."}, {"id": 13, "unit": 7, "question": "Akış şemalarında (Flowchart) kullanıcıdan veri girişi veya ekrana veri çıkışı işlemlerini temsil eden sembol hangisidir?", "options": ["A) Dikdörtgen", "B) Paralelkenar", "C) Oval", "D) Daire", "E) Baklava"], "correct_answer": "B", "explanation": "Girdi ve çıktı işlemleri Paralelkenar sembolü ile ifade edilir."}, {"id": 14, "unit": 7, "question": "Aşağıdaki programlama dillerinden hangisi insan diline en yakın, donanımdan bağımsız 'Yüksek Düzeyli' dillere örnektir?", "options": ["A) Makine Dili (0-1)", "B) Assembly Dili", "C) Python", "D) Mikroişlemci Kodu", "E) BIOS Kodu"], "correct_answer": "C", "explanation": "Python yüksek düzeyli bir dildir; öğrenilmesi ve okunması insan konuşma diline çok yakındır."}, {"id": 15, "unit": 7, "question": "Nesne Yönelimli Programlamada (OOP) bir sınıfın özelliklerini ve metotlarını başka bir sınıfın miras almasına ne ad verilir?", "options": ["A) Kapsülleme (Encapsulation)", "B) Kalıtım (Inheritance)", "C) Çok Biçimlilik (Polymorphism)", "D) Soyutlama (Abstraction)", "E) Derleme"], "correct_answer": "B", "explanation": "Bir üst sınıftan özelliklerin alt sınıfa aktarılmasına Kalıtım (Inheritance) denir."}, {"id": 16, "unit": 8, "question": "1950 yılında bir makinenin insan gibi düşünüp düşünemediğini anlamak için geliştirilen ünlü test aşağıdakilerden hangisidir?", "options": ["A) Turing Testi", "B) Voight-Kampff Testi", "C) Babbage Deneyi", "D) Moore Kriteri", "E) Von Neumann Testi"], "correct_answer": "A", "explanation": "Alan Turing tarafından önerilen makine zekası testi Turing Testi'dir."}, {"id": 17, "unit": 8, "question": "Makine öğrenmesinde etiketsiz veriler arasındaki benzerlikleri bularak kendi kendine gruplama yapılması hangi öğrenme türüdür?", "options": ["A) Denetimli Öğrenme (Supervised)", "B) Denetimsiz Öğrenme (Unsupervised)", "C) Pekiştirmeli Öğrenme (Reinforcement)", "D) Kural Tabanlı Öğrenme", "E) Manuel Öğrenme"], "correct_answer": "B", "explanation": "Etiketsiz verilerden örüntü çıkarma ve kümeleme Denetimsiz Öğrenme'dir."}, {"id": 18, "unit": 8, "question": "Gerçek dünya görüntüsünün üzerine bilgisayar tarafından üretilen dijital verilerin bindirilmesi teknolojisine ne ad verilir?", "options": ["A) Sanal Gerçeklik (VR)", "B) Artırılmış Gerçeklik (AR)", "C) Kuantum Bilişim", "D) Telekonferans", "E) Hologram"], "correct_answer": "B", "explanation": "Fiziksel dünyaya sanal öğeler ekleme teknolojisi Artırılmış Gerçekliktir (Augmented Reality - AR)."}, {"id": 19, "unit": 8, "question": "Bitcoin ve kripto paraların arkasındaki dağıtık defter teknolojisi hangisidir?", "options": ["A) Blokzincir (Blockchain)", "B) Yapay Sinir Ağı", "C) Büyük Veri", "D) Bulut Bilişim", "E) Sanallaştırma"], "correct_answer": "A", "explanation": "Kripto varlıkların temel altyapısı Blokzincir (Blockchain) teknolojisidir."}, {"id": 20, "unit": 8, "question": "Nesnelerin İnterneti (IoT) kavramını 1999 yılında ilk kez kullanan kişi kimdir?", "options": ["A) Kevin Ashton", "B) Tim Berners-Lee", "C) Elon Musk", "D) Steve Jobs", "E) Vint Cerf"], "correct_answer": "A", "explanation": "IoT kavramını 1999'da RFID teknolojisi sunumunda ilk kullanan kişi Kevin Ashton'dır."}]}]}, "genel_muhasebe": {"course_name": "GENEL MUHASEBE", "course_code": "MUH101U", "faculty": "İşletme / İktisat Fakültesi - Yönetim Bilişim Sistemleri (YBS)", "term": "1. Sınıf Güz Dönemi", "description": "Temel muhasebe kavramları, bilanço eşitliği, hesap işleyiş kuralları, dönen ve duran varlıklar, yabancı kaynaklar, öz kaynaklar, gelir tablosu hesapları ve dönem sonu envanter işlemleri.", "units": [{"unit_number": 1, "title": "Muhasebeye Giriş", "is_vize": true, "key_topics": ["Muhasebenin Tanımı ve İşlevleri", "Temel Muhasebe Eşitliği", "Finansal Tablolar (Bilanço ve Gelir Tablosu)", "Temel Muhasebe Kavramları"], "hap_bilgiler": ["Muhasebenin 4 Temel İşlevi: 1. Kaydetme (Yevmiye Defteri - ilk ve temel işlev), 2. Sınıflandırma (Büyük Defter / Defter-i Kebir), 3. Özetleme (Mizanlar, Bilanço, Gelir Tablosu), 4. Analiz ve Yorumlama (Rasyolar ve karar vericilere raporlama).", "Temel Muhasebe (Bilanço) Eşitliği: Varlıklar (Aktif) = Kaynaklar (Pasif). Detaylı: Varlıklar = Yabancı Kaynaklar (Borçlar) + Öz Kaynaklar (Sermaye).", "Bilanço: Bir işletmenin belirli bir tarihteki (anlık fotoğraf) varlıklarını ve bu varlıkların sağlandığı kaynakları gösteren temel mali tablodur. Sol taraf AKTİF (Dönen ve Duran Varlıklar), sağ taraf PASİF (Kısa Vadeli Yabancı Kaynaklar, Uzun Vadeli Yabancı Kaynaklar, Öz Kaynaklar).", "Gelir Tablosu: Bir işletmenin belirli bir dönemde elde ettiği tüm gelirler ile katlandığı tüm giderleri ve bunların sonucunda oluşan Dönem Net Kârı veya Zararını gösteren dinamik tablodur (Gelirler - Giderler = Kâr veya Zarar).", "12 Temel Muhasebe Kavramı:", "  - Sosyal Sorumluluk: Muhasebenin belli kişi veya grupların değil, tüm toplumun çıkarlarını gözeterek dürüst ve tarafsız yürütülmesidir (En üst kavramdır).", "  - Kişilik Kavramı: İşletmenin, sahiplerinden ve ortaklarından ayrı bağımsız bir hukuki ve iktisadi kişiliğe sahip olmasıdır.", "  - İşletmenin Sürekliliği: İşletmenin faaliyetlerinin herhangi bir zaman sınırına bağlı olmaksızın sonsuza kadar süreceği varsayımıdır (Maliyet esası bu kavrama dayanır).", "  - Dönemsellik Kavramı: İşletmenin sınırsız ömrünün belirli dönemlere (genellikle 1 takvim yılı) bölünmesi, her dönemin gelir ve giderinin o döneme ait olmasıdır (Amortisman, reeskont ve tahakkuk kayıtları bu kavrama dayanır).", "  - Parayla Ölçülme: Muhasebe işlemlerinin ortak bir ulusal para birimiyle kaydedilmesidir.", "  - Maliyet Esası: Para mevcudu ve alacaklar hariç, edinilen varlıkların maliyet bedeliyle defterlere kaydedilmesidir.", "  - Tarafsızlık ve Belgelendirme: Kayıtların objektif belgelere (fatura, makbuz, çek) dayandırılması zorunluluğudur.", "  - Tutarlılık: Muhasebe politikalarının ve değerleme yöntemlerinin dönemden döneme değiştirilmeden uygulanmasıdır (Karşılaştırılabilirliği sağlar).", "  - Tam Açıklama: Mali tabloların karar vericilerin anlayabileceği açıklık ve detayda hazırlanmasıdır.", "  - İhtiyatlılık: Olası riskler, zararlar ve giderler için karşılık ayrılması, ancak gerçekleşmemiş kârların kaydedilmemesidir.", "  - Önemlilik: Bir hesap veya tutarın karar vericilerin kararlarını etkileyecek ağırlıkta olması durumunda mutlaka ayrı gösterilmesidir.", "  - Özün Önceliği: İşlemlerin biçimsel hukuki yapısından ziyade iktisadi ve mali özünün esas alınmasıdır (Örn: Çeklerin vadeli düzenlenmesi durumunda senet gibi değerlenmesi)."]}, {"unit_number": 2, "title": "Bilgi İşleme ve Muhasebe Süreci", "is_vize": true, "key_topics": ["Hesap Kavramı ve İşleyiş Kuralları", "Muhasebe Fişleri", "Yasal Defterler", "Mizanlar", "Muhasebe Döngüsü"], "hap_bilgiler": ["Hesap İşleyiş Kuralları (ALTIN KURAL):", "  - Aktif Karakterli Hesaplar (Varlıklar ve Giderler): İlk kayıt ve artışlar BORCA yazılır. Azalışlar ALACAĞA yazılır. Borç kalanı verir veya kalan vermez (sıfır olur). Kesinlikle alacak kalanı veremez!", "  - Pasif Karakterli Hesaplar (Kaynaklar ve Gelirler): İlk kayıt ve artışlar ALACAĞA yazılır. Azalışlar BORCA yazılır. Alacak kalanı verir veya sıfır olur. Kesinlikle borç kalanı veremez!", "  - Düzenleyici Hesaplar: Yanında eksi (-) olan hesaplardır. Aktifi Düzenleyici hesaplar bilançonun aktifinde yer alır ancak pasif karakterlidir (artış alacağa). Pasifi Düzenleyici hesaplar pasifte yer alır ancak aktif karakterlidir (artış borca).", "Muhasebe Fişleri: 1. Kasa Tahsil Fişi (Kasaya nakit girişi olduğunda), 2. Kasa Tediye Fişi (Kasadan nakit çıkışı olduğunda), 3. Mahsup Fişi (İçinde kesinlikle kasa hesabı geçmeyen, nakit hareketsiz işlemler için düzenlenir).", "Yasal Defterler: Yevmiye Defteri (İşlemlerin tarih sırasına göre madde madde kaydedildiği günlük defter), Defter-i Kebir (Büyük Defter - yevmiyedeki kayıtların hesaplar bazında sınıflandırıldığı defter), Envanter Defteri (Dönem başı ve dönem sonu sayım sonuçlarının yazıldığı defter).", "Mizan Çeşitleri: 1. Aylık Mizan (Her ay sonunda yevmiye ile büyük defter uyumunu kontrol eder), 2. Genel Geçici Mizan (Aralık ayı sonunda, dönem sonu envanter işlemlerine başlamadan önce çıkarılır), 3. Kesin Mizan (Dönem sonu envanter ve düzeltme kayıtları tamamlandıktan sonra, bilançodan hemen önce çıkarılan nihai kontrol cetvelidir).", "Muhasebe Süreci Sıralaması: Açılış Bilançosu -> Açılış Yevmiye Kaydı -> Dönem İçi İşlemler -> Aylık Mizanlar -> Genel Geçici Mizan -> Envanter İşlemleri (Sayım, değerleme, amortisman) -> Kesin Mizan -> Finansal Tablolar (Bilanço & Gelir Tablosu) -> Kapanış Kayıtları."]}, {"unit_number": 3, "title": "Dönen Varlıklar", "is_vize": true, "key_topics": ["10 Hazır Değerler", "11 Menkul Kıymetler", "12 Ticari Alacaklar", "15 Stoklar ve Stok Değerleme", "19 KDV Hesapları"], "hap_bilgiler": ["Dönen Varlıklar (1 Grubu): Bir yıl veya normal faaliyet dönemi içinde paraya çevrilmesi veya tüketilmesi öngörülen varlıklardır.", "10 Hazır Değerler:", "  - 100 Kasa: Kasa mevcudu fiili sayımdan çok çıkarsa '397 Sayım ve Tesellüm Fazlaları' alacaklandırılır; eksik çıkarsa '197 Sayım ve Tesellüm Noksanları' borçlandırılır.", "  - 101 Alınan Çekler: Müşteriden alınan çekler portföyde iken bu hesapta izlenir.", "  - 102 Bankalar: Vadeli veya vadesiz banka mevduatları.", "  - 103 Verilen Çekler ve Ödeme Emirleri (-): İşletmenin üçüncü kişilere keşide ettiği çeklerdir. Aktifte yer almasına rağmen pasif karakterli (düzenleyici) bir hesaptır! Verildiğinde ALACAKLANDIRILIR.", "12 Ticari Alacaklar:", "  - 120 Alıcılar: Veresiye (açık hesap) mal veya hizmet satışından doğan senetsiz alacaklar. Mal satıldığında 120 BORÇLU, 600 Yurtiçi Satışlar ALACAKLI kaydedilir.", "  - 121 Alacak Senetleri: Müşteriden alınan bonolar ve poliçeler.", "  - 122 Alacak Senetleri Reeskontu (-): Senetli alacakların dönem sonundaki peşin değerine indirgenmesi (aktifi düzenleyici).", "  - 128 Şüpheli Ticari Alacaklar ve 129 Şüpheli Ticari Alacaklar Karşılığı (-): Vadesinde ödenmeyen ve yasal takibe intikal eden alacaklar.", "15 Stoklar:", "  - 153 Ticari Mallar: Üzerinde hiçbir değişiklik yapılmadan satılmak üzere alınan mallardır.", "  - Sürekli Envanter Yöntemi: Her satış anında satış kaydının hemen altına maliyet kaydı yapılır: 621 Satılan Ticari Mallar Maliyeti BORÇLU, 153 Ticari Mallar ALACAKLI.", "  - Aralıklı Envanter Yöntemi: Satış anında maliyet kaydı yapılmaz. Dönem sonunda fiili sayım yapılır ve formülle hesaplanır: STMM = Dönem Başı Mal Mevcudu + Dönem İçi Net Alışlar - Dönem Sonu Mal Mevcudu.", "  - Stok Değerleme Yöntemleri: FIFO (İlk Giren İlk Çıkar - enflasyonist ortamda dönem sonu stokları yüksek, STMM düşük, kâr yüksek çıkar), Ağırlıklı Ortalama Maliyet.", "KDV Hesapları:", "  - 191 İndirilecek KDV: Mal ve hizmet satın alırken ödenen KDV (Aktif hesap, Borçlu çalışır).", "  - 391 Hesaplanan KDV: Mal ve hizmet satarken müşteriden tahsil edilen KDV (Pasif hesap, Alacaklı çalışır).", "  - Ay Sonu KDV Mahsubu: 391 > 191 ise aradaki fark '360 Ödenecek Vergi ve Fonlar' hesabına alacak yazılır. 191 > 391 ise fark '190 Devreden KDV' hesabına borç yazılır."]}, {"unit_number": 4, "title": "Duran Varlıklar", "is_vize": true, "key_topics": ["25 Maddi Duran Varlıklar", "Amortisman Hesaplama Yöntemleri", "Kıst Amortisman Kuralı", "26 Maddi Olmayan Duran Varlıklar"], "hap_bilgiler": ["Duran Varlıklar (2 Grubu): Bir yıldan daha uzun süre işletme faaliyetlerinde kullanılmak üzere edinilen varlıklardır.", "25 Maddi Duran Varlıklar: 250 Arazi ve Arsalar, 251 Yeraltı ve Yerüstü Düzenleri, 252 Binalar, 253 Tesis Makine ve Cihazlar, 254 Taşıtlar, 255 Demirbaşlar, 257 Birikmiş Amortismanlar (-).", "KRİTİK KURAL: 250 Arazi ve Arsalar hesabına aşınma veya yıpranma payı olmadığı için KESİNLİKLE AMORTİSMAN AYRILMAZ!", "Amortisman Yöntemleri:", "  1. Normal (Eşit Paylı) Amortisman: Her yıl eşit tutarda amortisman ayrılır.", "     Amortisman Oranı = 1 / Faydalı Ömür (n). Yıllık Tutar = Maliyet Bedeli * Amortisman Oranı.", "     Örnek: 100.000 TL demirbaş, ömrü 5 yıl -> Oran = 1/5 = %20 -> Yıllık amortisman = 20.000 TL.", "  2. Azalan Bakiyeler (Hızlandırılmış) Amortisman Yöntemi:", "     Oran = Normal Amortisman Oranı * 2 (Ancak oran hiçbir şekilde %50'yi geçemez!).", "     Amortisman tutarı her yıl Duran Varlığın Net Defter Değerinden (Maliyet Bedeli - Birikmiş Amortisman) hesaplanır.", "     Son yıl kalan net defter değerinin tamamı amortisman olarak ayrılır ve sıfırlanır.", "  3. Kıst Amortisman Kuralı: Vergi Usul Kanunu'na göre YALNIZCA işletmelerde kullanılan BİNEK OTOMOBİLLER için uygulanır. Alındığı aydan itibaren yıl sonuna kadar kalan ay sayısı kadar ayrılır. İlk yıl ayrılmayan eksik kısım son yıla ilave edilir.", "Amortisman Kaydı: 770 Genel Yönetim Giderleri BORÇLU, 257 Birikmiş Amortismanlar ALACAKLI.", "26 Maddi Olmayan Duran Varlıklar: Fiziksel varlığı olmayan haklar ve imtiyazlardır (260 Haklar - patent, telif, lisans; 261 Şerefiye - işletme devralırken ödenen hava parası; 268 Birikmiş Amortismanlar [-])."]}, {"unit_number": 5, "title": "Yabancı Kaynaklar", "is_vize": false, "key_topics": ["3 Kısa Vadeli Yabancı Kaynaklar", "4 Uzun Vadeli Yabancı Kaynaklar", "Ticari Borçlar ve Senetler", "Gelecek Aylara Ait Gelirler"], "hap_bilgiler": ["Yabancı Kaynaklar: İşletmenin üçüncü kişilere (bankalar, satıcılar, devlet vb.) olan borçlarıdır.", "Kısa Vadeli Yabancı Kaynaklar (3 Grubu): Vadesi 1 yıla kadar olan borçlar.", "Uzun Vadeli Yabancı Kaynaklar (4 Grubu): Vadesi 1 yıldan uzun olan borçlar. Vadesi 1 yılın altına inen uzun vadeli borçlar dönem sonunda 3 grubundaki ilgili hesaplara aktarılır (Örn: 400 Banka Kredileri -> 303 Uzun Vadeli Kredilerin Anapara Taksitleri ve Faizleri).", "32 Ticari Borçlar:", "  - 320 Satıcılar: Veresiye (açık hesap) mal ve hizmet alımından doğan senetsiz borçlar. Mal alındığında 153 Ticari Mallar ve 191 İndirilecek KDV BORÇLU, 320 Satıcılar ALACAKLI olur.", "  - 321 Borç Senetleri: Mal alımı veya borç karşılığı işletmenin keşide ettiği ya da ciroladığı bonolar.", "  - 322 Borç Senetleri Reeskontu (-): Pasifte yer almasına karşın AKTİF karakterli düzenleyici hesaptır! Dönem sonunda borç senetlerinin peşin değerine indirilmesini sağlar.", "380 Gelecek Aylara Ait Gelirler: Peşin tahsil edilen ancak gelecek aylara ait olan gelirlerdir (Örn: 1 yıllık kira gelirinin peşin tahsil edilmesi). Dönemsellik ilkesi gereği peşin alınan tutar hemen gelir yazılmaz, pasifte 380 hesabında bekletilir ve ilgili ay geldikçe 649/600 hesaplarına aktarılır."]}, {"unit_number": 6, "title": "Öz Kaynaklar", "is_vize": false, "key_topics": ["50 Ödenmiş Sermaye", "52 Sermaye Yedekleri", "54 Kâr Yedekleri", "Geçmiş Yıllar Kâr/Zararları", "Dönem Net Kâr/Zararı"], "hap_bilgiler": ["Öz Kaynaklar (5 Grubu): İşletme sahip veya ortaklarının işletme varlıkları üzerindeki net hak sahipliğidir (Öz Kaynaklar = Varlıklar - Yabancı Kaynaklar).", "50 Ödenmiş Sermaye:", "  - 500 Sermaye: Şirket ana sözleşmesinde taahhüt edilen nominal sermayedir (Pasif hesap, alacak kalanı verir).", "  - 501 Ödenmemiş Sermaye (-): Ortakların taahhüt edip henüz işletmeye ödemedikleri sermaye payıdır. Pasifte yer almasına rağmen AKTİF karakterli düzenleyici hesaptır (borç tarafına kayıt yapılır, bilançoda indirim kalemi olarak eksi gösterilir).", "52 Sermaye Yedekleri: 520 Hisse Senedi İhraç Primleri (Emisyon Primi - hisse senetlerinin nominal değerinin üzerinde bir bedelle satılmasından doğan farktır).", "54 Kâr Yedekleri:", "  - 540 Yasal Yedekler: Türk Ticaret Kanunu (TTK) hükümlerine göre safi kârın %5'i oranında zorunlu olarak ayrılan yedek akçelerdir.", "  - 541 Statü Yedekleri: Şirket ana sözleşmesi gereğince ayrılan yedekler.", "  - 542 Olağanüstü Yedekler: Genel Kurul kararıyla serbestçe ayrılan yedekler.", "570 Geçmiş Yıllar Kârları (Kâr birikimi) ve 580 Geçmiş Yıllar Zararları (-) (Zarar birikimi).", "590 Dönem Net Kârı ve 591 Dönem Net Zararı (-): Faaliyet dönemi sonucunda oluşan nihai net sonuçtur."]}, {"unit_number": 7, "title": "Gelirler ve Giderler", "is_vize": false, "key_topics": ["6 Grubu Gelir Tablosu Hesapları", "Brüt Satış Kârı ve Faaliyet Kârı Formülleri", "7/A Seçeneği Maliyet Hesapları", "Yansıtma Hesapları"], "hap_bilgiler": ["Gelir Tablosu Temel Matematiksel Yapısı (Kademe Kademe Kâr Hesaplama):", "  1. Net Satışlar = 60 Brüt Satışlar (600 Yurtiçi Satışlar) - 61 Satış İndirimleri (610 Satıştan İadeler, 611 Satış İskontoları).", "  2. Brüt Satış Kârı (Zararı) = Net Satışlar - 62 Satışların Maliyeti (621 STMM).", "  3. Faaliyet Kârı (Zararı) = Brüt Satış Kârı - 63 Faaliyet Giderleri (631 Pazarlama Satış Dağıtım Giderleri + 632 Genel Yönetim Giderleri).", "  4. Olağan Kâr (Zarar) = Faaliyet Kârı + Diğer Faaliyetlerden Olağan Gelirler (Faiz 642, Kambiyo Kârı 646) - Diğer Faaliyetlerden Olağan Giderler (Kambiyo Zararı 656) - Finansman Giderleri (660).", "  5. Dönem Net Kârı (Zararı) = Dönem Kârı - Dönem Kârı Vergi ve Yasal Yükümlülük Karşılıkları (691).", "Maliyet Hesapları (7/A Seçeneği):", "  - 710 Direkt İlk Madde ve Malzeme, 720 Direkt İşçilik, 730 Genel Üretim, 760 Pazarlama Satış Dağıtım, 770 Genel Yönetim Giderleri, 780 Finansman Giderleri.", "  - Giderler fiilen ortaya çıktığında ilgili 7'li hesaba BORÇ yazılır.", "  - Dönem sonunda bu giderler Yansıtma Hesapları (771, 761, 781 vb.) aracılığıyla Gelir Tablosundaki 632, 631, 660 hesaplarına devredilerek kapatılır."]}, {"unit_number": 8, "title": "Dönem Sonu İşlemleri", "is_vize": false, "key_topics": ["Muhasebe Dışı ve Muhasebe İçi Envanter", "Reeskont Kayıtları", "Amortisman ve Karşılıklar", "Gelir ve Giderlerin 690 Hesaba Devri", "Kapanış Kaydı"], "hap_bilgiler": ["Envanter Türleri: Muhasebe Dışı Envanter (Fiziki sayım, ölçüm, tartım yaparak fiili durumun tespit edilmesi) ve Muhasebe İçi Envanter (Tespit edilen fiili durum ile defter kayıtları arasındaki farkların düzeltilmesi, amortisman, reeskont, karşılık ve kapanış kayıtları).", "Reeskont İşlemleri (Senede bağlı alacak ve borçların bilançoda peşin değerine indirgenmesi):", "  - Alacak Senetleri Reeskontu: 657 Reeskont Faiz Giderleri BORÇLU / 122 Alacak Senetleri Reeskontu ALACAKLI.", "  - Borç Senetleri Reeskontu: 322 Borç Senetleri Reeskontu BORÇLU / 647 Reeskont Faiz Gelirleri ALACAKLI.", "Gelir ve Gider Hesaplarının Kapatılması:", "  - Bütün Gelir Hesapları (Alacak kalanı veren 600, 642 vb.) BORÇLANDIRILARAK,", "  - Bütün Gider Hesapları (Borç kalanı veren 621, 631, 632, 656 vb.) ALACAKLANDIRILARAK,", "  - '690 Dönem Kârı veya Zararı' hesabına devredilir ve 6'lı hesapların tamamı sıfırlanır.", "690 Hesabın Kalanı: Alacak kalanı verirse KÂR (690 Borç / 692 Dönem Net Kârı Alacak); Borç kalanı verirse ZARAR (692 Dönem Net Zararı Borç / 690 Alacak) oluşur.", "Kapanış Yevmiye Kaydı (Dönemin en son kaydı):", "  - Borç kalanı veren Aktif hesaplar ALACAKLANDIRILIR.", "  - Alacak kalanı veren Pasif hesaplar BORÇLANDIRILIR.", "  - Böylece bilançonun tüm hesapları sıfırlanarak defterler kapatılır."]}], "sinav_tuzaklari": [{"id": 1, "title": "103 Verilen Çekler ve Ödeme Emirleri Hesabının Karakteri", "mistake": "103 hesabının aktifte yer aldığı için normal bir aktif hesap gibi borç kalanı vereceğini düşünmek.", "truth": "103 Verilen Çekler hesabı AKTİFİ DÜZENLEYİCİ PASİF KARAKTERLİ bir hesaptır. Çek keşide edildiğinde ALACAKLANDIRILIR, bankadan ödendiğinde BORÇLANDIRILIR. Asla borç kalanı vermez!", "tip": "Kodun yanında (-) işareti varsa ters çalışır: Aktifteyse pasif, pasifteyse aktif gibi düşün."}, {"id": 2, "title": "250 Arazi ve Arsalar Hesabına Amortisman Ayrılması Yanılgısı", "mistake": "Soru metninde 'işletmenin sahip olduğu arsaya %20 amortisman ayrılmıştır' dendiğinde hesaplama yapmaya çalışmak.", "truth": "Arazi ve arsalar (250) tükenebilir veya yıpranabilir bir nitelikte olmadığından amortismana tabi DEĞİLDİR! Bu hesap için amortisman tutarı daima 0 (sıfır) TL'dir.", "tip": "Arsa ve Araziye amortisman ayrılmaz; sınavda görürsen tuzaktır!"}, {"id": 3, "title": "Kıst Amortisman Kapsamı Tuzağı", "mistake": "Kıst amortismanın tüm makineler veya binalar için de uygulanabileceğini sanmak.", "truth": "Türk vergi mevzuatında kıst amortisman YALNIZCA işletmelerde kullanılan BİNEK OTOMOBİLLER için zorunludur. Kamyon, otobüs, bina veya makineler için yılın hangi ayında alınırsa alınsın tam yıllık amortisman ayrılır.", "tip": "Kıst Amortisman = Yalnızca Binek Otomobil."}, {"id": 4, "title": "Azalan Bakiyeler Yönteminde Matrah Hesabı", "mistake": "Her yıl ilk maliyet bedeli üzerinden amortisman hesaplamak.", "truth": "Azalan bakiyelerde amortisman tutarı maliyetten değil, NET DEFTER DEĞERİNDEN (Maliyet Bedeli - Birikmiş Amortisman) hesaplanır. Ayrıca normal oranın 2 katı alınır (azami %50).", "tip": "Azalan bakiyede her yıl birikmiş amortismanı düşmeyi unutma!"}, {"id": 5, "title": "120 Alıcılar ile 320 Satıcılar Hesaplarının Karıştırılması", "mistake": "Veresiye mal alışında 120, satışında 320 hesabını kullanmak.", "truth": "İşletme mal sattığında müşteriye karşı alacak doğar -> 120 ALICILAR BORÇLU. İşletme veresiye mal aldığında toptancıya borç doğar -> 320 SATICILAR ALACAKLI.", "tip": "Satıcıya borçlanırsın (320 Pasif/Alacak); Alıcıdan tahsil edersin (120 Aktif/Borç)."}, {"id": 6, "title": "Mizan Tablosunun Mali Tablo Sayılması", "mistake": "Mizanın bilanço veya gelir tablosu gibi bir finansal tablo olduğunu düşünmek.", "truth": "Mizan bir mali tablo DEĞİLDİR! Mizan, yevmiye defterinden büyük deftere yapılan kayıtların matematiksel eşitliğini kontrol etmeye yarayan bir ara kontrol cetvelidir.", "tip": "Temel mali tablolar sadece Bilanço ve Gelir Tablosudur."}, {"id": 7, "title": "380 Gelecek Aylara Ait Gelirler Hesabının Niteliği", "mistake": "Adında 'Gelir' kelimesi geçtiği için gelir tablosu hesabı sanmak.", "truth": "380 bir GELİR hesabı değil, bir PASİF (Kısa Vadeli Yabancı Kaynak) bilançosu hesabıdır. Peşin tahsil edilen kiranın henüz hak edilmemiş borcunu gösterir.", "tip": "3 ile başlıyorsa yabancı kaynak (borçtur), 6 ile başlıyorsa gelirdir."}, {"id": 8, "title": "KDV Mahsubunda Ödenecek KDV ile Devreden KDV Karışıklığı", "mistake": "191 büyük olduğunda vergi dairesine vergi ödeneceğini sanmak.", "truth": "391 Hesaplanan KDV (müşteriden tahsil ettiğin) > 191 İndirilecek KDV (ödediğin) ise devlete vergi borcu doğar -> 360 Ödenecek Vergi. Tam tersi 191 > 391 ise devletten alacaklı olursun ve sonraki aya devreder -> 190 Devreden KDV.", "tip": "391 büyükse ÖDE (360); 191 büyükse DEVRET (190)."}, {"id": 9, "title": "Gelir ve Gider Hesaplarının Kapatılma Şekli", "mistake": "Gelir hesaplarını alacaklandırarak, gider hesaplarını borçlandırarak kapattığını düşünmek.", "truth": "Gelir hesapları normalde alacak kalanı verir; kapatmak için BORÇLANDIRILIR. Gider hesapları borç kalanı verir; kapatmak için ALACAKLANDIRILIR. Karşı hesap daima '690 Dönem Kârı veya Zararı'dır.", "tip": "Kapatmak = Hesabın tersine kayıt yapıp sıfırlamaktır!"}, {"id": 10, "title": "501 Ödenmemiş Sermaye Hesabının Bilançodaki Yeri", "mistake": "Ödenmemiş sermayeyi bir alacak kalemi sanıp Dönen Varlıklara yazmak.", "truth": "501 Ödenmemiş Sermaye, bilançonun PASİFİNDE, ÖZ KAYNAKLAR grubunda yer alır; ancak düzenleyici bir hesap olduğu için sermayeden düşülerek (-) eksi olarak gösterilir.", "tip": "501 pasifte ama parantez içinde eksi (-) olarak oturur."}], "formuller_ve_kavramlar": [{"term": "Bilanço Eşitliği", "description": "Varlıklar (Aktif) = Yabancı Kaynaklar (Kısa + Uzun Vadeli Borçlar) + Öz Kaynaklar.", "example": "Varlıklar 500.000 TL, Borçlar 200.000 TL ise Öz Kaynaklar = 300.000 TL'dir."}, {"term": "Net Satışlar Formülü", "description": "Net Satışlar = Brüt Satışlar (600 Yurtiçi Satışlar) - Satış İndirimleri (610 Satıştan İadeler + 611 Satış İskontoları)."}, {"term": "Brüt Satış Kârı (Zararı)", "description": "Brüt Satış Kârı = Net Satışlar - Satılan Ticari Mallar Maliyeti (621 STMM)."}, {"term": "Faaliyet Kârı (Zararı)", "description": "Faaliyet Kârı = Brüt Satış Kârı - (760 Pazarlama Giderleri + 770 Genel Yönetim Giderleri)."}, {"term": "STMM Formülü (Aralıklı Envanter)", "description": "STMM = Dönem Başı Emtia Mevcudu + Dönem İçi Net Alışlar - Dönem Sonu Emtia Mevcudu.", "example": "Dönem başı mal: 50.000 TL, Alışlar: 150.000 TL, Dönem sonu sayım: 40.000 TL -> STMM = 50.000 + 150.000 - 40.000 = 160.000 TL."}, {"term": "Normal Amortisman Formülü", "description": "Yıllık Amortisman = Maliyet Bedeli / Faydalı Ömür = Maliyet Bedeli * (1 / n).", "example": "80.000 TL demirbaş, ömür 4 yıl -> Yıllık amortisman = 80.000 * %25 = 20.000 TL."}, {"term": "Azalan Bakiyeler Amortismanı", "description": "Amortisman Oranı = Normal Oran * 2 (Maksimum %50). Yıllık Amortisman = (Maliyet - Birikmiş Amortisman) * Oran.", "example": "100.000 TL makine, ömür 5 yıl -> Oran = (1/5)*2 = %40. 1. Yıl: 40.000 TL. 2. Yıl matrahı: 60.000 TL -> 24.000 TL amortisman."}, {"term": "Kıst Amortisman (Binek Oto)", "description": "İlk Yıl Amortismanı = (Yıllık Amortisman Tutarı / 12) * Kalan Ay Sayısı. Ayrılmayan kısım son yıla eklenir."}, {"term": "Alacak Senetleri Reeskontu", "description": "Senetli alacakların dönem sonu itibarıyla peşin değerine indirgenmesi işlemidir. 657 Reeskont Faiz Giderleri Borç / 122 Alacak Senetleri Reeskontu Alacak kaydedilir."}, {"term": "Borç Senetleri Reeskontu", "description": "Senetli borçların bilanço tarihindeki peşin değerine indirgenmesidir. 322 Borç Senetleri Reeskontu Borç / 647 Reeskont Faiz Gelirleri Alacak kaydedilir."}, {"term": "Kasa Sayım Fazlası", "description": "Fiili sayım mevcudu > Defter mevcudu ise aradaki fark 397 Sayım ve Tesellüm Fazlaları hesabına alacak yazılır."}, {"term": "Kasa Sayım Noksanı", "description": "Fiili sayım mevcudu < Defter mevcudu ise aradaki fark 197 Sayım ve Tesellüm Noksanları hesabına borç yazılır."}, {"term": "Yasal Yedekler (I. Tertip)", "description": "Türk Ticaret Kanunu uyarınca her yıl safi kârın %5'i, ödenmiş sermayenin %20'sine ulaşıncaya kadar yasal yedek olarak ayrılır."}, {"term": "Emisyon Primi (Hisse İhraç Primi)", "description": "Hisse senetlerinin nominal bedelinden daha yüksek fiyatla ihraç edilmesi halinde aradaki pozitif fark (520 hesabı)."}, {"term": "690 Dönem Kârı veya Zararı", "description": "Dönem sonunda tüm gelir ve gider hesaplarının devredildiği, kâr veya zararın net olarak toplandığı sonuç hesabıdır."}], "flashcards": [{"id": 1, "unit": 1, "question": "Muhasebenin ilk ve temel işlevi nedir?", "answer": "Kaydetme işlevidir (Yevmiye defterine tarih sırasıyla kaydetme)."}, {"id": 2, "unit": 1, "question": "Temel muhasebe (bilanço) eşitliği nasıldır?", "answer": "Varlıklar = Yabancı Kaynaklar (Borçlar) + Öz Kaynaklar (Sermaye)."}, {"id": 3, "unit": 1, "question": "İşletmenin sahiplerinden bağımsız bir varlığa sahip olduğunu belirten muhasebe kavramı nedir?", "answer": "Kişilik Kavramı."}, {"id": 4, "unit": 1, "question": "İşletmenin sınırsız ömrünün belirli takvim yıllarına bölünmesini öngören muhasebe ilkesi nedir?", "answer": "Dönemsellik Kavramı."}, {"id": 5, "unit": 1, "question": "Olası risk ve zararlar için karşılık ayrılmasını gerektiren temel muhasebe kavramı hangisidir?", "answer": "İhtiyatlılık Kavramı."}, {"id": 6, "unit": 2, "question": "Aktif karakterli bir hesapta artış meydana geldiğinde hesabın hangi tarafına kayıt yapılır?", "answer": "Borç (sol) tarafına kayıt yapılır."}, {"id": 7, "unit": 2, "question": "Pasif karakterli hesaplar kural olarak hangi kalanı verir?", "answer": "Alacak kalanı verir veya sıfır olur (Asla borç kalanı veremez)."}, {"id": 8, "unit": 2, "question": "İçinde kesinlikle kasa hesabı geçmeyen, nakitsiz işlemler için düzenlenen muhasebe fişi hangisidir?", "answer": "Mahsup Fişi."}, {"id": 9, "unit": 2, "question": "İşlemlerin hesaplar bazında sınıflandırılarak gösterildiği yasal defter hangisidir?", "answer": "Büyük Defter (Defter-i Kebir)."}, {"id": 10, "unit": 2, "question": "Dönem sonu envanter ve düzeltme kayıtları yapıldıktan sonra çıkarılan nihai kontrol cetveli nedir?", "answer": "Kesin Mizan."}, {"id": 11, "unit": 3, "question": "103 Verilen Çekler ve Ödeme Emirleri hesabının bilançodaki niteliği nedir?", "answer": "Aktifi Düzenleyici Pasif Karakterli hesaptır (Verildiğinde Alacaklandırılır)."}, {"id": 12, "unit": 3, "question": "Veresiye (açık hesap) mal satışından doğan senetsiz alacaklar hangi hesapta izlenir?", "answer": "120 Alıcılar hesabında izlenir."}, {"id": 13, "unit": 3, "question": "Kasa fiili sayımında defterdekinden daha fazla nakit çıkarsa hangi hesap alacaklandırılır?", "answer": "397 Sayım ve Tesellüm Fazlaları hesabı."}, {"id": 14, "unit": 3, "question": "Sürekli envanter yönteminde mal satıldığı anda yapılan maliyet kaydı nasıldır?", "answer": "621 Satılan Ticari Mallar Maliyeti BORÇLU, 153 Ticari Mallar ALACAKLI."}, {"id": 15, "unit": 3, "question": "Ay sonunda 391 Hesaplanan KDV > 191 İndirilecek KDV ise aradaki fark hangi hesaba kaydedilir?", "answer": "360 Ödenecek Vergi ve Fonlar hesabına (Alacak)."}, {"id": 16, "unit": 4, "question": "Maddi duran varlıklar arasında yer almasına rağmen KESİNLİKLE amortisman ayrılmayan hesap hangisidir?", "answer": "250 Arazi ve Arsalar hesabı."}, {"id": 17, "unit": 4, "question": "Azalan bakiyeler yönteminde uygulanabilecek azami (en yüksek) amortisman oranı yüzde kaçtır?", "answer": "Yüzde 50 (%50)."}, {"id": 18, "unit": 4, "question": "Kıst amortisman uygulaması mevzuat gereği yalnızca hangi duran varlık için zorunludur?", "answer": "Binek Otomobiller için."}, {"id": 19, "unit": 4, "question": "İşletmenin bir başka işletmeyi devralırken net varlık değerinden fazla ödediği tutar (hava parası) hangi hesapta izlenir?", "answer": "261 Şerefiye hesabında."}, {"id": 20, "unit": 5, "question": "Veresiye mal alımı dolayısıyla satıcılara olan senetsiz ticari borçlar hangi hesapta izlenir?", "answer": "320 Satıcılar hesabında."}, {"id": 21, "unit": 5, "question": "Peşin tahsil edilen gelecek dönemlere ait kira gelirleri dönemsellik ilkesi gereği hangi hesapta bekletilir?", "answer": "380 Gelecek Aylara Ait Gelirler hesabında."}, {"id": 22, "unit": 5, "question": "322 Borç Senetleri Reeskontu hesabının bilançodaki niteliği nedir?", "answer": "Pasifi Düzenleyici Aktif Karakterli hesaptır."}, {"id": 23, "unit": 6, "question": "Ortakların taahhüt edip henüz ödemedikleri sermaye payı hangi düzenleyici hesapta takip edilir?", "answer": "501 Ödenmemiş Sermaye (-) hesabında."}, {"id": 24, "unit": 6, "question": "Türk Ticaret Kanunu'na göre safi kârdan zorunlu olarak ayrılan yedek akçe türü nedir?", "answer": "540 Yasal Yedekler."}, {"id": 25, "unit": 7, "question": "Brüt Satış Kârı (Zararı) nasıl hesaplanır?", "answer": "Net Satışlar - Satılan Ticari Mallar Maliyeti (STMM)."}, {"id": 26, "unit": 7, "question": "Faaliyet Kârı nasıl bulunur?", "answer": "Brüt Satış Kârı - Faaliyet Giderleri (Pazarlama + Genel Yönetim Giderleri)."}, {"id": 27, "unit": 8, "question": "İşletmenin fiili sayım, tartım ve ölçüm yaparak mevcutları belirlemesine ne envanter denir?", "answer": "Muhasebe Dışı Envanter."}, {"id": 28, "unit": 8, "question": "Dönem sonunda tüm gelir hesapları nereye devredilerek kapatılır?", "answer": "Gelir hesapları borçlandırılarak '690 Dönem Kârı veya Zararı' hesabına devredilir."}, {"id": 29, "unit": 8, "question": "690 Dönem Kârı veya Zararı hesabı alacak kalanı verirse bu neyi ifade eder?", "answer": "Dönemin kârla (Dönem Net Kârı) sonuçlandığını ifade eder."}, {"id": 30, "unit": 8, "question": "Dönem sonu kapanış yevmiye kaydında aktif hesaplar nasıl kapatılır?", "answer": "Aktif hesaplar ALACAKLANDIRILARAK kapatılır."}], "exams": [{"title": "Vize Deneme Sınavı 1", "filename": "Vize_Deneme_1.md", "questions": [{"id": 1, "unit": 1, "question": "Mali nitelikteki işlemlerin yevmiye defterine tarih sırasıyla kaydedilmesi muhasebenin hangi temel işlevine aittir?", "options": ["A) Sınıflandırma", "B) Kaydetme", "C) Özetleme", "D) Analiz", "E) Yorumlama"], "correct_answer": "B", "explanation": "Mali işlemlerin tarih sırasıyla yevmiye defterine geçirilmesi muhasebenin 'Kaydetme' işlevidir."}, {"id": 2, "unit": 1, "question": "Bir işletmenin toplam varlıkları 650.000 TL ve yabancı kaynakları (borçları) 280.000 TL olduğuna göre, temel muhasebe eşitliğine göre Öz Kaynakları kaç TL'dir?", "options": ["A) 930.000 TL", "B) 650.000 TL", "C) 370.000 TL", "D) 280.000 TL", "E) 190.000 TL"], "correct_answer": "C", "explanation": "Varlıklar = Yabancı Kaynaklar + Öz Kaynaklar. 650.000 = 280.000 + Öz Kaynaklar -> Öz Kaynaklar = 650.000 - 280.000 = 370.000 TL."}, {"id": 3, "unit": 1, "question": "İşletme sahibi Bay A'nın kendi evinin kişisel elektrik faturasını işletmenin kasasından ödeyip gider yazması, aşağıdaki muhasebe temel kavramlarından hangisine aykırıdır?", "options": ["A) Dönemsellik", "B) Sosyal Sorumluluk", "C) Kişilik", "D) Tutarlılık", "E) İhtiyatlılık"], "correct_answer": "C", "explanation": "Kişilik kavramı, işletmenin sahip ve ortaklarından bağımsız ayrı bir kişiliğe sahip olduğunu belirtir. Kişisel harcamalar işletmeye gider yazılamaz."}, {"id": 4, "unit": 1, "question": "İşletmenin ömrünün sınırsız kabul edilmesi varsayımı aşağıdaki kavramlardan hangisidir?", "options": ["A) İşletmenin Sürekliliği", "B) Parayla Ölçülme", "C) Dönemsellik", "D) Maliyet Esası", "E) Önemlilik"], "correct_answer": "A", "explanation": "İşletmenin Sürekliliği kavramı, işletmenin ömrünün sonsuz olduğunu ve faaliyetlerinin herhangi bir sona bağlı olmadığını kabul eder."}, {"id": 5, "unit": 1, "question": "Gelecekte doğabilecek olası risk ve zararlar için karşılık ayrılmasını öngören muhasebe kavramı aşağıdakilerden hangisidir?", "options": ["A) Tam Açıklama", "B) İhtiyatlılık", "C) Özün Önceliği", "D) Tarafsızlık", "E) Tutarlılık"], "correct_answer": "B", "explanation": "İhtiyatlılık kavramı gereği, olası risk ve zararlar için karşılık ayrılır, ancak gerçekleşmemiş kârlar kaydedilmez."}, {"id": 6, "unit": 2, "question": "Aktif karakterli bir hesap için aşağıdakilerden hangisi kesinlikle yanlıştır?", "options": ["A) İlk kayıt borç tarafına yapılır.", "B) Artışlar borç tarafına yazılır.", "C) Azalışlar alacak tarafına yazılır.", "D) Dönem sonunda alacak kalanı verir.", "E) Borç kalanı verir veya sıfır olur."], "correct_answer": "D", "explanation": "Aktif karakterli hesaplar borç kalanı verir veya kalan vermez (sıfır). KESİNLİKLE alacak kalanı veremezler!"}, {"id": 7, "unit": 2, "question": "Kasa hesabını kesinlikle içermeyen, tamamen hesaben ve nakitsiz gerçekleşen işlemler için hangi muhasebe fişi düzenlenir?", "options": ["A) Kasa Tahsil Fişi", "B) Kasa Tediye Fişi", "C) Mahsup Fişi", "D) Açılış Fişi", "E) Gider Makbuzu"], "correct_answer": "C", "explanation": "Nakit tahsilat veya tediye içermeyen tüm yevmiye kayıtları için Mahsup Fişi düzenlenir."}, {"id": 8, "unit": 2, "question": "İşlemlerin tarih sırasına göre madde madde kaydedildiği yasal defter hangisidir?", "options": ["A) Yevmiye Defteri (Günlük Defter)", "B) Defter-i Kebir (Büyük Defter)", "C) Envanter Defteri", "D) Karar Defteri", "E) Pay Defteri"], "correct_answer": "A", "explanation": "Kronolojik (tarih) sırayla yevmiye maddeleri halinde tutulan defter Yevmiye Defteridir."}, {"id": 9, "unit": 2, "question": "Aralık ayı sonunda, dönem sonu envanter ve düzeltme işlemlerine başlamadan hemen önce çıkarılan kontrol mizanı hangisidir?", "options": ["A) Aylık Mizan", "B) Genel Geçici Mizan", "C) Kesin Mizan", "D) Açılış Mizanı", "E) Tasfiye Mizanı"], "correct_answer": "B", "explanation": "Envanter işlemlerinden hemen önce çıkarılan mizan Genel Geçici Mizandır."}, {"id": 10, "unit": 2, "question": "Aşağıdakilerden hangisi bir 'Mali Tablo' değildir?", "options": ["A) Bilanço", "B) Gelir Tablosu", "C) Nakit Akım Tablosu", "D) Mizan", "E) Satışların Maliyeti Tablosu"], "correct_answer": "D", "explanation": "Mizan bir mali tablo değil; kayıtların matematiksel tutarlılığını kontrol eden bir ara cetveldir."}, {"id": 11, "unit": 3, "question": "İşletmenin keşide ettiği çeklerin izlendiği ve aktifte yer almasına karşın pasif karakterli çalışan düzenleyici hesap hangisidir?", "options": ["A) 100 Kasa", "B) 101 Alınan Çekler", "C) 102 Bankalar", "D) 103 Verilen Çekler ve Ödeme Emirleri (-)", "E) 108 Diğer Hazır Değerler"], "correct_answer": "D", "explanation": "103 Verilen Çekler ve Ödeme Emirleri (-), aktifi düzenleyen pasif karakterli bir hesaptır."}, {"id": 12, "unit": 3, "question": "İşletme 50.000 TL + %20 KDV tutarındaki ticari malı veresiye (açık hesap) satmıştır. Bu işlemde aşağıdaki hesaplardan hangisi BORÇLU çalışır?", "options": ["A) 600 Yurtiçi Satışlar (50.000 TL)", "B) 391 Hesaplanan KDV (10.000 TL)", "C) 120 Alıcılar (60.000 TL)", "D) 320 Satıcılar (60.000 TL)", "E) 100 Kasa (60.000 TL)"], "correct_answer": "C", "explanation": "Veresiye mal satışında senetsiz müşteri alacağı doğar: 120 Alıcılar 60.000 TL BORÇLU; 600 Yurtiçi Satışlar 50.000 TL ALACAKLI ve 391 Hesaplanan KDV 10.000 TL ALACAKLI kaydedilir."}, {"id": 13, "unit": 3, "question": "Aralıklı envanter yönteminde; Dönem Başı Mal Mevcudu 60.000 TL, Dönem İçi Net Alışlar 140.000 TL ve Dönem Sonu Mal Mevcudu 50.000 TL ise Satılan Ticari Mallar Maliyeti (STMM) kaç TL'dir?", "options": ["A) 250.000 TL", "B) 150.000 TL", "C) 130.000 TL", "D) 190.000 TL", "E) 200.000 TL"], "correct_answer": "B", "explanation": "STMM = Dönem Başı + Dönem İçi Alışlar - Dönem Sonu = 60.000 + 140.000 - 50.000 = 150.000 TL."}, {"id": 14, "unit": 3, "question": "Kasada yapılan fiziki sayımda 18.000 TL nakit tespit edilmiş, ancak 100 Kasa hesabının büyük defter borç kalanı 17.500 TL olarak görülmüştür. Bu durumda alacaklandırılacak hesap hangisidir?", "options": ["A) 197 Sayım ve Tesellüm Noksanları (500 TL)", "B) 397 Sayım ve Tesellüm Fazlaları (500 TL)", "C) 679 Diğer Olağandışı Gelirler (500 TL)", "D) 100 Kasa (500 TL)", "E) 600 Yurtiçi Satışlar (500 TL)"], "correct_answer": "B", "explanation": "Fiili mevcudun (18.000) defter mevcudundan (17.500) 500 TL fazla çıkması durumunda 100 Kasa BORÇLU (500 TL), 397 Sayım ve Tesellüm Fazlaları ALACAKLI (500 TL) kaydedilir."}, {"id": 15, "unit": 3, "question": "Ay sonunda yapılan KDV mahsubunda; 391 Hesaplanan KDV 45.000 TL, 191 İndirilecek KDV 35.000 TL olarak belirlenmiştir. Aradaki 10.000 TL fark hangi hesaba kaydedilir?", "options": ["A) 190 Devreden KDV (Borçlu)", "B) 360 Ödenecek Vergi ve Fonlar (Alacaklı)", "C) 600 Yurtiçi Satışlar (Alacaklı)", "D) 100 Kasa (Alacaklı)", "E) 689 Diğer Olağandışı Giderler (Borçlu)"], "correct_answer": "B", "explanation": "391 (45.000) > 191 (35.000) olduğunda işletmenin devlete vergi borcu doğar ve 360 Ödenecek Vergi ve Fonlar hesabına 10.000 TL ALACAK yazılır."}, {"id": 16, "unit": 4, "question": "Aşağıdaki maddi duran varlık hesaplarından hangisine aşınma ve yıpranma payı olmadığı için KESİNLİKLE amortisman ayrılmaz?", "options": ["A) 252 Binalar", "B) 254 Taşıtlar", "C) 250 Arazi ve Arsalar", "D) 255 Demirbaşlar", "E) 253 Tesis Makine ve Cihazlar"], "correct_answer": "C", "explanation": "250 Arazi ve Arsalar hesabına kural olarak asla amortisman ayrılmaz."}, {"id": 17, "unit": 4, "question": "İşletme 120.000 TL maliyet bedelli bir demirbaşı satın almıştır. Demirbaşın faydalı ömrü 5 yıl olduğuna göre, Normal (Eşit Paylı) Amortisman yöntemine göre 1. yıl ayrılacak amortisman payı kaç TL'dir?", "options": ["A) 12.000 TL", "B) 24.000 TL", "C) 48.000 TL", "D) 30.000 TL", "E) 60.000 TL"], "correct_answer": "B", "explanation": "Normal amortisman oranı = 1 / 5 = %20. Yıllık amortisman = 120.000 * %20 = 24.000 TL."}, {"id": 18, "unit": 4, "question": "Azalan bakiyeler (hızlandırılmış) amortisman yönteminde uygulanacak amortisman oranı normal amortisman oranının kaç katıdır ve azami sınırı yüzde kaçtır?", "options": ["A) 3 katı, azami %60", "B) 2 katı, azami %50", "C) 2 katı, azami %40", "D) 1.5 katı, azami %50", "E) 2 katı, sınır yoktur"], "correct_answer": "B", "explanation": "Azalan bakiyeler yönteminde oran normal oranın 2 katıdır ve yasal olarak en fazla %50 olabilir."}, {"id": 19, "unit": 4, "question": "Duran varlıklar için ayrılan amortisman tutarlarının kaydedildiği yevmiye maddesinde ALACAKLANDIRILAN hesap hangisidir?", "options": ["A) 770 Genel Yönetim Giderleri", "B) 257 Birikmiş Amortismanlar (-)", "C) 255 Demirbaşlar", "D) 100 Kasa", "E) 621 STMM"], "correct_answer": "B", "explanation": "Amortisman kaydı: 770 Genel Yönetim Giderleri BORÇLU, 257 Birikmiş Amortismanlar (-) ALACAKLI olarak yapılır."}, {"id": 20, "unit": 4, "question": "Kıst amortisman uygulaması aşağıdaki duran varlık türlerinden hangisi için geçerlidir?", "options": ["A) Binalar", "B) Yük taşıma kamyonları", "C) Binek otomobiller", "D) Fabrika makineleri", "E) Patent ve haklar"], "correct_answer": "C", "explanation": "Kıst amortisman Türk Vergi Mevzuatında sadece binek otomobiller için uygulanır."}]}, {"title": "Vize Deneme Sınavı 2", "filename": "Vize_Deneme_2.md", "questions": [{"id": 1, "unit": 1, "question": "Çok sayıdaki mali verinin benzer işlem gruplarına göre düzenlenmesi ve büyük deftere aktarılması muhasebenin hangi işlevidir?", "options": ["A) Kaydetme", "B) Sınıflandırma", "C) Özetleme", "D) Analiz", "E) Denetim"], "correct_answer": "B", "explanation": "Verilerin benzer hesap başlıkları altında büyük deftere toplanması 'Sınıflandırma' işlevidir."}, {"id": 2, "unit": 1, "question": "Bir işletmenin belirli bir andaki finansal durumunu (varlıklarını ve borçlarını) gösteren tablo hangisidir?", "options": ["A) Gelir Tablosu", "B) Bilanço", "C) Mizan", "D) Satışların Maliyeti Tablosu", "E) Fon Akım Tablosu"], "correct_answer": "B", "explanation": "Belirli bir tarihteki varlık ve kaynak dengesini gösteren statik tablo Bilançodur."}, {"id": 3, "unit": 1, "question": "Uygulanan muhasebe politika ve yöntemlerinin yıldan yıla keyfi olarak değiştirilmemesini, finansal tabloların karşılaştırılabilir olmasını zorunlu kılan kavram hangisidir?", "options": ["A) Tutarlılık", "B) İhtiyatlılık", "C) Önemlilik", "D) Dönemsellik", "E) Kişilik"], "correct_answer": "A", "explanation": "Yöntemlerin ve politikaların dönemler arası benzer uygulanması Tutarlılık kavramının gereğidir."}, {"id": 4, "unit": 1, "question": "Muhasebede tüm kayıtların objektif ve yasal belgelere (fatura, dekont, makbuz vb.) dayandırılmasını gerektiren ilke nedir?", "options": ["A) Maliyet Esası", "B) Tarafsızlık ve Belgelendirme", "C) Sosyal Sorumluluk", "D) Tam Açıklama", "E) Özün Önceliği"], "correct_answer": "B", "explanation": "Tarafsızlık ve Belgelendirme ilkesi tüm muhasebe kayıtlarının geçerli belgelere dayanmasını şart koşar."}, {"id": 5, "unit": 1, "question": "Vadeli çeklerin özü itibarıyla bir senet niteliği taşıması sebebiyle dönem sonunda reeskonta tabi tutulması aşağıdaki kavramlardan hangisinin gereğidir?", "options": ["A) Özün Önceliği", "B) Parayla Ölçülme", "C) Süreklilik", "D) İhtiyatlılık", "E) Maliyet Esası"], "correct_answer": "A", "explanation": "İşlemlerin hukuki biçiminden ziyade iktisadi özünün esas alınması 'Özün Önceliği' kavramıdır."}, {"id": 6, "unit": 2, "question": "Pasif karakterli bir hesapta azalış meydana geldiğinde hesabın hangi tarafına kayıt yapılır?", "options": ["A) Borç tarafına", "B) Alacak tarafına", "C) Hem borç hem alacak", "D) Nazım hesaplara", "E) Kayıt yapılmaz"], "correct_answer": "A", "explanation": "Pasif hesaplar alacak taraflı çalışır; bu hesaplardaki azalışlar BORÇ tarafına yazılır."}, {"id": 7, "unit": 2, "question": "Kasaya nakit para girişi gerçekleştiğinde düzenlenen muhasebe fişi hangisidir?", "options": ["A) Kasa Tediye Fişi", "B) Mahsup Fişi", "C) Kasa Tahsil Fişi", "D) Açılış Fişi", "E) Dekont"], "correct_answer": "C", "explanation": "Kasaya nakit girdiğinde Kasa Tahsil Fişi düzenlenir."}, {"id": 8, "unit": 2, "question": "Yevmiye defterine kaydedilen işlemlerin hesaplar bazında topluca görülebilmesi için aktarıldığı defter hangisidir?", "options": ["A) Defter-i Kebir (Büyük Defter)", "B) Envanter Defteri", "C) Günlük Kasa Defteri", "D) Çek Defteri", "E) Stok Defteri"], "correct_answer": "A", "explanation": "Büyük Defter (Defter-i Kebir), işlemlerin 'T' cetvelleri şeklinde hesap bazında izlendiği yasal defterdir."}, {"id": 9, "unit": 2, "question": "Aşağıdakilerden hangisi pasifi düzenleyen aktif karakterli bir hesaptır?", "options": ["A) 103 Verilen Çekler ve Ödeme Emirleri (-)", "B) 257 Birikmiş Amortismanlar (-)", "C) 322 Borç Senetleri Reeskontu (-)", "D) 122 Alacak Senetleri Reeskontu (-)", "E) 129 Şüpheli Ticari Alacaklar Karşılığı (-)"], "correct_answer": "C", "explanation": "322 Borç Senetleri Reeskontu (-), pasifte yer almasına karşın borç taraflı çalışan aktif karakterli düzenleyici hesaptır."}, {"id": 10, "unit": 2, "question": "Dönem başı açılış bilançosundan sonra yapılan ilk yevmiye kaydına ne ad verilir?", "options": ["A) Kapanış Kaydı", "B) Düzeltme Kaydı", "C) Açılış Yevmiye Kaydı", "D) Tasfiye Kaydı", "E) Maliyet Kaydı"], "correct_answer": "C", "explanation": "Yeni faaliyet dönemine başlarken bilançodaki değerlerin defterlere geçirilmesi Açılış Kaydıdır."}, {"id": 11, "unit": 3, "question": "İşletme toptancıdan 80.000 TL + %20 KDV tutarında ticari malı veresiye (satıcıya borçlanarak) almıştır. Yapılacak yevmiye kaydında ALACAKLI hesap hangisidir?", "options": ["A) 153 Ticari Mallar (80.000 TL)", "B) 191 İndirilecek KDV (16.000 TL)", "C) 320 Satıcılar (96.000 TL)", "D) 120 Alıcılar (96.000 TL)", "E) 100 Kasa (96.000 TL)"], "correct_answer": "C", "explanation": "Veresiye mal alımında 320 Satıcılar 96.000 TL ALACAKLI, 153 Ticari Mallar 80.000 TL BORÇLU ve 191 İndirilecek KDV 16.000 TL BORÇLU kaydedilir."}, {"id": 12, "unit": 3, "question": "Kredi kartı sliplerinin bankadan tahsil edilinceye kadar izlendiği hazır değer hesabı hangisidir?", "options": ["A) 100 Kasa", "B) 102 Bankalar", "C) 108 Diğer Hazır Değerler", "D) 101 Alınan Çekler", "E) 110 Hisse Senetleri"], "correct_answer": "C", "explanation": "Kredi kartı slipleri, vadesi gelmiş kuponlar ve pullar 108 Diğer Hazır Değerler hesabında izlenir."}, {"id": 13, "unit": 3, "question": "Kasada yapılan sayımda 24.000 TL nakit bulunmuş, fakat 100 Kasa hesabının büyük defter borç bakiyesi 25.000 TL olarak görülmüştür. Bu durumda BORÇLANDIRILACAK hesap hangisidir?", "options": ["A) 397 Sayım ve Tesellüm Fazlaları (1.000 TL)", "B) 197 Sayım ve Tesellüm Noksanları (1.000 TL)", "C) 100 Kasa (1.000 TL)", "D) 659 Diğer Olağan Giderler (1.000 TL)", "E) 689 Diğer Olağandışı Giderler (1.000 TL)"], "correct_answer": "B", "explanation": "Kasa noksanı durumunda: 197 Sayım ve Tesellüm Noksanları BORÇLU (1.000 TL), 100 Kasa ALACAKLI (1.000 TL) kaydedilir."}, {"id": 14, "unit": 3, "question": "Enflasyonist (fiyatların sürekli arttığı) bir ortamda FIFO (İlk Giren İlk Çıkar) yöntemi uygulandığında, dönem sonu stoklar ve satılan malın maliyeti (STMM) nasıl etkilenir?", "options": ["A) Stoklar düşük, STMM yüksek çıkar.", "B) Stoklar yüksek, STMM düşük çıkar.", "C) Hem stoklar hem STMM düşük çıkar.", "D) Kâr minimum çıkar.", "E) Hiçbir etkisi olmaz."], "correct_answer": "B", "explanation": "FIFO yönteminde ilk alınan ucuz mallar önce çıkacağından STMM düşük çıkar, depoda son alınan pahalı mallar kalacağı için dönem sonu stoklar yüksek çıkar."}, {"id": 15, "unit": 3, "question": "Ay sonunda 191 İndirilecek KDV hesabı 60.000 TL, 391 Hesaplanan KDV hesabı 40.000 TL bakiye vermiştir. Yapılacak mahsup kaydında BORÇLANDIRILACAK hesap hangisidir?", "options": ["A) 360 Ödenecek Vergi ve Fonlar (20.000 TL)", "B) 190 Devreden KDV (20.000 TL)", "C) 100 Kasa (20.000 TL)", "D) 600 Yurtiçi Satışlar (20.000 TL)", "E) 391 Hesaplanan KDV (40.000 TL)"], "correct_answer": "B", "explanation": "İndirilecek KDV (60.000) > Hesaplanan KDV (40.000) olduğunda, aradaki 20.000 TL gelecek aya devreder ve 190 Devreden KDV BORÇLU kaydedilir."}, {"id": 16, "unit": 4, "question": "İşletme 200.000 TL değerinde ve 4 yıl ömürlü bir üretim makinesi için Azalan Bakiyeler yöntemine göre amortisman ayıracaktır. 1. yıl ayrılacak amortisman kaç TL'dir?", "options": ["A) 50.000 TL", "B) 80.000 TL", "C) 100.000 TL", "D) 40.000 TL", "E) 60.000 TL"], "correct_answer": "C", "explanation": "Normal oran = 1/4 = %25. Azalan bakiyeler oranı = %25 * 2 = %50 (yasal tavan). 1. Yıl Amortismanı = 200.000 * %50 = 100.000 TL."}, {"id": 17, "unit": 4, "question": "İşletme 1 Ekim tarihinde 240.000 TL bedelle bir binek otomobil satın almıştır. Ömrü 5 yıl olduğuna göre, Kıst Amortisman kuralı gereğince ilk yıl ayrılacak amortisman payı kaç TL'dir?", "options": ["A) 48.000 TL", "B) 24.000 TL", "C) 12.000 TL", "D) 8.000 TL", "E) 4.000 TL"], "correct_answer": "C", "explanation": "Yıllık tam amortisman = 240.000 / 5 = 48.000 TL. Aylık amortisman = 48.000 / 12 = 4.000 TL. Ekim, Kasım, Aralık = 3 ay. İlk yıl tutarı = 3 * 4.000 = 12.000 TL."}, {"id": 18, "unit": 4, "question": "Bir işletmenin ticari itibarını, müşteri çevresini veya pazar payını devralırken net aktif değerinin üzerinde ödediği hava parası hangi hesapta aktifleştirilir?", "options": ["A) 260 Haklar", "B) 261 Şerefiye", "C) 262 Kuruluş ve Örgütlenme Giderleri", "D) 255 Demirbaşlar", "E) 770 Genel Yönetim Giderleri"], "correct_answer": "B", "explanation": "Ödenen hava parası 261 Şerefiye hesabında maddi olmayan duran varlık olarak muhasebeleştirilir."}, {"id": 19, "unit": 4, "question": "Bir duran varlığın maliyet bedelinden, bugüne kadar ayrılmış olan birikmiş amortismanların düşülmesiyle bulunan tutara ne ad verilir?", "options": ["A) Nominal Değer", "B) Tasfiye Değeri", "C) Net Defter Değeri", "D) Hurda Değeri", "E) Emsal Bedel"], "correct_answer": "C", "explanation": "Net Defter Değeri = Maliyet Bedeli - Birikmiş Amortismanlar."}, {"id": 20, "unit": 4, "question": "Patent, lisans, telif hakkı ve marka gibi yasal imtiyazlar Tekdüzen Hesap Planında hangi hesapta izlenir?", "options": ["A) 260 Haklar", "B) 261 Şerefiye", "C) 250 Arazi ve Arsalar", "D) 110 Hisse Senetleri", "E) 255 Demirbaşlar"], "correct_answer": "A", "explanation": "Patent, telif, marka ve imtiyaz hakları 260 Haklar hesabında takip edilir."}]}, {"title": "Final Deneme Sınavı 1", "filename": "Final_Deneme_1.md", "questions": [{"id": 1, "unit": 1, "question": "(Vize Tekrarı) Muhasebe kayıtlarının kişisel yargılara değil, objektif fatura ve makbuzlara dayanmasını zorunlu kılan temel ilke hangisidir?", "options": ["A) Tutarlılık", "B) Tarafsızlık ve Belgelendirme", "C) Dönemsellik", "D) Maliyet Esası", "E) Önemlilik"], "correct_answer": "B", "explanation": "Belgelendirme ilkesi gereği her kayıt yasal evrakla kanıtlanmalıdır."}, {"id": 2, "unit": 2, "question": "(Vize Tekrarı) Yevmiye defterine yapılan kayıtların büyük deftere doğru aktarılıp aktarılmadığını matematiksel olarak denetleyen cetvel hangisidir?", "options": ["A) Bilanço", "B) Mizan", "C) Gelir Tablosu", "D) Gelir Fişi", "E) Envanter Listesi"], "correct_answer": "B", "explanation": "Mizan, yevmiye ve büyük defter tutarlarının eşitliğini kontrol eden cetveldir."}, {"id": 3, "unit": 3, "question": "(Vize Tekrarı) Sürekli envanter yönteminde ticari mal satıldığında, satış hasılatı kaydının yanı sıra yapılan maliyet kaydında hangi hesap BORÇLANDIRILIR?", "options": ["A) 153 Ticari Mallar", "B) 600 Yurtiçi Satışlar", "C) 621 Satılan Ticari Mallar Maliyeti", "D) 100 Kasa", "E) 391 Hesaplanan KDV"], "correct_answer": "C", "explanation": "Maliyet kaydında 621 STMM BORÇLU, 153 Ticari Mallar ALACAKLI yazılır."}, {"id": 4, "unit": 4, "question": "(Vize Tekrarı) 100.000 TL maliyetli bir tesis makinesine 5 yıl ömür üzerinden Normal Amortisman ayrılacaktır. Yıllık amortisman tutarı kaç TL'dir?", "options": ["A) 10.000 TL", "B) 20.000 TL", "C) 25.000 TL", "D) 40.000 TL", "E) 50.000 TL"], "correct_answer": "B", "explanation": "100.000 / 5 = 20.000 TL."}, {"id": 5, "unit": 5, "question": "İşletmenin 1 Ekim tarihinde kiraladığı gayrimenkul için 1 yıllık kira bedeli olan 120.000 TL'yi peşin tahsil etmesi durumunda, dönemsellik ilkesi gereğince gelecek yıla sarkan 9 aylık kısım (90.000 TL) hangi hesapta bekletilir?", "options": ["A) 600 Yurtiçi Satışlar", "B) 649 Diğer Olağan Gelirler", "C) 380 Gelecek Aylara Ait Gelirler", "D) 480 Gelecek Yıllara Ait Gelirler", "E) 180 Gelecek Aylara Ait Giderler"], "correct_answer": "D", "explanation": "Gelecek takvim yılına sarkan peşin gelirler 480 Gelecek Yıllara Ait Gelirler hesabında pasifte izlenir. Cari yılın gelecek aylarına ait olanlar ise 380 hesabında tutulur."}, {"id": 6, "unit": 5, "question": "İşletmenin satıcılara olan senetsiz veresiye ticari borçları hangi hesapta izlenir?", "options": ["A) 120 Alıcılar", "B) 320 Satıcılar", "C) 321 Borç Senetleri", "D) 300 Banka Kredileri", "E) 331 Ortaklara Borçlar"], "correct_answer": "B", "explanation": "Senetsiz ticari borçlar 320 Satıcılar hesabında takip edilir."}, {"id": 7, "unit": 5, "question": "Dönem sonunda borç senetlerinin bilançoda peşin değeriyle gösterilmesi için yapılan reeskont kaydında ALACAKLANDIRILAN hesap hangisidir?", "options": ["A) 657 Reeskont Faiz Giderleri", "B) 647 Reeskont Faiz Gelirleri", "C) 322 Borç Senetleri Reeskontu", "D) 321 Borç Senetleri", "E) 122 Alacak Senetleri Reeskontu"], "correct_answer": "B", "explanation": "Borç senetleri reeskont kaydı: 322 Borç Senetleri Reeskontu BORÇLU / 647 Reeskont Faiz Gelirleri ALACAKLI."}, {"id": 8, "unit": 6, "question": "Şirket ortaklarının taahhüt ettikleri sermaye borcunu henüz ödemediklerini gösteren ve pasifte eksi (-) karakterli çalışan hesap hangisidir?", "options": ["A) 500 Sermaye", "B) 501 Ödenmemiş Sermaye (-)", "C) 520 Hisse Senedi İhraç Primleri", "D) 540 Yasal Yedekler", "E) 580 Geçmiş Yıllar Zararları"], "correct_answer": "B", "explanation": "501 Ödenmemiş Sermaye (-) pasifte yer almasına karşın taahhüdün ödenmeyen kısmını gösteren borç karakterli düzenleyici hesaptır."}, {"id": 9, "unit": 6, "question": "Türk Ticaret Kanunu (TTK) hükümlerine göre şirketlerin safi kârları üzerinden ayırmak zorunda oldukları yedek akçe türü nedir?", "options": ["A) Statü Yedekleri", "B) Olağanüstü Yedekler", "C) Yasal Yedekler", "D) Özel Fonlar", "E) Sermaye Yedekleri"], "correct_answer": "C", "explanation": "TTK gereğince ayrılması zorunlu olan yedekler 540 Yasal Yedekler hesabında toplanır."}, {"id": 10, "unit": 6, "question": "Yeni çıkarılan hisse senetlerinin üzerinde yazılı nominal değerinden daha yüksek bir fiyatla satılması durumunda oluşan kâr payı hangi hesapta izlenir?", "options": ["A) 600 Yurtiçi Satışlar", "B) 520 Hisse Senedi İhraç Primleri (Emisyon Primi)", "C) 540 Yasal Yedekler", "D) 645 Menkul Kıymet Satış Kârları", "E) 500 Sermaye"], "correct_answer": "B", "explanation": "Hisse senetlerinin nominal değerinin üzerinde ihraç edilmesinden doğan primler 520 Hisse Senedi İhraç Primleri hesabına alınır."}, {"id": 11, "unit": 7, "question": "Brüt Satışları 500.000 TL, Satış İndirimleri 40.000 TL ve Satılan Ticari Mallar Maliyeti (STMM) 310.000 TL olan bir işletmenin Brüt Satış Kârı kaç TL'dir?", "options": ["A) 190.000 TL", "B) 150.000 TL", "C) 160.000 TL", "D) 230.000 TL", "E) 120.000 TL"], "correct_answer": "B", "explanation": "Net Satışlar = 500.000 - 40.000 = 460.000 TL. Brüt Satış Kârı = Net Satışlar - STMM = 460.000 - 310.000 = 150.000 TL."}, {"id": 12, "unit": 7, "question": "Bir işletmenin Brüt Satış Kârı 200.000 TL, Pazarlama Satış Dağıtım Giderleri 40.000 TL ve Genel Yönetim Giderleri 60.000 TL ise Faaliyet Kârı kaç TL olur?", "options": ["A) 100.000 TL", "B) 140.000 TL", "C) 160.000 TL", "D) 300.000 TL", "E) 80.000 TL"], "correct_answer": "A", "explanation": "Faaliyet Kârı = Brüt Satış Kârı - Faaliyet Giderleri = 200.000 - (40.000 + 60.000) = 100.000 TL."}, {"id": 13, "unit": 7, "question": "Dönem içinde 7/A seçeneğine göre 770 Genel Yönetim Giderleri hesabına kaydedilen tutarlar dönem sonunda hangi yansıtma hesabı aracılığıyla gelir tablosuna devredilir?", "options": ["A) 771 Genel Yönetim Giderleri Yansıtma Hesabı", "B) 761 Pazarlama Giderleri Yansıtma", "C) 632 Genel Yönetim Giderleri", "D) 690 Dönem Kârı veya Zararı", "E) 153 Ticari Mallar"], "correct_answer": "A", "explanation": "770 hesabındaki giderler 771 yansıtma hesabı alacaklandırılarak 632 Genel Yönetim Giderleri hesabına devredilir."}, {"id": 14, "unit": 8, "question": "İşletmenin varlık ve borçlarının fiilen sayılıp ölçülerek gerçek durumun belirlenmesine ne ad verilir?", "options": ["A) Muhasebe İçi Envanter", "B) Muhasebe Dışı Envanter", "C) Kesin Mizan", "D) Kapanış Kaydı", "E) Reeskont"], "correct_answer": "B", "explanation": "Fiziki sayım ve tespit işlemleri Muhasebe Dışı Envanterdir."}, {"id": 15, "unit": 8, "question": "Dönem sonunda tüm gelir hesapları (600, 642 vb.) kapatılırken hangi hesaba devredilir?", "options": ["A) 500 Sermaye", "B) 690 Dönem Kârı veya Zararı", "C) 590 Dönem Net Kârı", "D) 100 Kasa", "E) 770 Genel Yönetim"], "correct_answer": "B", "explanation": "Gelir ve gider hesapları 690 Dönem Kârı veya Zararı hesabına devredilerek kapatılır."}, {"id": 16, "unit": 8, "question": "Dönem sonu kapanış kayıtları sırasında borç kalanı veren aktif hesaplar nasıl kapatılır?", "options": ["A) Borçlandırılarak", "B) Alacaklandırılarak", "C) Nazım hesaplara yazılarak", "D) 690 hesaba borç yazılarak", "E) Silinerek"], "correct_answer": "B", "explanation": "Borç kalanı veren aktif hesaplar ALACAKLANDIRILARAK sıfırlanır ve kapatılır."}, {"id": 17, "unit": 8, "question": "690 Dönem Kârı veya Zararı hesabının alacak toplamı 600.000 TL, borç toplamı 450.000 TL ise işletmenin dönem sonucu nedir?", "options": ["A) 150.000 TL Dönem Kârı", "B) 150.000 TL Dönem Zararı", "C) 1.050.000 TL Toplam Varlık", "D) Sıfır sonuç", "E) 450.000 TL Vergi"], "correct_answer": "A", "explanation": "Alacak tarafı gelirleri, borç tarafı giderleri gösterir. Gelirler (600.000) > Giderler (450.000) olduğunda 150.000 TL KÂR oluşur."}, {"id": 18, "unit": 8, "question": "Alacak senetlerinin dönem sonunda peşin değerine indirgenmesi için yapılan reeskont kaydında BORÇLANDIRILAN hesap hangisidir?", "options": ["A) 122 Alacak Senetleri Reeskontu", "B) 657 Reeskont Faiz Giderleri", "C) 647 Reeskont Faiz Gelirleri", "D) 121 Alacak Senetleri", "E) 322 Borç Senetleri Reeskontu"], "correct_answer": "B", "explanation": "Alacak senedi reeskont kaydı: 657 Reeskont Faiz Giderleri BORÇLU / 122 Alacak Senetleri Reeskontu ALACAKLI."}, {"id": 19, "unit": 8, "question": "Aşağıdakilerden hangisi bir 'Muhasebe İçi Envanter' işlemidir?", "options": ["A) Kasadaki paraların tek tek sayılması", "B) Depodaki ticari malların sayılıp listelenmesi", "C) Amortisman paylarının hesaplanıp yevmiyeye kaydedilmesi", "D) Müşterilere teyit mektubu (mutabakat) gönderilmesi", "E) Banka cüzdanının bankadan istenmesi"], "correct_answer": "C", "explanation": "Amortisman ayırma, reeskont hesaplama ve gelir-gider devir kayıtları muhasebe içi envanter işlemleridir."}, {"id": 20, "unit": 8, "question": "Dönemin en son kaydı olan bilanço hesaplarının kapatılması işleminde ALACAKLANDIRILAN hesaplar hangileridir?", "options": ["A) Aktif hesaplar", "B) Pasif hesaplar", "C) Gelir hesapları", "D) Gider hesapları", "E) Öz kaynak hesapları"], "correct_answer": "A", "explanation": "Kapanış kaydında borç kalanı veren Aktif hesaplar alacaklandırılır, alacak kalanı veren Pasif hesaplar borçlandırılır."}]}, {"title": "Final Deneme Sınavı 2", "filename": "Final_Deneme_2.md", "questions": [{"id": 1, "unit": 1, "question": "(Vize Tekrarı) Bir işletmenin varlıklarının toplamı 900.000 TL, öz kaynakları 400.000 TL ise yabancı kaynakları (borçları) kaç TL'dir?", "options": ["A) 1.300.000 TL", "B) 500.000 TL", "C) 400.000 TL", "D) 900.000 TL", "E) 200.000 TL"], "correct_answer": "B", "explanation": "Varlıklar = Borçlar + Özkaynaklar. 900.000 = Borçlar + 400.000 -> Borçlar = 500.000 TL."}, {"id": 2, "unit": 2, "question": "(Vize Tekrarı) Kasadan nakit para çıkışı olduğunda düzenlenen belge hangisidir?", "options": ["A) Kasa Tahsil Fişi", "B) Kasa Tediye Fişi", "C) Mahsup Fişi", "D) Dekont", "E) Fatura"], "correct_answer": "B", "explanation": "Kasadan ödeme/çıkış yapıldığında Kasa Tediye Fişi kesilir."}, {"id": 3, "unit": 3, "question": "(Vize Tekrarı) Müşterilerden vadeli olarak alınan bonolar ve poliçeler hangi hesapta izlenir?", "options": ["A) 120 Alıcılar", "B) 121 Alacak Senetleri", "C) 101 Alınan Çekler", "D) 321 Borç Senetleri", "E) 110 Hisse Senetleri"], "correct_answer": "B", "explanation": "Senetli alacaklar 121 Alacak Senetleri hesabında izlenir."}, {"id": 4, "unit": 4, "question": "(Vize Tekrarı) 60.000 TL maliyetli bir demirbaş için 5 yıl ömür üzerinden Normal Amortisman yöntemi uygulandığında yıllık amortisman oranı yüzde kaçtır?", "options": ["A) %10", "B) %20", "C) %25", "D) %40", "E) %50"], "correct_answer": "B", "explanation": "Oran = 1 / 5 = %20."}, {"id": 5, "unit": 5, "question": "İşletmenin bankalardan sağladığı 1 yıldan kısa vadeli nakit krediler hangi hesapta izlenir?", "options": ["A) 102 Bankalar", "B) 300 Banka Kredileri", "C) 400 Banka Kredileri", "D) 320 Satıcılar", "E) 303 Uzun Vadeli Krediler"], "correct_answer": "B", "explanation": "Kısa vadeli banka kredileri 300 Banka Kredileri hesabında izlenir."}, {"id": 6, "unit": 5, "question": "Vadesi bir yılın altına inen uzun vadeli banka kredilerinin anapara ve faiz taksitleri dönem sonunda hangi hesaba aktarılır?", "options": ["A) 300 Banka Kredileri", "B) 303 Uzun Vadeli Kredilerin Anapara Taksitleri ve Faizleri", "C) 400 Banka Kredileri", "D) 320 Satıcılar", "E) 102 Bankalar"], "correct_answer": "B", "explanation": "Uzun vadeli kredilerin vadesi 1 yılın altına inen kısımları 303 no'lu hesaba virmanlanır."}, {"id": 7, "unit": 5, "question": "Veresiye mal alımından doğan borçlar için düzenlenen bono veya poliçeler hangi hesapta izlenir?", "options": ["A) 320 Satıcılar", "B) 321 Borç Senetleri", "C) 121 Alacak Senetleri", "D) 103 Verilen Çekler", "E) 300 Banka Kredileri"], "correct_answer": "B", "explanation": "Senetli ticari borçlar 321 Borç Senetleri hesabında izlenir."}, {"id": 8, "unit": 6, "question": "Şirketin ana sözleşmesinde belirlenen ve ortakların taahhüt ettiği sermaye tutarı hangi hesapta izlenir?", "options": ["A) 500 Sermaye", "B) 501 Ödenmemiş Sermaye", "C) 540 Yasal Yedekler", "D) 520 Hisse Senedi Primleri", "E) 590 Dönem Kârı"], "correct_answer": "A", "explanation": "Nominal taahhüt edilen sermaye 500 Sermaye hesabında alacaklı takip edilir."}, {"id": 9, "unit": 6, "question": "Şirket genel kurulunun kararıyla serbestçe ayrılmasına karar verilen yedek akçeler hangisidir?", "options": ["A) Yasal Yedekler", "B) Statü Yedekleri", "C) Olağanüstü Yedekler", "D) Emisyon Primi", "E) Karşılıklar"], "correct_answer": "C", "explanation": "Genel kurul kararıyla ayrılan ihtiyari yedekler 542 Olağanüstü Yedeklerdir."}, {"id": 10, "unit": 6, "question": "Geçmiş faaliyet dönemlerinden devreden kâr birikimleri bilançoda hangi hesapta yer alır?", "options": ["A) 590 Dönem Net Kârı", "B) 570 Geçmiş Yıllar Kârları", "C) 580 Geçmiş Yıllar Zararları", "D) 540 Yasal Yedekler", "E) 600 Yurtiçi Satışlar"], "correct_answer": "B", "explanation": "Geçmiş yıllardan devreden kârlar 570 Geçmiş Yıllar Kârları hesabında gösterilir."}, {"id": 11, "unit": 7, "question": "Satılan malların müşteriler tarafından geri iade edilmesi durumunda aşağıdaki hesaplardan hangisi BORÇLU çalışır?", "options": ["A) 600 Yurtiçi Satışlar", "B) 610 Satıştan İadeler (-)", "C) 611 Satış İskontoları", "D) 391 Hesaplanan KDV", "E) 621 STMM"], "correct_answer": "B", "explanation": "Satıştan iadeler 610 Satıştan İadeler (-) hesabının borcuna kaydedilir."}, {"id": 12, "unit": 7, "question": "İşletmenin bankadaki mevduat hesabına tahakkuk eden faiz geliri hangi hesaba ALACAK kaydedilir?", "options": ["A) 102 Bankalar", "B) 642 Faiz Gelirleri", "C) 780 Finansman Giderleri", "D) 600 Yurtiçi Satışlar", "E) 657 Reeskont Giderleri"], "correct_answer": "B", "explanation": "Mevduat faiz gelirleri 642 Faiz Gelirleri hesabına alacak yazılır (102 Bankalar borçlu)."}, {"id": 13, "unit": 7, "question": "İşletmenin kullandığı banka kredisi nedeniyle ödediği faiz ve komisyon giderleri hangi hesapta izlenir?", "options": ["A) 642 Faiz Gelirleri", "B) 660 Kısa Vadeli Borçlanma Giderleri (veya 780 Finansman Giderleri)", "C) 770 Genel Yönetim Giderleri", "D) 656 Kambiyo Zararları", "E) 300 Banka Kredileri"], "correct_answer": "B", "explanation": "Borçlanma faizleri 780 Finansman Giderleri veya gelir tablosunda 660 Finansman Giderlerinde izlenir."}, {"id": 14, "unit": 8, "question": "Dönem sonunda 690 Dönem Kârı veya Zararı hesabının borç kalanı vermesi durumunda bu tutar hangi hesaba aktarılır?", "options": ["A) 590 Dönem Net Kârı", "B) 692 Dönem Net Kârı veya Zararı (Zarar olarak)", "C) 500 Sermaye", "D) 100 Kasa", "E) 540 Yasal Yedekler"], "correct_answer": "B", "explanation": "690 borç kalanı verirse dönem zararla sonuçlanmıştır ve 692 hesabına devredilir."}, {"id": 15, "unit": 8, "question": "Dönem sonunda gider hesapları (621, 631, 632 vb.) kapatılırken hangi işlem yapılır?", "options": ["A) Gider hesapları borçlandırılır.", "B) Gider hesapları alacaklandırılır ve 690 hesap borçlandırılır.", "C) 500 Sermaye hesabı borçlandırılır.", "D) Gider hesapları silinir.", "E) Kasa hesabı alacaklandırılır."], "correct_answer": "B", "explanation": "Gider hesapları alacaklandırılarak kapatılır ve toplam tutar 690 hesabın borcuna yazılır."}, {"id": 16, "unit": 8, "question": "Aşağıdakilerden hangisi bir 'Muhasebe Dışı Envanter' işlemidir?", "options": ["A) Kasa sayım farkı kaydı yapılması", "B) Depodaki malların fiziki olarak sayılıp tartılması", "C) Şüpheli alacak karşılığı ayrılması", "D) Amortisman kaydı yapılması", "E) Kapanış kaydı yapılması"], "correct_answer": "B", "explanation": "Fiziki tartım ve sayım muhasebe dışı envanterdir."}, {"id": 17, "unit": 8, "question": "Dönem sonu kesin mizanı hangi aşamada düzenlenir?", "options": ["A) Dönem başında", "B) Envanter işlemlerine başlamadan önce", "C) Envanter ve düzeltme kayıtları tamamlandıktan sonra, bilançodan hemen önce", "D) Kapanış kaydından sonra", "E) Her ay başında"], "correct_answer": "C", "explanation": "Kesin mizan, tüm envanter düzeltmeleri yapıldıktan sonra bilançonun hazırlanmasından hemen önce çıkarılır."}, {"id": 18, "unit": 8, "question": "Dönem sonunda alacak senetlerine reeskont ayrıldığında kullanılan 122 Alacak Senetleri Reeskontu (-) hesabı bilançoda nerede yer alır?", "options": ["A) Aktifte, Ticari Alacaklar grubunda indirim kalemi olarak", "B) Pasifte, Kısa Vadeli Yabancı Kaynaklarda", "C) Gelir Tablosunda", "D) Öz Kaynaklarda", "E) Nazım Hesaplarda"], "correct_answer": "A", "explanation": "122 hesabı aktifte Ticari Alacaklar içinde alacak senetlerinin altında eksi (-) olarak yer alır."}, {"id": 19, "unit": 8, "question": "Kapanış yevmiye kaydında borçlandırılan hesap grubu aşağıdakilerden hangisidir?", "options": ["A) Aktif karakterli hesaplar", "B) Pasif karakterli hesaplar (Kaynaklar)", "C) Gelir hesapları", "D) Gider hesapları", "E) Maliyet hesapları"], "correct_answer": "B", "explanation": "Kapanış kaydında alacak kalanı veren Pasif hesaplar BORÇLANDIRILARAK sıfırlanır."}, {"id": 20, "unit": 8, "question": "Faaliyet dönemi sonunda net kâr elde edilmesi durumunda bu tutar bilançonun hangi grubunda öz kaynakları artırıcı bir unsur olarak yer alır?", "options": ["A) 1 Dönen Varlıklar", "B) 3 Kısa Vadeli Yabancı Kaynaklar", "C) 5 Öz Kaynaklar (590 Dönem Net Kârı)", "D) 2 Duran Varlıklar", "E) 4 Uzun Vadeli Yabancı Kaynaklar"], "correct_answer": "C", "explanation": "Dönem net kârı bilançoda 5 Öz Kaynaklar grubunda 590 Dönem Net Kârı hesabında pozitif olarak yer alır."}]}]}, "matematik_1": {"course_name": "MATEMATİK I", "course_code": "MAT105U", "faculty": "İşletme / İktisat Fakültesi - Yönetim Bilişim Sistemleri (YBS)", "term": "1. Sınıf Güz Dönemi", "description": "Kümeler ve sayılar, fonksiyonlar ve grafikleri, polinomlar, üstel ve logaritmik fonksiyonlar, limit, süreklilik, türev, matrisler, determinantlar, çok değişkenli fonksiyonlar ve iktisadi uygulamalar.", "units": [{"unit_number": 1, "title": "Kümeler ve Sayılar", "is_vize": true, "key_topics": ["Kümelerde İşlemler", "Alt Küme ve Özalt Küme", "De Morgan Kuralları", "Sayı Kümeleri", "Mutlak Değer"], "hap_bilgiler": ["Alt Küme Sayısı Formülü: n elemanlı bir kümenin alt küme sayısı 2^n, kendisi hariç özalt küme sayısı ise 2^n - 1'dir. Örn: 4 elemanlı bir kümenin 2^4 = 16 alt kümesi, 15 özalt kümesi vardır.", "Birleşim ve Kesişim Eleman Sayısı: s(A ∪ B) = s(A) + s(B) - s(A ∩ B). Eğer A ve B ayrık kümeler ise (kesişimleri boş küme) s(A ∪ B) = s(A) + s(B)'dir.", "De Morgan Kuralları: (A ∪ B)' = A' ∩ B' ve (A ∩ B)' = A' ∪ B'. Birleşimin tümleyeni tümleyenlerin kesişimine eşittir.", "Sayı Kümeleri Hiyerarşisi: N (Doğal Sayılar: {0,1,2,...}) ⊂ Z (Tam Sayılar: {...,-2,-1,0,1,2,...}) ⊂ Q (Rasyonel Sayılar: a/b şeklinde yazılabilenler) ⊂ R (Gerçel/Reel Sayılar).", "İrrasyonel Sayılar (Q' veya I): a/b şeklinde yazılamayan, virgülden sonra devretmeksizin sonsuza giden sayılardır. √2, √3, pi (π ≈ 3.14159) ve e (≈ 2.71828) en klasik irrasyonel sayılardır.", "Mutlak Değer Özellikleri:", "  - Her x gerçel sayısı için |x| ≥ 0'dır.", "  - |-x| = |x| ve |x * y| = |x| * |y|.", "  - Üçgen Eşitsizliği: |x + y| ≤ |x| + |y|.", "  - a > 0 olmak üzere; |x| < a ise -a < x < a'dır. |x| > a ise x > a veya x < -a'dır."]}, {"unit_number": 2, "title": "Fonksiyonlar", "is_vize": true, "key_topics": ["Fonksiyon Tanımı ve Kümeleri", "Bire-Bir ve Örtenlik", "Ters Fonksiyon", "Bileşke İşlemi", "Tek ve Çift Fonksiyonlar"], "hap_bilgiler": ["Fonksiyon Olma Şartı: f: A -> B için tanım kümesi A'nın her elemanı değer kümesi B'den yalnız bir elemanla eşleşmelidir. A'da açıkta eleman kalamaz, ancak B'de kalabilir.", "Bire-Bir (Injective) Fonksiyon: Farklı elemanların görüntüleri de farklı olmalıdır (x1 ≠ x2 => f(x1) ≠ f(x2)). Grafiğe çizilen yatay doğrular grafiği en fazla bir noktada kesmelidir (Yatay Doğru Testi).", "Örten (Surjective) Fonksiyon: Değer kümesinde açıkta hiç eleman kalmamasıdır (f(A) = B). Değer kümesinde açıkta eleman kalırsa fonksiyona 'İçine Fonksiyon' denir.", "Ters Fonksiyon (f^-1): Bir fonksiyonun tersinin olabilmesi için fonksiyonun MUTLAKA hem BİRE-BİR hem de ÖRTEN (Biyektif) olması şarttır! y = f(x) <=> x = f^-1(y). Bir fonksiyonun grafiği ile tersinin grafiği y = x doğrusuna göre simetriktir.", "Doğrusal Fonksiyonun Tersi: f(x) = ax + b ise f^-1(x) = (x - b) / a'dır. Örn: f(x) = 2x + 6 => f^-1(x) = (x - 6) / 2.", "Bileşke Fonksiyon: (f o g)(x) = f(g(x)). Bileşke işleminin değişme özelliği yoktur: (f o g) ≠ (g o f). Ancak birleşme özelliği vardır: f o (g o h) = (f o g) o h.", "Çift Fonksiyon: f(-x) = f(x) olan fonksiyondur. Grafiği y eksenine göre simetriktir (Örn: f(x) = x^2, f(x) = cos x, f(x) = |x|).", "Tek Fonksiyon: f(-x) = -f(x) olan fonksiyondur. Grafiği orijine (0,0) göre simetriktir (Örn: f(x) = x^3, f(x) = sin x, f(x) = x)."]}, {"unit_number": 3, "title": "Polinom Fonksiyonlar", "is_vize": true, "key_topics": ["Doğrusal Fonksiyonlar ve Eğim", "Paralel ve Dik Doğrular", "İkinci Dereceden Fonksiyonlar (Parabol)", "Tepe Noktası ve Diskriminant"], "hap_bilgiler": ["Doğrunun Eğimi (m): A(x1, y1) ve B(x2, y2) noktalarından geçen doğrunun eğimi m = (y2 - y1) / (x2 - x1)'dir. y = mx + n denkleminde x'in katsayısı m eğimdir, n ise doğrunun y eksenini kestiği noktadır.", "Paralel Doğrular: Eğilimleri birbirine eşittir (d1 // d2 => m1 = m2).", "Dik Doğrular: Birbirine dik iki doğrunun eğimleri çarpımı -1'dir (d1 ⊥ d2 => m1 * m2 = -1 => m2 = -1 / m1).", "İkinci Dereceden Fonksiyon (Parabol): f(x) = ax^2 + bx + c (a ≠ 0).", "  - a > 0 ise kollar YUKARI doğrudur ve fonksiyon tepe noktasında en küçük (MİNİMUM) değerini alır.", "  - a < 0 ise kollar AŞAĞI doğrudur ve fonksiyon tepe noktasında en büyük (MAKSİMUM) değerini alır.", "Tepe Noktası Koordinatları T(r, k):", "  - r = -b / (2a) (Simetri ekseni x = r doğrusudur).", "  - k = f(r) = (4ac - b^2) / (4a) (Fonksiyonun alabileceği en büyük veya en küçük değerdir).", "Diskriminant (Δ = b^2 - 4ac):", "  - Δ > 0 ise parabol x eksenini iki farklı noktada keser (2 gerçel kök vardır).", "  - Δ = 0 ise parabol x eksenine teğettir (çakışık/çift katlı tek gerçel kök vardır: x1 = x2 = -b / (2a)).", "  - Δ < 0 ise parabol x eksenini hiç kesmez (gerçel kök yoktur).", "Kökler Bağıntıları: Kökler toplamı x1 + x2 = -b / a, Kökler çarpımı x1 * x2 = c / a."]}, {"unit_number": 4, "title": "Üstel ve Logaritmik Fonksiyonlar", "is_vize": true, "key_topics": ["Üstel Fonksiyon Tanımı", "Doğal Üstel Fonksiyon (e^x)", "Logaritma Tanımı ve Özellikleri", "Doğal Logaritma (ln x)"], "hap_bilgiler": ["Üstel Fonksiyon: f(x) = a^x (a > 0 ve a ≠ 1).", "  - a > 1 ise fonksiyon artandır.", "  - 0 < a < 1 ise fonksiyon azalandır.", "  - Tanım kümesi tüm gerçel sayılar (-∞, +∞), görüntü kümesi pozitif gerçel sayılardır (0, +∞). Grafiği daima (0, 1) noktasından geçer.", "Doğal Üstel Fonksiyon: Tabanı Euler sayısı (e ≈ 2.71828) olan f(x) = e^x fonksiyonudur.", "Logaritma Fonksiyonu: Üstel fonksiyonun tersidir. y = log_a(x) <=> a^y = x (x > 0, a > 0, a ≠ 1). Logaritması alınan sayı x daima KESİNLİKLE pozitif (> 0) olmalıdır!", "Temel Logaritma Kuralları:", "  - log_a(1) = 0 ve log_a(a) = 1.", "  - log_a(x * y) = log_a(x) + log_a(y) (Çarpımın logaritması toplamdır).", "  - log_a(x / y) = log_a(x) - log_a(y) (Bölümün logaritması farktır).", "  - log_a(x^k) = k * log_a(x) (Kuvvet başa katsayı olarak düşer).", "  - Taban Değiştirme Kuralı: log_a(b) = ln(b) / ln(a) = log(b) / log(a).", "Doğal Logaritma (ln): Tabanı e olan logaritmadır. ln(x) = log_e(x). ln(e) = 1, ln(1) = 0, ln(e^k) = k."]}, {"unit_number": 5, "title": "Limit, Süreklilik ve Türev", "is_vize": false, "key_topics": ["Limit Tanımı ve Özellikleri", "0/0 Belirsizliği ve L'Hopital", "Süreklilik Şartları", "Türev Tanımı ve Geometrik Anlamı", "Temel Türev Alma Kuralları"], "hap_bilgiler": ["Limit Varlık Şartı: Bir f(x) fonksiyonunun x = a noktasında limitinin olması için sağdan ve soldan limitlerinin birbirine eşit olması gerekir: lim_{x->a^+} f(x) = lim_{x->a^-} f(x) = L.", "0/0 Belirsizliği ve L'Hopital Kuralı: lim_{x->a} f(x)/g(x) işleminde 0/0 çıkarsa, pay ve paydanın ayrı ayrı türevi alınarak limit tekrar hesaplanır: lim [f'(x) / g'(x)].", "Süreklilik Şartları (3 Şart Birlikte Sağlanmalı): 1. f(a) tanımlı olmalıdır, 2. x -> a iken limit var olmalıdır, 3. lim_{x->a} f(x) = f(a) olmalıdır.", "Türevin Geometrik Anlamı: f'(x0), f(x) eğrisine x0 noktasında çizilen teğet doğrusunun eğimine eşittir (mt = f'(x0)).", "Temel Türev Alma Kuralları:", "  - Sabit sayının türevi sıfırdır: (c)' = 0.", "  - Kuvvet kuralı: (x^n)' = n * x^(n-1). Örn: (x^3)' = 3x^2, (5x^4)' = 20x^3, (x)' = 1.", "  - Çarpımın Türevi: (f * g)' = f' * g + f * g'.", "  - Bölümün Türevi: (f / g)' = (f' * g - f * g') / (g^2).", "  - Zincir Kuralı (Bileşke Türevi): [f(g(x))]' = f'(g(x)) * g'(x).", "  - Üstel ve Logaritmik Türevler: (e^x)' = e^x, (e^(kx))' = k * e^(kx), (ln x)' = 1 / x, (ln(g(x)))' = g'(x) / g(x)."]}, {"unit_number": 6, "title": "Matrisler ve Doğrusal Denklem Sistemleri", "is_vize": false, "key_topics": ["Matris Boyutu ve Türleri", "Matris Çarpımı Kuralları", "Determinant Hesaplama (2x2 ve 3x3)", "Ters Matris ve Cramer Kuralı"], "hap_bilgiler": ["Matris Boyutu: m satır ve n sütundan oluşan tabloya m x n matris denir. Kare matriste satır ve sütun sayısı eşittir (m = n).", "Matris Çarpımı Şartı: A_(m x k) ile B_(k x n) çarpılabilir ve sonuç C_(m x n) boyutunda olur. Yani birinci matrisin SÜTUN sayısı, ikinci matrisin SATIR sayısına eşit olmak zorundadır! Matris çarpımında değişme özelliği yoktur: A * B ≠ B * A.", "Birim Matris (I): Asal köşegeni 1, diğer tüm elemanları 0 olan kare matristir. Her A matrisi için A * I = I * A = A'dır.", "2x2 Determinant: det |a b; c d| = a * d - b * c (Asal köşegen çarpımı eksi yedek köşegen çarpımı).", "Determinant Özellikleri: det(A^T) = det(A), det(A * B) = det(A) * det(B). Bir matrisin iki satırı veya sütunu aynıysa ya da orantılıysa determinantı 0'dır.", "Ters Matris (A^-1): Bir kare matrisin tersinin olabilmesi için det(A) ≠ 0 (tekil olmayan / regüler) olması şarttır! Eğer det(A) = 0 ise matris tektir (singüler) ve tersi yoktur!", "2x2 Ters Matris Formülü: A = [a b; c d] ise A^-1 = (1 / det(A)) * [d -b; -c a]. Asal köşegen yer değiştirir, yedek köşegen işaret değiştirir.", "Cramer Kuralı: Ax = b sisteminde xi = det(Ai) / det(A). Ai matrisi, katsayılar matrisinin i. sütunu yerine b sonuç sütununun yazılmasıyla elde edilir."]}, {"unit_number": 7, "title": "Çok Değişkenli Fonksiyonlar", "is_vize": false, "key_topics": ["İki Değişkenli Fonksiyonlar", "Birinci Mertebeden Kısmi Türevler", "Schwarz Teoremi", "İkinci Mertebeden Kısmi Türevler ve Ekstremum"], "hap_bilgiler": ["Çok Değişkenli Fonksiyon: z = f(x, y) şeklinde birden fazla bağımsız değişkene sahip fonksiyonlardır.", "Kısmi Türev Mantığı:", "  - x'e göre kısmi türev (∂f/∂x veya fx): y bir sabit sayı kabul edilerek x'e göre türev alınır.", "  - y'ye göre kısmi türev (∂f/∂y veya fy): x bir sabit sayı kabul edilerek y'ye göre türev alınır.", "Schwarz Teoremi (Karma Kısmi Türevlerin Eşitliği): Eğer sürekli türevlenebiliyorsa fxy = fyx'tir. Yani önce x'e sonra y'ye türev almak ile önce y'ye sonra x'e türev almak aynı sonucu verir.", "İki Değişkenli Fonksiyonlarda Yerel Ekstremum (Maksimum/Minimum) Bulma Adımları:", "  1. Kritik Nokta: fx = 0 ve fy = 0 denklemleri ortak çözülerek kritik (x0, y0) noktaları bulunur.", "  2. Hessian Determinantı (D): D = fxx * fyy - (fxy)^2 hesaplanır.", "     - Eğer D > 0 ve fxx > 0 ise fonksiyon (x0, y0) noktasında bir YEREL MİNİMUM'a sahiptir.", "     - Eğer D > 0 ve fxx < 0 ise fonksiyon (x0, y0) noktasında bir YEREL MAKSİMUM'a sahiptir.", "     - Eğer D < 0 ise nokta bir EYER (SEMER) NOKTASI'dır (ne maksimum ne minimumdur).", "     - Eğer D = 0 ise test sonuçsuz kalır, başka yöntemlere bakılır."]}, {"unit_number": 8, "title": "İktisadi Uygulamalar", "is_vize": false, "key_topics": ["Piyasa Dengesi (Arz-Talep)", "Toplam ve Marjinal Hasılat", "Toplam ve Marjinal Maliyet", "Kâr Maksimizasyonu Kuralı (MR=MC)", "Talebin Fiyat Esnekliği"], "hap_bilgiler": ["Piyasa Denge Fiyatı ve Miktarı: Talep (Qd) ve Arz (Qs) fonksiyonları eşitlenerek bulunur: Qd = Qs => P* (denge fiyatı) bulunur, yerine konularak Q* (denge miktarı) elde edilir.", "Hasılat Fonksiyonları:", "  - Toplam Hasılat (TR - Total Revenue): TR = P * Q (Fiyat çarpı miktar).", "  - Marjinal Hasılat (MR - Marginal Revenue): Üretilen/satılan son birimin toplam hasılata katkısıdır. Toplam Hasılatın Q'ya göre 1. türevidir: MR = d(TR) / dQ.", "Maliyet Fonksiyonları:", "  - Toplam Maliyet (TC - Total Cost): TC = TFC (Sabit Maliyet) + TVC (Değişken Maliyet).", "  - Ortalama Maliyet (AC - Average Cost): AC = TC / Q.", "  - Marjinal Maliyet (MC - Marginal Cost): Bir birim ek üretimin maliyetidir. Toplam Maliyetin Q'ya göre 1. türevidir: MC = d(TC) / dQ.", "Kâr Maksimizasyonu Kuralı: Toplam Kâr (π) = TR - TC. Kârın maksimum olması için 1. türevin sıfır olması gerekir: dπ/dQ = 0 => MR - MC = 0 => MR = MC! Yani kârı maksimize eden üretim düzeyinde Marjinal Hasılat daima Marjinal Maliyete eşit olmalıdır.", "Talebin Fiyat Esnekliği Formülü: ε = (dQ / dP) * (P / Q). Q'nun fiyata göre türevi ile P/Q oranının çarpımıdır."]}], "sinav_tuzaklari": [{"id": 1, "title": "Kümelerde Alt Küme ile Özalt Küme Sayısı Karışıklığı", "mistake": "Özalt küme sorulduğunda doğrudan 2^n hesaplayıp işaretlemek.", "truth": "Alt küme sayısı 2^n'dir; ancak ÖZALT KÜME kümenin kendisi hariç tutulduğu için 2^n - 1'dir. 1 çıkarmayı kesinlikle unutmamalısın.", "tip": "Özalt küme = 2^n - 1 (Kendini çıkar)."}, {"id": 2, "title": "Rasyonel Sayı ile İrrasyonel Sayı Ayrımı (Karekök Tuzağı)", "mistake": "Karekök içindeki her sayının irrasyonel olduğunu düşünmek (örn: √9 veya √16).", "truth": "Kök dışına tam çıkan sayılar rasyoneldir (√9 = 3 rasyoneldir). Kök dışına çıkamayan sayılar (√2, √3, √5) ve pi (π), e sayıları irrasyoneldir.", "tip": "Kökten tam çıkıyorsa Rasyonel (Q), çıkamıyorsa İrrasyonel (Q')."}, {"id": 3, "title": "Ters Fonksiyon Varlık Şartı", "mistake": "Her fonksiyonun tersinin alınabileceğini zannetmek.", "truth": "Bir fonksiyonun tersinin var olabilmesi için fonksiyonun MUTLAKA hem BİRE-BİR hem de ÖRTEN olması gerekir. İkisinden biri eksikse ters fonksiyon tanımlanamaz.", "tip": "Ters fonksiyon = Bire-bir VE Örten (Biyektif) olmak zorundadır."}, {"id": 4, "title": "Parabolde Tepe Noktasının Maksimum mu Minimum mu Olduğu", "mistake": "a katsayısı pozitifken fonksiyonun maksimum değer aldığını sanmak.", "truth": "f(x) = ax^2 + bx + c fonksiyonunda a > 0 ise kollar YUKARI açılır ve çukurun dibi MİNİMUM değerdir. a < 0 ise kollar AŞAĞI iner ve tepe noktası MAKSİMUM değerdir.", "tip": "a > 0 => Gülen yüz (En dip = Minimum); a < 0 => Üzgün yüz (Zirve = Maksimum)."}, {"id": 5, "title": "Bir Doğruya Dik Olan Doğrunun Eğimi", "mistake": "Dik doğrunun eğimini bulurken sadece işaretini değiştirmek (m yerine -m almak).", "truth": "Dik iki doğrunun eğimleri çarpımı -1'dir (m1 * m2 = -1). Dolayısıyla dik doğrunun eğimi hem ters çevrilir hem işareti değişir: m2 = -1 / m1.", "tip": "Örn: m1 = 2 ise dik doğrunun eğimi -1/2'dir (sadece -2 değil!)."}, {"id": 6, "title": "Logaritmanın Tanım Kümesi Pozitiflik Şartı", "mistake": "log_a(x) ifadesinde x'in sıfır veya negatif olabileceğini varsaymak.", "truth": "Logaritması alınan sayı daima sıfırdan KESİNLİKLE BÜYÜK olmalıdır (x > 0). Taban da pozitif ve 1'den farklı olmalıdır (a > 0, a ≠ 1). log(0) tanımsızdır, negatifin logaritması reel sayılarda yoktur.", "tip": "Logaritmanın içi daima > 0 olmak zorundadır."}, {"id": 7, "title": "0/0 Belirsizliğinde L'Hopital Kuralı Uygulaması", "mistake": "Bölümün türev kuralını [(f'g - fg')/g^2] uygulamaya çalışmak.", "truth": "L'Hopital kuralında bölümün genel türevi ALINMAZ! Sadece payın türevi alınıp paya [f'(x)], paydanın türevi alınıp paydaya [g'(x)] yazılır.", "tip": "L'Hopital = Payın türevi / Paydanın türevi."}, {"id": 8, "title": "Matris Çarpımı Değişme Özelliği Yanılgısı", "mistake": "Sayılar gibi matrislerde de A * B = B * A olduğunu düşünmek.", "truth": "Matris çarpımında kural olarak DEĞİŞME ÖZELLİĞİ YOKTUR (A * B ≠ B * A). Çoğu zaman biri tanımlıyken diğeri boyut uyumsuzluğundan hesaplanamaz bile.", "tip": "A * B ile B * A matrislerde eşit DEĞİLDİR!"}, {"id": 9, "title": "Ters Matris Varlık Şartı (Determinant Sıfır Olma Durumu)", "mistake": "Her kare matrisin tersinin olduğunu varsaymak.", "truth": "Bir A matrisinin tersinin (A^-1) var olabilmesi için det(A) ≠ 0 olmalıdır. Determinantı 0 olan matrislere 'Tekil (Singüler)' matris denir ve tersleri YOKTUR.", "tip": "det(A) = 0 ise ters matris YOKTUR."}, {"id": 10, "title": "Kâr Maksimizasyonunda Türev Alma Tuzağı", "mistake": "Kârı bulmak için sadece fiyatı veya maliyeti sıfıra eşitlemek.", "truth": "Kârı maksimize eden miktar; Marjinal Hasılatın Marjinal Maliyete eşit olduğu (MR = MC) üretim düzeyidir. TR'nin türevi ile TC'nin türevi birbirine eşitlenir.", "tip": "Maksimum Kâr = MR'yi bul, MC'ye eşitle (MR = MC)."}], "formuller_ve_kavramlar": [{"term": "Alt Küme Formülü", "description": "n elemanlı bir kümenin alt küme sayısı = 2^n; özalt küme sayısı = 2^n - 1.", "example": "s(A) = 5 ise alt küme sayısı = 2^5 = 32, özalt küme = 31."}, {"term": "Kümeler Birleşim Formülü", "description": "s(A ∪ B) = s(A) + s(B) - s(A ∩ B)."}, {"term": "İki Noktadan Geçen Doğrunun Eğimi", "description": "m = (y2 - y1) / (x2 - x1).", "example": "A(1, 3) ve B(3, 7) noktaları için m = (7 - 3) / (3 - 1) = 4 / 2 = 2."}, {"term": "Dik Doğruların Eğimleri Bağıntısı", "description": "m1 * m2 = -1 => m2 = -1 / m1."}, {"term": "Parabol Tepe Noktası Koordinatları", "description": "f(x) = ax^2 + bx + c için r = -b / (2a) ve k = f(r) = (4ac - b^2) / (4a).", "example": "f(x) = x^2 - 4x + 7 için r = -(-4)/(2*1) = 2. k = f(2) = 4 - 8 + 7 = 3. Tepe noktası T(2, 3)."}, {"term": "Parabol Kökler ve Diskriminant", "description": "Δ = b^2 - 4ac. Kökler toplamı = -b / a, Kökler çarpımı = c / a."}, {"term": "Logaritma Çarpım ve Bölüm Kuralları", "description": "log(x * y) = log(x) + log(y) ve log(x / y) = log(x) - log(y)."}, {"term": "L'Hopital Kuralı", "description": "0/0 veya ∞/∞ belirsizliklerinde lim [f(x) / g(x)] = lim [f'(x) / g'(x)]."}, {"term": "Kuvvet Türev Kuralı", "description": "d(x^n)/dx = n * x^(n-1).", "example": "d(4x^3)/dx = 12x^2."}, {"term": "Çarpımın Türevi", "description": "(f * g)' = f' * g + f * g'."}, {"term": "Bölümün Türevi", "description": "(f / g)' = (f' * g - f * g') / (g^2)."}, {"term": "2x2 Matris Determinantı", "description": "det |a b; c d| = a * d - b * c.", "example": "det |3 2; 1 4| = 3*4 - 2*1 = 12 - 2 = 10."}, {"term": "2x2 Ters Matris Formülü", "description": "A^-1 = (1 / det(A)) * [d -b; -c a]."}, {"term": "Cramer Kuralı", "description": "xi = det(Ai) / det(A)."}, {"term": "Schwarz Teoremi", "description": "fxy = fyx (Karma ikinci mertebe kısmi türevler eşittir)."}, {"term": "Hessian Determinantı (Ekstremum)", "description": "D = fxx * fyy - (fxy)^2. D > 0 ve fxx > 0 ise Min; D > 0 ve fxx < 0 ise Max; D < 0 ise Eyer noktası."}, {"term": "Kâr Maksimizasyonu Şartı", "description": "MR = MC (Marjinal Hasılat = Marjinal Maliyet)."}, {"term": "Marjinal Hasılat (MR)", "description": "MR = d(TR) / dQ."}, {"term": "Marjinal Maliyet (MC)", "description": "MC = d(TC) / dQ."}, {"term": "Talebin Fiyat Esnekliği", "description": "ε = (dQ/dP) * (P/Q)."}], "flashcards": [{"id": 1, "unit": 1, "question": "4 elemanlı bir kümenin alt küme sayısı ile özalt küme sayısı kaçtır?", "answer": "Alt küme sayısı 2^4 = 16, özalt küme sayısı 16 - 1 = 15'tir."}, {"id": 2, "unit": 1, "question": "De Morgan kurallarına göre (A ∪ B)' ifadesinin eşiti nedir?", "answer": "A' ∩ B' (Tümleyenlerin kesişimidir)."}, {"id": 3, "unit": 1, "question": "√2, pi (π) ve e sayıları hangi sayı kümesinin elemanıdır?", "answer": "İrrasyonel Sayılar kümesinin (Q' veya I)."}, {"id": 4, "unit": 1, "question": "|x| < 5 eşitsizliğinin çözüm aralığı nedir?", "answer": "-5 < x < 5 veya (-5, 5) açık aralığıdır."}, {"id": 5, "unit": 2, "question": "Bir fonksiyonun tersinin (f^-1) var olabilmesi için gereken iki temel şart nedir?", "answer": "Fonksiyonun hem Bire-Bir hem de Örten olması gerekir."}, {"id": 6, "unit": 2, "question": "f(x) = 3x - 9 fonksiyonunun tersi f^-1(x) nedir?", "answer": "f^-1(x) = (x + 9) / 3."}, {"id": 7, "unit": 2, "question": "Grafiği y eksenine göre simetrik olan ve f(-x) = f(x) şartını sağlayan fonksiyona ne ad verilir?", "answer": "Çift Fonksiyon (örn: f(x) = x^2)."}, {"id": 8, "unit": 2, "question": "Grafiği orijine göre simetrik olan ve f(-x) = -f(x) şartını sağlayan fonksiyona ne ad verilir?", "answer": "Tek Fonksiyon (örn: f(x) = x^3)."}, {"id": 9, "unit": 3, "question": "y = 4x + 5 doğrusuna dik olan bir doğrunun eğimi kaçtır?", "answer": "-1/4'tür (m1 * m2 = -1 => 4 * m2 = -1 => m2 = -1/4)."}, {"id": 10, "unit": 3, "question": "f(x) = ax^2 + bx + c parabolünün tepe noktasının apsisi (r) hangi formülle bulunur?", "answer": "r = -b / (2a)."}, {"id": 11, "unit": 3, "question": "Bir parabolde diskriminant Δ = 0 ise parabolün x eksenine göre konumu nasıldır?", "answer": "Parabol x eksenine teğettir (tek bir noktada değer)."}, {"id": 12, "unit": 3, "question": "f(x) = -2x^2 + 8x - 5 parabolünün kolları ne tarafa bakar ve tepe noktasında hangi değeri alır?", "answer": "a = -2 < 0 olduğundan kolları aşağı bakar ve tepe noktasında Maksimum değerini alır."}, {"id": 13, "unit": 4, "question": "Doğal logaritma fonksiyonunda ln(e) ve ln(1) değerleri kaçtır?", "answer": "ln(e) = 1 ve ln(1) = 0'dır."}, {"id": 14, "unit": 4, "question": "log_a(x * y) ifadesi nasıl açılır?", "answer": "log_a(x) + log_a(y) şeklinde açılır."}, {"id": 15, "unit": 4, "question": "log_2(32) işleminin sonucu kaçtır?", "answer": "5'tir (Çünkü 2^5 = 32)."}, {"id": 16, "unit": 5, "question": "Bir noktada limitin var olması için sağ ve sol limitler arasında nasıl bir ilişki olmalıdır?", "answer": "Sağdan limit ile soldan limit birbirine eşit olmalıdır."}, {"id": 17, "unit": 5, "question": "Limit hesabında 0/0 belirsizliği çıktığında uygulanan kural nedir?", "answer": "L'Hopital Kuralı (Pay ve paydanın ayrı ayrı türevi alınır)."}, {"id": 18, "unit": 5, "question": "f(x) = 5x^4 - 3x^2 + 7 fonksiyonunun türevi f'(x) nedir?", "answer": "f'(x) = 20x^3 - 6x."}, {"id": 19, "unit": 5, "question": "f(x) = e^(3x) fonksiyonunun türevi nedir?", "answer": "f'(x) = 3 * e^(3x)."}, {"id": 20, "unit": 5, "question": "Türevin geometrik anlamı nedir?", "answer": "Fonksiyon grafiğine o noktadan çizilen teğet doğrusunun eğimidir (mt = f'(x0))."}, {"id": 21, "unit": 6, "question": "3 x 2 boyutunda bir A matrisi ile 2 x 4 boyutunda bir B matrisi çarpılırsa oluşan matrisin boyutu ne olur?", "answer": "3 x 4 boyutunda olur."}, {"id": 22, "unit": 6, "question": "A = [2 5; 1 3] matrisinin determinantı kaçtır?", "answer": "det(A) = 2*3 - 5*1 = 6 - 5 = 1'dir."}, {"id": 23, "unit": 6, "question": "Bir kare matrisin tersinin (A^-1) var olabilmesi için determinantı ne olmalıdır?", "answer": "Determinantı sıfırdan farklı olmalıdır (det(A) ≠ 0)."}, {"id": 24, "unit": 6, "question": "İki satırı birbirinin aynısı olan bir matrisin determinantı kaçtır?", "answer": "Sıfırdır (0)."}, {"id": 25, "unit": 7, "question": "f(x, y) = 3x^2 * y + 5y^3 fonksiyonunun x'e göre kısmi türevi (fx) nedir?", "answer": "fx = 6x * y (y sabit kabul edilir)."}, {"id": 26, "unit": 7, "question": "İkinci mertebe kısmi türevlerde fxy = fyx olduğunu belirten teoremin adı nedir?", "answer": "Schwarz Teoremi."}, {"id": 27, "unit": 7, "question": "Hessian determinantı D < 0 olan kritik noktaya ne ad verilir?", "answer": "Eyer (Semer) Noktası."}, {"id": 28, "unit": 8, "question": "Toplam maliyet TC = 2Q^2 + 10Q + 50 ise Marjinal Maliyet (MC) fonksiyonu nedir?", "answer": "MC = d(TC)/dQ = 4Q + 10."}, {"id": 29, "unit": 8, "question": "İktisatta kâr maksimizasyonunun altın kuralı nedir?", "answer": "MR = MC (Marjinal Hasılat = Marjinal Maliyet)."}, {"id": 30, "unit": 8, "question": "Piyasa denge fiyatı nasıl belirlenir?", "answer": "Talep fonksiyonu ile arz fonksiyonu birbirine eşitlenerek (Qd = Qs)."}], "exams": [{"title": "Vize Deneme Sınavı 1", "filename": "Vize_Deneme_1.md", "questions": [{"id": 1, "unit": 1, "question": "A = {a, b, c, d, e} kümesinin özalt küme sayısı kaçtır?", "options": ["A) 16", "B) 31", "C) 32", "D) 63", "E) 64"], "correct_answer": "B", "explanation": "Eleman sayısı n = 5'tir. Alt küme sayısı 2^5 = 32'dir. Özalt küme sayısı 2^n - 1 = 32 - 1 = 31'dir."}, {"id": 2, "unit": 1, "question": "s(A) = 12, s(B) = 8 ve s(A ∩ B) = 3 olduğuna göre, s(A ∪ B) kaçtır?", "options": ["A) 17", "B) 20", "C) 23", "D) 15", "E) 18"], "correct_answer": "A", "explanation": "s(A ∪ B) = s(A) + s(B) - s(A ∩ B) = 12 + 8 - 3 = 17."}, {"id": 3, "unit": 1, "question": "Aşağıdakilerden hangisi bir 'İrrasyonel Sayı'dır?", "options": ["A) 3/5", "B) -7", "C) √16", "D) √5", "E) 0"], "correct_answer": "D", "explanation": "√16 = 4 rasyoneldir. √5 ise kök dışına çıkamayan, devretmeyen sonsuz bir ondalıktır; dolayısıyla İrrasyoneldir."}, {"id": 4, "unit": 1, "question": "|2x - 6| < 10 eşitsizliğini sağlayan en büyük x tam sayısı kaçtır?", "options": ["A) 6", "B) 7", "C) 8", "D) 9", "E) 10"], "correct_answer": "B", "explanation": "-10 < 2x - 6 < 10 => her tarafa 6 ekle: -4 < 2x < 16 => 2'ye böl: -2 < x < 8. Bu aralıktaki en büyük tam sayı 7'dir."}, {"id": 5, "unit": 1, "question": "A ve B iki küme olmak üzere, (A ∪ B)' ifadesi De Morgan kuralına göre aşağıdakilerden hangisine eşittir?", "options": ["A) A' ∪ B'", "B) A' ∩ B'", "C) A ∩ B", "D) A' ∩ B", "E) A \\ B"], "correct_answer": "B", "explanation": "De Morgan kuralı: (A ∪ B)' = A' ∩ B' (Birleşimin tümleyeni, tümleyenlerin kesişimidir)."}, {"id": 6, "unit": 2, "question": "f(x) = 4x - 12 fonksiyonunun tersi f^-1(x) aşağıdakilerden hangisidir?", "options": ["A) (x + 12) / 4", "B) (x - 12) / 4", "C) 4x + 12", "D) -4x + 12", "E) (x + 4) / 12"], "correct_answer": "A", "explanation": "y = 4x - 12 => y + 12 = 4x => x = (y + 12) / 4. Dolayısıyla f^-1(x) = (x + 12) / 4."}, {"id": 7, "unit": 2, "question": "f(x) = 2x + 1 ve g(x) = x^2 olduğuna göre, (f o g)(3) bileşke işleminin sonucu kaçtır?", "options": ["A) 19", "B) 49", "C) 37", "D) 25", "E) 13"], "correct_answer": "A", "explanation": "(f o g)(3) = f(g(3)). g(3) = 3^2 = 9. f(9) = 2*9 + 1 = 18 + 1 = 19."}, {"id": 8, "unit": 2, "question": "Grafiği y eksenine göre simetrik olan ve f(-x) = f(x) özelliğini sağlayan fonksiyon türü hangisidir?", "options": ["A) Tek Fonksiyon", "B) Çift Fonksiyon", "C) Örten Fonksiyon", "D) Bire-Bir Fonksiyon", "E) İçine Fonksiyon"], "correct_answer": "B", "explanation": "y eksenine göre simetrik olan fonksiyonlar Çift Fonksiyonlardır."}, {"id": 9, "unit": 2, "question": "Aşağıdakilerden hangisi bir 'Tek Fonksiyon'dur?", "options": ["A) f(x) = x^2 + 4", "B) f(x) = x^3", "C) f(x) = cos x", "D) f(x) = |x|", "E) f(x) = 7"], "correct_answer": "B", "explanation": "f(-x) = (-x)^3 = -x^3 = -f(x). f(x) = x^3 tek fonksiyondur ve grafiği orijine göre simetriktir."}, {"id": 10, "unit": 2, "question": "Bir f fonksiyonunun tersinin tanımlı olabilmesi için fonksiyonun hangi özelliği taşıması zorunludur?", "options": ["A) Sadece örten olması", "B) Sadece çift fonksiyon olması", "C) Hem bire-bir hem de örten olması", "D) Sabit fonksiyon olması", "E) Tanım kümesinin doğal sayılar olması"], "correct_answer": "C", "explanation": "Ters fonksiyon ancak ve ancak fonksiyon bire-bir ve örten (biyektif) ise tanımlıdır."}, {"id": 11, "unit": 3, "question": "A(2, 5) ve B(4, 11) noktalarından geçen doğrunun eğimi kaçtır?", "options": ["A) 2", "B) 3", "C) 4", "D) 6", "E) 8"], "correct_answer": "B", "explanation": "m = (y2 - y1) / (x2 - x1) = (11 - 5) / (4 - 2) = 6 / 2 = 3."}, {"id": 12, "unit": 3, "question": "Eğimi 3 olan bir d1 doğrusuna dik olan d2 doğrusunun eğimi kaçtır?", "options": ["A) 3", "B) -3", "C) 1/3", "D) -1/3", "E) 0"], "correct_answer": "D", "explanation": "Dik doğruların eğimleri çarpımı -1'dir: m1 * m2 = -1 => 3 * m2 = -1 => m2 = -1/3."}, {"id": 13, "unit": 3, "question": "f(x) = x^2 - 6x + 14 parabolünün tepe noktasının koordinatları T(r, k) nedir?", "options": ["A) T(3, 5)", "B) T(-3, 5)", "C) T(3, -5)", "D) T(6, 14)", "E) T(2, 6)"], "correct_answer": "A", "explanation": "r = -b / (2a) = -(-6) / (2*1) = 6/2 = 3. k = f(3) = 3^2 - 6*3 + 14 = 9 - 18 + 14 = 5. Tepe noktası T(3, 5)."}, {"id": 14, "unit": 3, "question": "f(x) = -x^2 + 8x - 10 parabolünün alabileceği en büyük (maksimum) değer kaçtır?", "options": ["A) 4", "B) 6", "C) 8", "D) 10", "E) 16"], "correct_answer": "B", "explanation": "a = -1 < 0 olduğundan tepe noktasında maksimum değerini alır. r = -8 / (2*-1) = 4. k = f(4) = -(4^2) + 8*4 - 10 = -16 + 32 - 10 = 6."}, {"id": 15, "unit": 3, "question": "x^2 - 8x + 12 = 0 denkleminin kökler toplamı kaçtır?", "options": ["A) 4", "B) 8", "C) -8", "D) 12", "E) 6"], "correct_answer": "B", "explanation": "Kökler toplamı formülü = -b / a = -(-8) / 1 = 8."}, {"id": 16, "unit": 4, "question": "log_3(81) ifadesinin değeri kaçtır?", "options": ["A) 2", "B) 3", "C) 4", "D) 9", "E) 27"], "correct_answer": "C", "explanation": "81 = 3^4 olduğuna göre, log_3(3^4) = 4 * log_3(3) = 4 * 1 = 4."}, {"id": 17, "unit": 4, "question": "ln(x) = 2 denklemini sağlayan x değeri aşağıdakilerden hangisidir?", "options": ["A) 2e", "B) e^2", "C) 10^2", "D) √e", "E) 2/e"], "correct_answer": "B", "explanation": "ln tabanı e'dir. log_e(x) = 2 <=> x = e^2."}, {"id": 18, "unit": 4, "question": "log(2) = x ve log(3) = y olduğuna göre, log(6) ifadesinin x ve y türünden eşiti nedir?", "options": ["A) x * y", "B) x + y", "C) x - y", "D) y / x", "E) 2x + 3y"], "correct_answer": "B", "explanation": "log(6) = log(2 * 3) = log(2) + log(3) = x + y."}, {"id": 19, "unit": 4, "question": "f(x) = a^x üstel fonksiyonunun azalan bir fonksiyon olması için taban 'a' hangi aralıkta olmalıdır?", "options": ["A) a > 1", "B) a < 0", "C) 0 < a < 1", "D) a = 1", "E) a ≥ 2"], "correct_answer": "C", "explanation": "Üstel fonksiyonda 0 < a < 1 olduğunda fonksiyon azalandır; a > 1 olduğunda artandır."}, {"id": 20, "unit": 4, "question": "f(x) = log_2(x - 5) fonksiyonunun en geniş tanım kümesi aşağıdakilerden hangisidir?", "options": ["A) x ≥ 5", "B) (5, +∞)", "C) (-∞, 5)", "D) Tüm Gerçel Sayılar", "E) [5, +∞)"], "correct_answer": "B", "explanation": "Logaritmanın içi kesinlikle pozitif olmalıdır: x - 5 > 0 => x > 5, yani (5, +∞) açık aralığıdır."}]}, {"title": "Vize Deneme Sınavı 2", "filename": "Vize_Deneme_2.md", "questions": [{"id": 1, "unit": 1, "question": "Alt küme sayısı 64 olan bir kümenin eleman sayısı (n) kaçtır?", "options": ["A) 5", "B) 6", "C) 7", "D) 8", "E) 9"], "correct_answer": "B", "explanation": "2^n = 64 => 2^6 = 64 olduğuna göre eleman sayısı n = 6'dır."}, {"id": 2, "unit": 1, "question": "Aşağıdaki sayılardan hangisi bir rasyonel sayı değildir?", "options": ["A) 0", "B) -3/4", "C) 2,75", "D) π (Pi sayısı)", "E) √49"], "correct_answer": "D", "explanation": "π sayısı devretmeyen sonsuz bir ondalık olup irrasyoneldir."}, {"id": 3, "unit": 1, "question": "|3x - 9| = 0 denklemini sağlayan x değeri kaçtır?", "options": ["A) 0", "B) 3", "C) -3", "D) 9", "E) Çözüm yoktur"], "correct_answer": "B", "explanation": "Mutlak değerin sıfır olması için içinin sıfır olması gerekir: 3x - 9 = 0 => 3x = 9 => x = 3."}, {"id": 4, "unit": 1, "question": "s(A \\ B) = 7, s(B \\ A) = 4 ve s(A ∩ B) = 3 olduğuna göre, s(A ∪ B) kaçtır?", "options": ["A) 11", "B) 14", "C) 17", "D) 20", "E) 12"], "correct_answer": "B", "explanation": "s(A ∪ B) = s(A \\ B) + s(B \\ A) + s(A ∩ B) = 7 + 4 + 3 = 14."}, {"id": 5, "unit": 1, "question": "Boş kümenin alt küme sayısı kaçtır?", "options": ["A) 0", "B) 1", "C) 2", "D) Tanımsızdır", "E) Sonsuz"], "correct_answer": "B", "explanation": "Boş kümenin eleman sayısı 0'dır. Alt küme sayısı 2^0 = 1'dir (yalnızca kendisi)."}, {"id": 6, "unit": 2, "question": "f(x) = 5x + 10 fonksiyonu için f^-1(25) değeri kaçtır?", "options": ["A) 3", "B) 5", "C) 7", "D) 135", "E) 15"], "correct_answer": "A", "explanation": "f^-1(25) = k dersek f(k) = 25 olur. 5k + 10 = 25 => 5k = 15 => k = 3."}, {"id": 7, "unit": 2, "question": "f(x) = 3x - 2 ve g(x) = 2x + 4 olduğuna göre, (g o f)(x) bileşke fonksiyonu nedir?", "options": ["A) 6x", "B) 6x - 4", "C) 6x + 2", "D) 6x - 8", "E) 5x + 2"], "correct_answer": "A", "explanation": "(g o f)(x) = g(f(x)) = g(3x - 2) = 2*(3x - 2) + 4 = 6x - 4 + 4 = 6x."}, {"id": 8, "unit": 2, "question": "Aşağıdakilerden hangisi bir fonksiyonun grafiği ile tersinin grafiğinin simetrik olduğu doğruyu belirtir?", "options": ["A) x ekseni (y = 0)", "B) y ekseni (x = 0)", "C) y = x doğrusu", "D) y = -x doğrusu", "E) Orijin noktası"], "correct_answer": "C", "explanation": "Bir fonksiyon ile tersinin grafiği y = x (1. açıortay) doğrusuna göre simetriktir."}, {"id": 9, "unit": 2, "question": "Tanım kümesindeki her elemanı değer kümesinde yine kendisine eşleyen f(x) = x fonksiyonuna ne ad verilir?", "options": ["A) Sabit Fonksiyon", "B) Birim (Özdeşlik) Fonksiyon", "C) Sıfır Fonksiyonu", "D) Ters Fonksiyon", "E) Polinom Fonksiyon"], "correct_answer": "B", "explanation": "f(x) = x fonksiyonu Birim (Özdeşlik) fonksiyondur."}, {"id": 10, "unit": 2, "question": "f(x) = 8 fonksiyonu için f(100) değeri kaçtır?", "options": ["A) 8", "B) 100", "C) 800", "D) 0", "E) Tanımsız"], "correct_answer": "A", "explanation": "f(x) = 8 bir sabit fonksiyondur; her x değeri için sonucu daima 8'dir."}, {"id": 11, "unit": 3, "question": "2x - 3y + 6 = 0 doğrusunun eğimi kaçtır?", "options": ["A) 2/3", "B) -2/3", "C) 3/2", "D) -3/2", "E) 2"], "correct_answer": "A", "explanation": "3y = 2x + 6 => y = (2/3)x + 2. x'in katsayısı olan m = 2/3 doğrunun eğimidir."}, {"id": 12, "unit": 3, "question": "Birbirine paralel iki doğrunun eğimleri m1 ve m2 arasındaki ilişki nedir?", "options": ["A) m1 * m2 = -1", "B) m1 = m2", "C) m1 + m2 = 0", "D) m1 * m2 = 1", "E) m1 - m2 = 1"], "correct_answer": "B", "explanation": "Paralel doğruların eğimleri birbirine eşittir (m1 = m2)."}, {"id": 13, "unit": 3, "question": "f(x) = x^2 - 4x + 3 parabolünün x eksenini kestiği noktaların apsisleri toplamı kaçtır?", "options": ["A) 3", "B) 4", "C) -4", "D) 7", "E) 1"], "correct_answer": "B", "explanation": "x eksenini kestiği noktalar köklerdir: x1 + x2 = -b / a = -(-4) / 1 = 4."}, {"id": 14, "unit": 3, "question": "f(x) = 3x^2 - 12x + 20 parabolünün simetri ekseni hangi doğrudur?", "options": ["A) x = 2", "B) x = -2", "C) x = 4", "D) y = 2", "E) x = 6"], "correct_answer": "A", "explanation": "Simetri ekseni x = r doğrusudur: r = -b / (2a) = -(-12) / (2*3) = 12 / 6 = 2. Yani x = 2 doğrusudur."}, {"id": 15, "unit": 3, "question": "f(x) = x^2 + 6x + m parabolünün x eksenine teğet olması için m kaç olmalıdır?", "options": ["A) 3", "B) 6", "C) 9", "D) 12", "E) 36"], "correct_answer": "C", "explanation": "x eksenine teğet olması için diskriminant Δ = 0 olmalıdır. Δ = b^2 - 4ac = 6^2 - 4*1*m = 0 => 36 - 4m = 0 => 4m = 36 => m = 9."}, {"id": 16, "unit": 4, "question": "ln(e^5) işleminin sonucu kaçtır?", "options": ["A) 1", "B) e", "C) 5", "D) 5e", "E) e^5"], "correct_answer": "C", "explanation": "ln(e^k) = k olduğundan ln(e^5) = 5'tir."}, {"id": 17, "unit": 4, "question": "log_5(x) = 3 olduğuna göre x kaçtır?", "options": ["A) 15", "B) 125", "C) 243", "D) 81", "E) 5"], "correct_answer": "B", "explanation": "x = 5^3 = 125."}, {"id": 18, "unit": 4, "question": "log(50) + log(2) işleminin sonucu kaçtır?", "options": ["A) 1", "B) 2", "C) 10", "D) 100", "E) 52"], "correct_answer": "B", "explanation": "log(50) + log(2) = log(50 * 2) = log(100) = log_10(10^2) = 2."}, {"id": 19, "unit": 4, "question": "f(x) = 2^x üstel fonksiyonu için f(4) değeri kaçtır?", "options": ["A) 8", "B) 16", "C) 32", "D) 64", "E) 12"], "correct_answer": "B", "explanation": "f(4) = 2^4 = 16."}, {"id": 20, "unit": 4, "question": "log_a(a) ifadesinin değeri her a > 0 (a ≠ 1) için kaçtır?", "options": ["A) 0", "B) 1", "C) a", "D) e", "E) Tanımsız"], "correct_answer": "B", "explanation": "Taban ile logaritması alınan sayı eşit olduğunda sonuç daima 1'dir."}]}, {"title": "Final Deneme Sınavı 1", "filename": "Final_Deneme_1.md", "questions": [{"id": 1, "unit": 1, "question": "(Vize Tekrarı) 3 elemanlı bir kümenin alt küme sayısı kaçtır?", "options": ["A) 6", "B) 7", "C) 8", "D) 9", "E) 16"], "correct_answer": "C", "explanation": "2^3 = 8."}, {"id": 2, "unit": 2, "question": "(Vize Tekrarı) f(x) = 2x - 8 ise f^-1(0) değeri kaçtır?", "options": ["A) -8", "B) 4", "C) -4", "D) 0", "E) 8"], "correct_answer": "B", "explanation": "2x - 8 = 0 => 2x = 8 => x = 4."}, {"id": 3, "unit": 3, "question": "(Vize Tekrarı) f(x) = x^2 - 4x + 1 parabolünün tepe noktasının apsisi (r) kaçtır?", "options": ["A) -2", "B) 2", "C) 4", "D) -4", "E) 1"], "correct_answer": "B", "explanation": "r = -(-4) / (2*1) = 2."}, {"id": 4, "unit": 4, "question": "(Vize Tekrarı) log_2(16) değeri kaçtır?", "options": ["A) 2", "B) 4", "C) 8", "D) 16", "E) 32"], "correct_answer": "B", "explanation": "2^4 = 16 olduğuna göre sonuç 4'tür."}, {"id": 5, "unit": 5, "question": "lim_{x->2} (x^2 - 4) / (x - 2) limitinin değeri kaçtır?", "options": ["A) 0", "B) 2", "C) 4", "D) 8", "E) Belirsizdir"], "correct_answer": "C", "explanation": "x=2 yazıldığında 0/0 belirsizliği çıkar. L'Hopital ile: payın türevi 2x, paydanın türevi 1. lim_{x->2} 2x / 1 = 2*2 = 4."}, {"id": 6, "unit": 5, "question": "f(x) = 3x^4 - 5x^2 + 8x - 1 fonksiyonunun türevi f'(x) nedir?", "options": ["A) 12x^3 - 10x + 8", "B) 12x^3 - 5x + 8", "C) 7x^3 - 10x", "D) 12x^4 - 10x^2 + 8", "E) 3x^3 - 5x + 8"], "correct_answer": "A", "explanation": "f'(x) = 3*(4x^3) - 5*(2x) + 8 = 12x^3 - 10x + 8."}, {"id": 7, "unit": 5, "question": "f(x) = x^3 - 6x^2 + 9x + 2 fonksiyonunun x = 1 noktasındaki teğetinin eğimi kaçtır?", "options": ["A) 0", "B) 3", "C) -3", "D) 6", "E) 9"], "correct_answer": "A", "explanation": "Teğet eğimi türevdir: f'(x) = 3x^2 - 12x + 9. x = 1 için: f'(1) = 3*(1) - 12*(1) + 9 = 3 - 12 + 9 = 0."}, {"id": 8, "unit": 5, "question": "f(x) = e^(2x) fonksiyonunun x'e göre türevi nedir?", "options": ["A) e^(2x)", "B) 2 * e^(2x)", "C) 2x * e^(2x)", "D) e^x", "E) 2 * e^x"], "correct_answer": "B", "explanation": "Zincir kuralı gereğince (e^(kx))' = k * e^(kx) => 2 * e^(2x)."}, {"id": 9, "unit": 6, "question": "A = [4 2; 3 1] matrisinin determinantı kaçtır?", "options": ["A) -2", "B) 2", "C) 10", "D) -10", "E) 0"], "correct_answer": "A", "explanation": "det(A) = 4*1 - 2*3 = 4 - 6 = -2."}, {"id": 10, "unit": 6, "question": "Aşağıdaki durumlardan hangisinde bir kare matrisin tersi KESİNLİKLE YOKTUR?", "options": ["A) det(A) > 0 ise", "B) det(A) < 0 ise", "C) det(A) = 0 ise", "D) det(A) = 1 ise", "E) Matris birim matris ise"], "correct_answer": "C", "explanation": "Determinantı sıfır olan matrislerin tersi yoktur (tekil matris)."}, {"id": 11, "unit": 6, "question": "A bir 2x3 matris, B ise 3x4 matris olduğuna göre A * B çarpım matrisinin boyutu nedir?", "options": ["A) 2x3", "B) 3x3", "C) 2x4", "D) 4x2", "E) Çarpım yapılamaz"], "correct_answer": "C", "explanation": "2x3 ile 3x4 çarpıldığında ortak boyut 3 elenir ve sonuç 2x4 boyutunda olur."}, {"id": 12, "unit": 7, "question": "f(x, y) = 4x^3 * y^2 - 7x + 2y fonksiyonunun x'e göre kısmi türevi (fx) nedir?", "options": ["A) 12x^2 * y^2 - 7", "B) 8x^3 * y + 2", "C) 12x^2 - 7", "D) 4x^2 * y^2", "E) 12x^2 * y - 7"], "correct_answer": "A", "explanation": "y sabit tutulduğunda: d(4x^3)/dx * y^2 - 7 = 12x^2 * y^2 - 7."}, {"id": 13, "unit": 7, "question": "İkinci mertebe kısmi türevlerde karma türevlerin eşit olduğunu (fxy = fyx) ifade eden teorem hangisidir?", "options": ["A) Fermat Teoremi", "B) Schwarz (Clairaut) Teoremi", "C) Rolle Teoremi", "D) Cramer Teoremi", "E) Euler Teoremi"], "correct_answer": "B", "explanation": "fxy = fyx eşitliği Schwarz Teoremi olarak bilinir."}, {"id": 14, "unit": 7, "question": "İki değişkenli bir fonksiyonun kritik noktasında Hessian determinantı D < 0 olarak bulunmuştur. Bu nokta ne tür bir noktadır?", "options": ["A) Yerel Maksimum", "B) Yerel Minimum", "C) Eyer (Semer) Noktası", "D) Dönüm Noktası", "E) Kök Noktası"], "correct_answer": "C", "explanation": "D < 0 olması noktanın Eyer (Semer) Noktası olduğunu gösterir."}, {"id": 15, "unit": 8, "question": "Bir malın talep denklemi Qd = 100 - 4P ve arz denklemi Qs = 20 + 4P olduğuna göre piyasa denge fiyatı (P*) kaç TL'dir?", "options": ["A) 5", "B) 10", "C) 15", "D) 20", "E) 60"], "correct_answer": "B", "explanation": "Qd = Qs => 100 - 4P = 20 + 4P => 80 = 8P => P = 10 TL."}, {"id": 16, "unit": 8, "question": "Toplam maliyet fonksiyonu TC = Q^3 - 6Q^2 + 25Q + 100 olan bir firmanın Marjinal Maliyet (MC) fonksiyonu nedir?", "options": ["A) 3Q^2 - 12Q + 25", "B) Q^2 - 6Q + 25", "C) 3Q^2 - 6Q + 100", "D) 3Q^2 - 12Q", "E) 6Q - 12"], "correct_answer": "A", "explanation": "MC, TC'nin Q'ya göre 1. türevidir: d(TC)/dQ = 3Q^2 - 12Q + 25."}, {"id": 17, "unit": 8, "question": "Bir firmanın toplam hasılat fonksiyonu TR = 80Q - 2Q^2 olduğuna göre Marjinal Hasılatı (MR) sıfır yapan üretim miktarı (Q) kaçtır?", "options": ["A) 10", "B) 20", "C) 30", "D) 40", "E) 80"], "correct_answer": "B", "explanation": "MR = d(TR)/dQ = 80 - 4Q. MR = 0 => 80 - 4Q = 0 => 4Q = 80 => Q = 20."}, {"id": 18, "unit": 8, "question": "Bir işletmenin kârını maksimize etmesi için gerekli birinci derece koşul aşağıdakilerden hangisidir?", "options": ["A) TR = TC", "B) MR = MC", "C) P = AC", "D) MC = 0", "E) MR = 0"], "correct_answer": "B", "explanation": "Maksimum kâr için Marjinal Hasılat Marjinal Maliyete eşit olmalıdır (MR = MC)."}, {"id": 19, "unit": 8, "question": "Toplam Hasılat TR = 120Q ve Toplam Maliyet TC = Q^2 + 20Q + 200 olduğuna göre kârı maksimum yapan üretim miktarı (Q) kaçtır?", "options": ["A) 25", "B) 50", "C) 75", "D) 100", "E) 120"], "correct_answer": "B", "explanation": "MR = d(TR)/dQ = 120. MC = d(TC)/dQ = 2Q + 20. MR = MC => 120 = 2Q + 20 => 2Q = 100 => Q = 50."}, {"id": 20, "unit": 8, "question": "f(x) = ln(x) fonksiyonunun türevi f'(x) aşağıdakilerden hangisidir?", "options": ["A) 1/x", "B) e^x", "C) x", "D) 1 / (x^2)", "E) ln(x) / x"], "correct_answer": "A", "explanation": "(ln x)' = 1 / x."}]}, {"title": "Final Deneme Sınavı 2", "filename": "Final_Deneme_2.md", "questions": [{"id": 1, "unit": 1, "question": "(Vize Tekrarı) |x - 4| = 7 denklemini sağlayan x değerlerinin toplamı kaçtır?", "options": ["A) 4", "B) 7", "C) 8", "D) 11", "E) -3"], "correct_answer": "C", "explanation": "x - 4 = 7 => x1 = 11. x - 4 = -7 => x2 = -3. Toplam = 11 + (-3) = 8."}, {"id": 2, "unit": 2, "question": "(Vize Tekrarı) f(x) = 5x - 7 fonksiyonunun bire-bir ve örten olduğu bilindiğine göre ters fonksiyonu nedir?", "options": ["A) (x + 7) / 5", "B) (x - 7) / 5", "C) 5x + 7", "D) -5x + 7", "E) (x - 5) / 7"], "correct_answer": "A", "explanation": "f^-1(x) = (x + 7) / 5."}, {"id": 3, "unit": 3, "question": "(Vize Tekrarı) y = -2x + 7 doğrusunun eğimi kaçtır?", "options": ["A) 7", "B) -2", "C) 2", "D) -7", "E) 1/2"], "correct_answer": "B", "explanation": "y = mx + n formunda x'in katsayısı m = -2 eğimdir."}, {"id": 4, "unit": 4, "question": "(Vize Tekrarı) log_4(64) işleminin sonucu kaçtır?", "options": ["A) 2", "B) 3", "C) 4", "D) 8", "E) 16"], "correct_answer": "B", "explanation": "4^3 = 64 olduğuna göre log_4(64) = 3."}, {"id": 5, "unit": 5, "question": "f(x) = x^5 - 2x^3 + 4x fonksiyonunun ikinci mertebeden türevi f''(x) nedir?", "options": ["A) 20x^3 - 12x", "B) 5x^4 - 6x^2 + 4", "C) 20x^4 - 6x", "D) 60x^2 - 12", "E) 20x^3 - 6x"], "correct_answer": "A", "explanation": "1. türev: f'(x) = 5x^4 - 6x^2 + 4. 2. türev: f''(x) = 20x^3 - 12x."}, {"id": 6, "unit": 5, "question": "lim_{x->3} (2x^2 - 5x + 1) limitinin değeri kaçtır?", "options": ["A) 4", "B) 10", "C) 16", "D) 20", "E) 8"], "correct_answer": "A", "explanation": "Polinom fonksiyonda doğrudan x yerine 3 yazılır: 2*(3^2) - 5*3 + 1 = 2*9 - 15 + 1 = 18 - 15 + 1 = 4."}, {"id": 7, "unit": 5, "question": "f(x) = (2x + 1) * (x - 3) fonksiyonunun türevi f'(x) nedir?", "options": ["A) 4x - 5", "B) 4x + 5", "C) 2x - 5", "D) 4x - 6", "E) 2x - 6"], "correct_answer": "A", "explanation": "Çarpımın türevi: (2)*(x - 3) + (2x + 1)*(1) = 2x - 6 + 2x + 1 = 4x - 5."}, {"id": 8, "unit": 5, "question": "Bir f fonksiyonunun x = a noktasında sürekli olması için aşağıdakilerden hangisi gerekli DEĞİLDİR?", "options": ["A) f(a)'nın tanımlı olması", "B) x -> a iken limitin var olması", "C) Limitin f(a) değerine eşit olması", "D) Fonksiyonun o noktada türevinin sıfır olması", "E) Sağ ve sol limitlerin eşit olması"], "correct_answer": "D", "explanation": "Süreklilik için türevin sıfır olması gerekmez; hatta fonksiyon sürekli olduğu halde o noktada türevsiz bile olabilir (kırılma noktaları)."}, {"id": 9, "unit": 6, "question": "A = [3 1; 2 2] matrisinin determinantı kaçtır?", "options": ["A) 4", "B) 6", "C) 8", "D) 2", "E) 0"], "correct_answer": "A", "explanation": "det(A) = 3*2 - 1*2 = 6 - 2 = 4."}, {"id": 10, "unit": 6, "question": "Asal köşegenindeki elemanları 1, diğer tüm elemanları 0 olan matrise ne ad verilir?", "options": ["A) Sıfır Matrisi", "B) Birim Matris", "C) Skaler Matris", "D) Ters Matris", "E) Transpoz Matris"], "correct_answer": "B", "explanation": "Köşegeni 1 olan matris Birim Matristir (I)."}, {"id": 11, "unit": 6, "question": "Cramer kuralı ile 2 bilinmeyenli denklem sistemi çözülürken x bilinmeyeni nasıl bulunur?", "options": ["A) det(A) / det(Ax)", "B) det(Ax) / det(A)", "C) det(Ax) * det(A)", "D) det(Ay) / det(A)", "E) det(A) + det(Ax)"], "correct_answer": "B", "explanation": "Cramer kuralında x = det(Ax) / det(A)'dır."}, {"id": 12, "unit": 7, "question": "f(x, y) = 5x^2 + 3xy + 2y^2 fonksiyonunun y'ye göre kısmi türevi (fy) nedir?", "options": ["A) 10x + 3y", "B) 3x + 4y", "C) 3x + 2y", "D) 10x + 4y", "E) 4y"], "correct_answer": "B", "explanation": "x sabit tutulur: d(5x^2)/dy = 0, d(3xy)/dy = 3x, d(2y^2)/dy = 4y => fy = 3x + 4y."}, {"id": 13, "unit": 7, "question": "f(x, y) = x^3 * y^4 fonksiyonunun önce x'e sonra y'ye türevi (fxy) nedir?", "options": ["A) 12x^2 * y^3", "B) 3x^2 * y^4", "C) 4x^3 * y^3", "D) 12x^3 * y^2", "E) 6x * y^2"], "correct_answer": "A", "explanation": "fx = 3x^2 * y^4. fxy = d(3x^2 * y^4)/dy = 3x^2 * (4y^3) = 12x^2 * y^3."}, {"id": 14, "unit": 7, "question": "İki değişkenli bir fonksiyonda Hessian determinantı D > 0 ve fxx > 0 ise kritik nokta ne tür bir ekstremum noktasıdır?", "options": ["A) Yerel Maksimum", "B) Yerel Minimum", "C) Eyer Noktası", "D) Dönüm Noktası", "E) Belirsizdir"], "correct_answer": "B", "explanation": "D > 0 ve fxx > 0 olduğunda fonksiyon yerel minimuma sahiptir."}, {"id": 15, "unit": 8, "question": "Bir firmanın toplam hasılat fonksiyonu TR = 150Q - Q^2 olduğuna göre Marjinal Hasılat (MR) fonksiyonu nedir?", "options": ["A) 150 - 2Q", "B) 150 - Q", "C) 150Q - 2", "D) 75 - Q", "E) -2Q"], "correct_answer": "A", "explanation": "MR = d(TR)/dQ = 150 - 2Q."}, {"id": 16, "unit": 8, "question": "Toplam Maliyet TC = 50 + 20Q ise Sabit Maliyet (TFC) kaç TL'dir?", "options": ["A) 20", "B) 50", "C) 70", "D) 0", "E) 100"], "correct_answer": "B", "explanation": "Q'ya bağlı olmayan sabit terim TFC'dir, yani 50 TL'dir."}, {"id": 17, "unit": 8, "question": "Bir malın talep fonksiyonu Q = 200 - 5P olduğuna göre P = 10 TL için talep miktarı (Q) kaçtır?", "options": ["A) 100", "B) 150", "C) 50", "D) 190", "E) 20"], "correct_answer": "B", "explanation": "Q = 200 - 5*10 = 200 - 50 = 150 birim."}, {"id": 18, "unit": 8, "question": "Marjinal Hasılatı MR = 100 - 4Q ve Marjinal Maliyeti MC = 20 + 4Q olan bir tekelci firmanın kârını maksimize eden üretim miktarı (Q) kaçtır?", "options": ["A) 5", "B) 10", "C) 15", "D) 20", "E) 25"], "correct_answer": "B", "explanation": "MR = MC => 100 - 4Q = 20 + 4Q => 80 = 8Q => Q = 10 birim."}, {"id": 19, "unit": 8, "question": "Toplam Maliyeti TC = 300 + 15Q olan firmanın Marjinal Maliyeti (MC) kaçtır?", "options": ["A) 300", "B) 15", "C) 315", "D) 0", "E) 15Q"], "correct_answer": "B", "explanation": "MC = d(TC)/dQ = 15."}, {"id": 20, "unit": 8, "question": "f(x) = e^x fonksiyonunun x'e göre türevi nedir?", "options": ["A) e^x", "B) x * e^(x-1)", "C) 1 / e^x", "D) ln x", "E) 1"], "correct_answer": "A", "explanation": "Doğal üstel fonksiyonun türevi kendisine eşittir: (e^x)' = e^x."}]}]}, "iktisada_giris": {"course_name": "İKTİSADA GİRİŞ", "course_code": "İKT101U", "faculty": "İşletme / İktisat Fakültesi - Yönetim Bilişim Sistemleri (YBS)", "term": "1. Sınıf Güz Dönemi", "description": "Mikroekonomi ve makroekonomiye giriş, tüketici teorisi, arz ve talep esneklikleri, üretim ve maliyetler, piyasa yapıları, GSYH, enflasyon, işsizlik, basit Keynesyen model, para-banka ve AD-AS analizi.", "units": [{"unit_number": 1, "title": "Temel Kavramlar ve Tüketici Davranışı", "is_vize": true, "key_topics": ["Kıtlık ve Fırsat Maliyeti", "Üretim İmkânları Eğrisi (PPF)", "Pozitif ve Normatif İktisat", "Fayda Teorisi (TU ve MU)", "Farksızlık Eğrileri ve Bütçe Doğrusu"], "hap_bilgiler": ["İktisadın Tanımı ve Temel Sorun: İnsanların sınırsız ihtiyaçları karşısında kıt kaynakların en etkin biçimde tahsis edilmesini inceleyen sosyal bilimdir. Temel sorun 'KITLIK'tır.", "Fırsat Maliyeti (Alternatif Maliyet): Bir kararı uygularken vazgeçilen en iyi ikinci alternatifin değeridir.", "İktisadın 3 Temel Sorusu: 1. Ne üretilecek? 2. Nasıl üretilecek? 3. Kimin için üretilecek?", "Üretim İmkânları Eğrisi (PPF): Mevcut teknoloji ve kaynaklarla üretilebilecek maksimum mal bileşimlerini gösterir. Artan fırsat maliyeti sebebiyle orijine göre İÇBÜKEYDİR. Eğri üzerindeki noktalar etkin, içindeki noktalar eksik istihdam/etkinsiz, dışındaki noktalar ise mevcut kaynaklarla ulaşılamaz.", "Pozitif İktisat ('Ne?', 'Nasıl?'): Değer yargısı içermeyen, objektif ve test edilebilir durumları inceler (Örn: 'KDV artarsa fiyatlar yükselir').", "Normatif İktisat ('Ne olmalı?'): Kişisel değer yargıları ve ahlaki öneriler içerir (Örn: 'Devlet asgari ücreti 40.000 TL yapmalıdır').", "Toplam Fayda (TU) ve Marjinal Fayda (MU): Tüketim arttıkça ek birimden elde edilen fayda azalır (Azalan Marjinal Fayda Yasası / 1. Gossen Yasası). Toplam Fayda (TU) MAKSİMUM olduğunda Marjinal Fayda (MU) SIFIRDIR (MU = 0).", "Tüketici Dengesi (Eşmarjinal İlkesi / 2. Gossen Yasası): Harcanan son liranın marjinal faydaları eşitlendiğinde sağlanır: MUx / Px = MUy / Py.", "Farksızlık (Kayıtsızlık) Eğrileri: Tüketiciye eşit tatmin düzeyi sağlayan sepetlerin geometrik yeridir. Özellikleri: Negatif eğimlidir, birbirlerini asla kesmezler, orijinden uzaklaştıkça daha yüksek fayda sağlarlar, azalan marjinal ikame oranı nedeniyle orijine göre DIŞBÜKEYDİRLER. Eğimi Marjinal İkame Oranıdır: MRS = MUx / MUy.", "Bütçe Doğrusu ve Denge: Gelir I = Px * X + Py * Y. Bütçe doğrusunun eğimi -Px / Py'dir. Tüketici dengesi bütçe doğrusunun farksızlık eğrisine TEĞET olduğu noktada gerçekleşir (MRS = Px / Py)."]}, {"unit_number": 2, "title": "Arz, Talep ve Esneklik", "is_vize": true, "key_topics": ["Talep Kanunu ve Eğrinin Kayması", "Arz Kanunu", "Piyasa Dengesi", "Taban ve Tavan Fiyat", "Talebin Fiyat, Gelir ve Çapraz Esneklikleri"], "hap_bilgiler": ["Talep Kanunu: Ceteris paribus (diğer koşullar sabitken), bir malın fiyatı arttıkça talep edilen miktar azalır (ters yönlü ilişki). Talep eğrisi negatif eğimlidir.", "Talep Miktarının Değişmesi vs Talebin Değişmesi (Eğrinin Kayması): Malın kendi fiyatındaki değişim eğri ÜZERİNDE HAREKET yaratır. Gelir, tüketici zevkleri, ikame/tamamlayıcı mal fiyatları ve beklentilerdeki değişim ise talep eğrisini tamamen SAĞA veya SOLA kaydırır.", "Normal Mal (Gelir artınca talep artar), Düşük Mal (Gelir artınca talep azalır). İkame Mal (Birinin fiyatı artınca diğerinin talebi artar: Çay-Kahve), Tamamlayıcı Mal (Birinin fiyatı artınca diğerinin talebi azalır: Otomobil-Benzin).", "Arz Kanunu: Fiyat arttıkça arz edilen miktar artar (doğru yönlü ilişki). Arz eğrisi pozitif eğimlidir.", "Piyasa Fiyat Kontrolleri:", "  - Taban Fiyat: Üreticiyi korumak amacıyla denge fiyatının ÜZERİNDE belirlenen asgari fiyattır (Örn: Asgari ücret, tarımsal destekleme). Piyasada ARZ FAZLASI (Artık) oluşturur.", "  - Tavan Fiyat: Tüketiciyi korumak amacıyla denge fiyatının ALTINDA belirlenen azami fiyattır (Örn: Kira sınırlaması). Piyasada TALEP FAZLASI (Kıtlık) ve karaborsa oluşturur.", "Talebin Fiyat Esnekliği (|ed| = %ΔQ / %ΔP):", "  - |ed| > 1 ise Talep Esnektir: Fiyat indirimi Toplam Hasılatı (TR) artırır.", "  - |ed| < 1 ise Talep İnelastiktir (Katıdır): Fiyat artışı Toplam Hasılatı (TR) artırır (Tuz, ekmek vb.).", "  - |ed| = 1 ise Birim Esnektir: Fiyat değişimi TR'yi değiştirmez.", "  - ed = 0 ise Tam İnelastiktir (Dikey doğru - insülin ilacı).", "  - ed = ∞ ise Tam Esnektir (Yatay doğru).", "Çapraz Fiyat Esnekliği (exy): exy > 0 ise İKAME mallar, exy < 0 ise TAMAMLAYICI mallar, exy = 0 ise BAĞIMSIZ mallardır.", "Gelir Esnekliği (eI): eI > 0 ise NORMAL mal (eI > 1 ise LÜKS mal, 0 < eI < 1 ise ZORUNLU mal); eI < 0 ise DÜŞÜK maldır."]}, {"unit_number": 3, "title": "Üretim, Maliyetler ve Firma Davranışı", "is_vize": true, "key_topics": ["Kısa ve Uzun Dönem", "Azalan Verimler Yasası", "Toplam, Ortalama ve Marjinal Maliyetler", "Ölçek Ekonomileri"], "hap_bilgiler": ["Dönem Ayrımı: Kısa dönemde en az bir üretim faktörü sabittir (genellikle sermaye K sabittir, emek L değişkendir). Uzun dönemde tüm girdiler değişkendir.", "Ürün Kavramları ve Azalan Verimler Yasası: Sabit girdilere ilave değişken girdi eklendikçe bir noktadan sonra Marjinal Ürün (MP) azalmaya başlar.", "  - Marjinal Ürün MP = 0 olduğunda Toplam Ürün (TP) MAKSİMUMDUR.", "  - Marjinal Ürün Ortalama Ürüne eşit olduğunda (MP = AP), Ortalama Ürün (AP) MAKSİMUMDUR.", "Kısa Dönem Maliyetleri:", "  - Toplam Maliyet: TC = TFC (Sabit Maliyet) + TVC (Değişken Maliyet).", "  - Ortalama Sabit Maliyet: AFC = TFC / Q. Üretim miktarı arttıkça AFC sürekli azalır ve yatay eksene yaklaşır.", "  - Ortalama Toplam Maliyet: ATC = TC / Q = AFC + AVC.", "  - Marjinal Maliyet (MC = ΔTC / ΔQ): Son üretilen birimin maliyetidir.", "ALTIN MALİYET KURALI: Marjinal Maliyet (MC) eğrisi hem AVC hem de ATC eğrilerini en dip (MİNİMUM) noktalarında alttan keser!", "Uzun Dönem Maliyetleri (LRAC):", "  - Ölçeğe Göre Artan Getiri (Pozitif Ölçek Ekonomileri): Üretim ölçeği arttıkça uzun dönem ortalama maliyet (LRAC) düşer.", "  - Ölçeğe Göre Sabit Getiri: LRAC eğrisi yataydır.", "  - Ölçeğe Göre Azalan Getiri (Negatif Ölçek Ekonomileri): Aşırı büyüme ve yönetimsel hantallık nedeniyle LRAC yükselir."]}, {"unit_number": 4, "title": "Piyasalar", "is_vize": true, "key_topics": ["Tam Rekabet Piyasası", "Monopol (Tekel)", "Monopolcü Rekabet", "Oligopol ve Oyun Teorisi"], "hap_bilgiler": ["Tam Rekabet Piyasasının 4 Koşulu: 1. Atomisite (Çok sayıda alıcı ve satıcı), 2. Homojenlik (Malların birbirinin tıpatıp aynısı olması), 3. Tam Bilgi (Şeffaflık), 4. Piyasaya Giriş-Çıkış Serbestisi.", "Tam Rekabette Firma Davranışı: Firma 'Fiyat Kabullenicidir' (Price Taker). Firmanın karşılaştığı talep eğrisi sonsuz esnektir (yatay doğrudur): P = AR = MR.", "Tam Rekabette Kısa Dönem Kâr Maksimizasyonu: P = MC (veya MR = MC).", "Kapanma Koşulu: Eğer fiyat Ortalama Değişken Maliyetin altına düşerse (P < AVC_min), firma derhal üretimi durdurmalı ve kapanmalıdır! Firmanın kısa dönem arz eğrisi, MC'nin AVC üzerinde kalan parçasıdır.", "Tam Rekabette Uzun Dönem: Serbest giriş ve çıkışlar sonucunda aşırı kâr sıfırlanır, sadece normal kâr elde edilir: P = MR = MC = ATC_min.", "Monopol (Tekel): Tek bir satıcı, ikamesi olmayan mal ve yüksek giriş engelleri. Firma 'Fiyat Belirleyicidir'. MR eğrisi talep eğrisinin altındadır (P > MR). Kâr maksimizasyonu MR = MC koşuluyla sağlanır, fiyat talep eğrisinden okunur. Monopol piyasası toplumda refah kaybına (Ölü Dara Kaybı) yol açar.", "Monopolcü Rekabet: Çok sayıda firma, serbest giriş-çıkış, ancak FARKLILAŞTIRILMIŞ ürünler (marka, reklam, ambalaj). Uzun dönemde aşırı kâr sıfırdır (P = ATC) ancak atıl kapasite oluşur.", "Oligopol: Birbirini etkileyen az sayıda büyük satıcı (karşılıklı bağımlılık). Paul Sweezy'nin 'Dirsekli Talep Modeli' fiyat katılığını açıklar. Oyun Teorisi ve Mahkûmlar İkilemi (Nash Dengesi) bu piyasada incelenir."]}, {"unit_number": 5, "title": "Makroekonominin Kapsamı ve Temel Makroekonomik Değişkenler", "is_vize": false, "key_topics": ["Klasik İktisat vs Keynesyen İktisat", "GSYH ve Ölçüm Yöntemleri", "Nominal ve Reel GSYH", "Enflasyon Türleri", "İşsizlik Türleri"], "hap_bilgiler": ["Makroekonominin Doğuşu: 1929 Büyük Dünya Buhranı sonrasında John Maynard Keynes'in 1936 tarihli 'İstihdam, Faiz ve Paranın Genel Teorisi' kitabıyla doğmuştur.", "Klasik İktisat (Adam Smith, Say Yasası): 'Her arz kendi talebini yaratır'. Fiyatlar ve ücretler tamamen esnektir, ekonomi kendiliğinden daima tam istihdama gelir, devlet müdahalesine gerek yoktur.", "Keynesyen İktisat: Fiyat ve ücretler aşağı doğru yapışkandır (esnek değildir). Krizin nedeni efektif talep yetersizliğidir; ekonomi eksik istihdamda dengede kalabilir ve devletin harcama yaparak müdahale etmesi şarttır.", "Gayri Safi Yurtiçi Hasıla (GSYH): Bir ülkede belirli bir dönemde üretilen nihai mal ve hizmetlerin piyasa değeridir.", "  - Harcama Yoluyla GSYH: GSYH = C + I + G + (X - M) (Tüketim + Yatırım + Kamu Harcamaları + Net İhracat).", "  - Nominal GSYH: Cari (o yılın) fiyatlarıyla hesaplanan değer.", "  - Reel GSYH: Enflasyon arındırılarak sabit baz yıl fiyatlarıyla hesaplanan değer.", "  - GSYH Deflatörü = (Nominal GSYH / Reel GSYH) * 100.", "İşsizlik Oranı Formülü: İşsizlik Oranı = (İşsiz Sayısı / İşgücü) * 100. (İşgücü = Çalışanlar + İşsizler).", "İşsizlik Türleri:", "  - Friksiyonel (Geçici/Arızi): İş değiştirenlerin veya yeni mezunların iş arama sürecindeki geçici işsizlik.", "  - Yapısal: Teknolojik değişim veya sektör kapanması nedeniyle işgücü niteliği ile talep edilen nitelik arasındaki uyumsuzluk.", "  - Konjonktürel (Dönemsel/Keynesyen): Ekonomik durgunluk ve kriz dönemlerinde toplam talep daralması sonucu ortaya çıkan işsizlik.", "  - Doğal İşsizlik: Friksiyonel İşsizlik + Yapısal İşsizlik (Konjonktürel işsizlik sıfır olduğunda ulaşılan tam istihdam oranı)."]}, {"unit_number": 6, "title": "Millî Gelir Düzeyinin Belirlenmesi", "is_vize": false, "key_topics": ["Basit Keynesyen Model", "Tüketim ve Tasarruf Fonksiyonları", "MPC ve MPS", "Basit Çarpan (Çoğaltan) Mekanizması", "Deflasyonist ve Enflasyonist Açık"], "hap_bilgiler": ["Basit Dışa Kapalı Devletsiz Keynesyen Model: Toplam Harcama AE = C + I. Denge Şartı: Y = AE.", "Tüketim Fonksiyonu: C = C0 + c * Y. (C0 = Otonom tüketim - gelir sıfırken yapılan harcama, c = MPC).", "Marjinal Tüketim Eğilimi (MPC = ΔC / ΔY): Gelirdeki 1 birimlik artışın ne kadarının tüketime gideceğini gösterir (0 < MPC < 1).", "Marjinal Tasarruf Eğilimi (MPS = ΔS / ΔY): Gelirdeki 1 birimlik artışın ne kadarının tasarruf edileceğini gösterir.", "ALTIN KURAL: MPC + MPS = 1'dir. Dolayısıyla MPS = 1 - MPC.", "Basit Çarpan (Çoğaltan / Multiplier) Formülü: Yatırımlardaki 1 liralık otonom artışın millî geliri katbekat artırmasını ifade eder: k = 1 / (1 - MPC) = 1 / MPS.", "  - Örnek: MPC = 0.80 ise MPS = 0.20 => k = 1 / 0.20 = 5. Yatırımlar 10 milyar artarsa millî gelir 10 * 5 = 50 milyar TL artar.", "Devletin Olduğu Modelde Çarpanlar:", "  - Kamu Harcamaları Çarpanı: kg = 1 / (1 - MPC).", "  - Vergi Çarpanı: kt = -MPC / (1 - MPC).", "  - Denk Bütçe Çarpanı (Haavelmo Teoremi): Kamu harcamaları ve vergiler eşit miktarda artırılırsa çarpan 1'e eşittir (k = 1).", "Açık Türleri:", "  - Deflasyonist Açık (Durgunluk Açığı): Denge gelirinin potansiyel (tam istihdam) gelirinin altında kalması durumudur (İşsizlik vardır).", "  - Enflasyonist Açık: Toplam harcamaların tam istihdam üretim kapasitesini aşması durumudur (Fiyat artışı ve enflasyon yaratır)."]}, {"unit_number": 7, "title": "Para ve Bankacılık", "is_vize": false, "key_topics": ["Paranın Tanımı ve 4 İşlevi", "Para Arzı Tanımları (M1, M2, M3)", "Kaydi Para Yaratma Mekanizması", "Merkez Bankası Para Politikası Araçları", "Likidite Tuzağı"], "hap_bilgiler": ["Paranın 4 Temel İşlevi: 1. Değişim (Mübadele) Aracı, 2. Hesap Birimi (Değer Ölçüsü), 3. Değer Saklama (Tasarruf) Aracı, 4. Ertelenmiş Ödemeler Aracı.", "Para Arzı Büyüklükleri (Likiditeden Düşüğe Doğru):", "  - M1 (Dar Para Arzı - En Likit): Dolaşımdaki Nakit Para (Kasa + Cüzdan) + Vadesiz Ticari ve Tasarruf Mevduatları.", "  - M2: M1 + Vadeli Mevduatlar.", "  - M3 (Geniş Para Arzı): M2 + Repo + Para Piyasası Fonları + İhraç Edilen Menkul Kıymetler.", "Kaydi (Banka) Para Yaratılması ve Kredi Çarpanı: Ticari bankalar topladıkları mevduatın bir kısmını Merkez Bankası'na zorunlu karşılık (r) olarak yatırır, kalanını kredi vererek kaydi para üretir.", "  - Basit Mevduat/Kredi Çarpanı = 1 / r. (Örn: Zorunlu karşılık oranı r = %10 ise çarpan = 1 / 0.10 = 10'dur. Bankaya yatırılan 1000 TL toplamda 10.000 TL kaydi para yaratır).", "Merkez Bankasının 3 Temel Para Politikası Aracı:", "  1. Açık Piyasa İşlemleri (APİ): Merkez Bankasının tahvil/bono alıp satmasıdır. Piyasaya para sürmek için bono SATIN ALIR (genişletici); piyasadan likidite çekmek için bono SATAR (daraltıcı).", "  2. Reeskont Oranı: Ticari bankaların Merkez Bankasından aldıkları avans ve kredilerin faiz oranıdır.", "  3. Zorunlu Karşılık Oranı (Munzam Karşılık): Bankaların mevduat karşılığı Merkez Bankasında bloke tuttuğu zorunlu paydır.", "Keynesyen Para Talebi Güdüleri: 1. İşlem Güdüsü (Gelirle doğru orantılı), 2. İhtiyat Güdüsü (Gelirle doğru orantılı), 3. Spekülasyon Güdüsü (FAİZ ORANIYLA TERS ORANTILI).", "Likidite Tuzağı: Faiz oranlarının inebileceği en dip seviyeye indiği, para talebinin sonsuz esnek olduğu ve para arzı artırılsa dahi faizlerin daha fazla düşürülemediği durumdur (Para politikası etkisizleşir)."]}, {"unit_number": 8, "title": "Toplam Talep-Toplam Arz Analizi ve Politika Uygulamaları", "is_vize": false, "key_topics": ["Toplam Talep Eğrisi (AD)", "Toplam Arz Eğrisi (SRAS ve LRAS)", "Makroekonomik Şoklar ve Stagflasyon", "Maliye ve Para Politikası Karması"], "hap_bilgiler": ["Toplam Talep (AD - Aggregate Demand): Ekonomideki tüm sektörlerin belirli bir fiyat düzeyinde talep ettiği nihai mal ve hizmet miktarıdır. AD eğrisi NEGATİF eğimlidir.", "AD Eğrisinin Negatif Eğimli Olmasının 3 Nedeni:", "  1. Servet (Pigou) Etkisi: Fiyatlar düştükçe paranın satın alma gücü artar, tüketim harcamaları artar.", "  2. Faiz Oranı (Keynes) Etkisi: Fiyatlar düştükçe para talebi azalır, faizler düşer, yatırımlar artar.", "  3. Uluslararası Ticaret (Mundell-Fleming) Etkisi: Yerli fiyatlar düşünce mallar ucuzlar, ihracat artar, ithalat azalır (Net ihracat artar).", "Toplam Arz (AS - Aggregate Supply):", "  - Kısa Dönem Toplam Arz (SRAS): Ücret ve hammadde fiyatlarının yapışkanlığı sebebiyle POZİTİF eğimlidir.", "  - Uzun Dönem Toplam Arz (LRAS): Fiyatlar ve ücretler tamamen esnektir. Ekonomi daima Potansiyel (Tam İstihdam) GSYH düzeyindedir; bu yüzden LRAS DİKEY bir doğrudur!", "Stagflasyon: Ekonomide aynı anda DURGUNLUK (İşsizlik artışı) ve YÜKSEK ENFLASYONUN birlikte yaşanmasıdır. Negatif bir arz şoku (Örn: Petrol fiyatlarının aniden sıçraması) SRAS eğrisini SOLA kaydırdığında tetiklenir.", "Politika Uygulamaları:", "  - Genişletici Politikalar (Durgunlukta uygulanır): Kamu harcamalarını artırmak, vergileri düşürmek, para arzını artırmak, faizleri indirmek -> AD eğrisi SAĞA kayar.", "  - Daraltıcı Politikalar (Enflasyonla mücadelede uygulanır): Kamu harcamalarını kısmak, vergileri artırmak, para arzını kısmak, faizleri artırmak -> AD eğrisi SOLA kayar."]}], "sinav_tuzaklari": [{"id": 1, "title": "Talep Eğrisi Üzerinde Hareket ile Eğrinin Kayması Ayrımı", "mistake": "Malın kendi fiyatı düştüğünde talep eğrisinin sağa kaydığını söylemek.", "truth": "Malın kendi fiyatındaki değişimler ASLA eğriyi kaydırmaz; yalnızca var olan eğri ÜZERİNDE aşağı veya yukarı HAREKET ettirir (Talep edilen miktarın değişmesidir). Eğriyi tamamen kaydıranlar ise gelir, zevkler veya diğer malların fiyatlarıdır.", "tip": "Kendi fiyatı = Eğri üzerinde hareket; Dış faktörler = Eğrinin tamamen kayması."}, {"id": 2, "title": "Taban Fiyat ile Tavan Fiyatın Yeri ve Sonuçları", "mistake": "Tavan fiyatın denge fiyatının üstünde, taban fiyatın altında belirlendiğini sanmak.", "truth": "Taban fiyat denge fiyatının ÜZERİNDE belirlenir (üreticiyi/işçiyi korumak için asgari taban) ve ARZ FAZLASI yaratır. Tavan fiyat ise denge fiyatının ALTINDA belirlenir (tüketiciyi korumak için azami sınır) ve TALEP FAZLASI (Kıtlık) yaratır.", "tip": "Taban = Denge üstü (Fazlalık); Tavan = Denge altı (Kıtlık/Karaborsa)."}, {"id": 3, "title": "Pozitif İktisat ile Normatif İktisat Karışıklığı", "mistake": "'Enflasyon %20'ye düşürülmelidir' cümlesini pozitif iktisat sanmak.", "truth": "İçinde 'olmalı', 'yapılmalı', 'uygundur' gibi temenni ve değer yargısı bulunan her ifade NORMATİF İKTİSAT'tır. 'Fiyatlar artarsa talep düşer' gibi nesnel sebep-sonuç ilişkileri ise POZİTİF İKTİSAT'tır.", "tip": "'...malı / ...meli' görürsen hemen Normatif de geç!"}, {"id": 4, "title": "Talebin Fiyat Esnekliği ile Toplam Hasılat (TR) İlişkisi", "mistake": "Fiyatı indirilen her ürünün hasılatı artıracağını zannetmek.", "truth": "Fiyat indirimi Toplam Hasılatı (TR) sadece talep ESNEKSE (|ed| > 1) artırır. Eğer talep inelastikse (|ed| < 1, tuz gibi), fiyat indirimi hasılatı DÜŞÜRÜR; aksine fiyat artışı hasılatı artırır.", "tip": "Esnekse (|ed|>1) fiyat indir hasılat coşsun; İnelastikse (|ed|<1) zam yap hasılat artsın."}, {"id": 5, "title": "Marjinal Maliyet (MC) ile Ortalama Maliyet (ATC/AVC) Kesişim Noktası", "mistake": "MC eğrisinin ATC'yi maksimum noktasında kestiğini düşünmek.", "truth": "Marjinal Maliyet (MC) eğrisi, hem Ortalama Değişken Maliyet (AVC) hem de Ortalama Toplam Maliyet (ATC) eğrilerini daima en dipteki MİNİMUM noktalarında keser!", "tip": "MC, AVC ve ATC'yi dipten (en düşük noktasından) vurur!"}, {"id": 6, "title": "Tam Rekabet ile Monopolde Fiyat ve Marjinal Hasılat (P ve MR)", "mistake": "Her iki piyasada da P = MR olduğunu düşünmek.", "truth": "Tam Rekabette fiyat sabittir ve P = MR'dir. Ancak Monopolde (Tekel) firma fiyat belirleyicidir ve talep eğrisi aşağı eğimlidir; dolayısıyla MONOPOLDE DAİMA FİYAT MARJİNAL HASILATTAN BÜYÜKTÜR (P > MR).", "tip": "Tam Rekabet: P = MR; Monopol: P > MR."}, {"id": 7, "title": "MPC ile MPS Toplamı Kuralı", "mistake": "MPC = 0.70 olduğunda çarpanın 1/0.70 olduğunu sanmak.", "truth": "MPC (Tüketim eğilimi) + MPS (Tasarruf eğilimi) = 1'dir. Basit çarpan k = 1 / (1 - MPC) = 1 / MPS'dir. MPC = 0.70 ise MPS = 0.30'dur ve k = 1 / 0.30'dur.", "tip": "Paydada daima MPS (1 - MPC) yer alır!"}, {"id": 8, "title": "M1 Para Arzına Vadeli Mevduatların Dahil Edilmesi Yanılgısı", "mistake": "M1'in vadeli mevduatları da kapsadığını düşünmek.", "truth": "M1 dar para arzıdır; sadece en likit olan dolaşımdaki nakit parayı ve VADESİZ mevduatları içerir. VADELİ mevduatlar M2'nin kapsamındadır.", "tip": "Vadesiz = M1; Vadeli eklenirse = M2."}, {"id": 9, "title": "Uzun Dönem Toplam Arz Eğrisinin (LRAS) Şekli", "mistake": "LRAS eğrisinin de kısa dönem gibi pozitif eğimli olduğunu düşünmek.", "truth": "Uzun dönemde tüm fiyatlar ve ücretler esnektir, ekonomi tam istihdama ulaşmıştır. Bu yüzden LRAS potansiyel GSYH düzeyinde DİK (DİKEY) BİR DOĞRUDUR.", "tip": "Kısa dönem AS (SRAS) = Yatık pozitif; Uzun dönem AS (LRAS) = Dimdik dikey."}, {"id": 10, "title": "Stagflasyonun Sebebi ve Tanımı", "mistake": "Stagflasyonun talep fazlalığından kaynaklandığını sanmak.", "truth": "Stagflasyon yüksek enflasyon ile işsizliğin (durgunluğun) aynı anda yaşanmasıdır ve TALEP DEĞİL, NEGATİF ARZ ŞOKU (maliyet artışı / petrol krizi) sonucu SRAS'ın sola kaymasıyla meydana gelir.", "tip": "Stagflasyon = Durgunluk + Enflasyon; sebebi negatif arz şokudur."}], "formuller_ve_kavramlar": [{"term": "Tüketici Dengesi Şartı", "description": "MUx / Px = MUy / Py (Harcanan son liranın marjinal faydalarının eşitliği)."}, {"term": "Talebin Fiyat Esnekliği Formülü", "description": "ed = (%ΔQ) / (%ΔP) = [(Q2 - Q1) / Q1] / [(P2 - P1) / P1]."}, {"term": "Çapraz Fiyat Esnekliği", "description": "exy = (%ΔQx) / (%ΔPy). Pozitif ise ikame, negatif ise tamamlayıcı mal."}, {"term": "Talebin Gelir Esnekliği", "description": "eI = (%ΔQ) / (%ΔI). Pozitif ise normal mal, negatif ise düşük mal."}, {"term": "Toplam Maliyet Eşitliği", "description": "TC = TFC + TVC ve ATC = AFC + AVC."}, {"term": "Marjinal Maliyet (MC)", "description": "MC = ΔTC / ΔQ (Toplam maliyetin üretim miktarına göre türevi)."}, {"term": "Harcama Yoluyla GSYH", "description": "GSYH = C + I + G + (X - M) (Tüketim + Yatırım + Kamu + Net İhracat)."}, {"term": "GSYH Deflatörü", "description": "Deflatör = (Nominal GSYH / Reel GSYH) * 100."}, {"term": "İşsizlik Oranı Formülü", "description": "İşsizlik Oranı = (İşsiz Sayısı / İşgücü) * 100."}, {"term": "Doğal İşsizlik Oranı", "description": "Doğal İşsizlik = Friksiyonel İşsizlik + Yapısal İşsizlik."}, {"term": "Keynesyen MPC ve MPS Eşitliği", "description": "MPC + MPS = 1. (MPC: Marjinal Tüketim Eğilimi, MPS: Marjinal Tasarruf Eğilimi)."}, {"term": "Basit Çarpan (Çoğaltan) Formülü", "description": "k = 1 / (1 - MPC) = 1 / MPS.", "example": "MPC = 0.75 ise k = 1 / (1 - 0.75) = 1 / 0.25 = 4."}, {"term": "Vergi Çarpanı Formülü", "description": "kt = -MPC / (1 - MPC).", "example": "MPC = 0.80 ise kt = -0.80 / 0.20 = -4."}, {"term": "Denk Bütçe Çarpanı", "description": "Kamu harcamaları ve vergiler eşit miktarda artırıldığında çarpan k = 1'dir."}, {"term": "M1 Para Arzı", "description": "M1 = Dolaşımdaki Nakit + Vadesiz Mevduatlar."}, {"term": "M2 Para Arzı", "description": "M2 = M1 + Vadeli Mevduatlar."}, {"term": "Basit Kredi Çarpanı", "description": "Kredi Çarpanı = 1 / r (r: Zorunlu Karşılık Oranı).", "example": "r = %20 ise çarpan = 1 / 0.20 = 5."}], "flashcards": [{"id": 1, "unit": 1, "question": "Bir kararı alırken vazgeçilen en iyi ikinci alternatifin değerine ne ad verilir?", "answer": "Fırsat Maliyeti (Alternatif Maliyet)."}, {"id": 2, "unit": 1, "question": "Üretim İmkânları Eğrisi (PPF) artan fırsat maliyeti sebebiyle orijine göre nasıldır?", "answer": "İçbükeydir (Konkav)."}, {"id": 3, "unit": 1, "question": "'Hükümet dar gelirli vatandaşlara kira yardımı yapmalıdır' ifadesi hangi iktisat dalına örnektir?", "answer": "Normatif İktisat (Değer yargısı ve temenni içerir)."}, {"id": 4, "unit": 1, "question": "Tüketim arttıkça ek birimden elde edilen tatminin azalacağını belirten yasa hangisidir?", "answer": "Azalan Marjinal Fayda Yasası (1. Gossen Yasası)."}, {"id": 5, "unit": 1, "question": "Toplam Fayda (TU) maksimum noktaya ulaştığında Marjinal Fayda (MU) kaç olur?", "answer": "Sıfır (MU = 0) olur."}, {"id": 6, "unit": 1, "question": "Farksızlık eğrisinin eğimine ne ad verilir?", "answer": "Marjinal İkame Oranı (MRS = MUx / MUy)."}, {"id": 7, "unit": 2, "question": "Malın kendi fiyatındaki bir değişiklik talep eğrisini nasıl etkiler?", "answer": "Eğriyi kaydırmaz; eğri üzerinde yukarı veya aşağı harekete yol açar."}, {"id": 8, "unit": 2, "question": "Gelir arttığında talebi azalan mallara ne ad verilir?", "answer": "Düşük Mal (Giffen Malı)."}, {"id": 9, "unit": 2, "question": "Çay fiyatı arttığında kahveye olan talebin artması iki malın ne tür mal olduğunu gösterir?", "answer": "İkame Mal olduğunu gösterir (Çapraz esneklik pozitiftir)."}, {"id": 10, "unit": 2, "question": "Devletin üreticiyi korumak amacıyla denge fiyatının üzerinde belirlediği asgari fiyata ne denir?", "answer": "Taban Fiyat (Asgari fiyat; arz fazlası yaratır)."}, {"id": 11, "unit": 2, "question": "Talebin fiyat esnekliği |ed| > 1 olduğunda ürünün fiyatı düşürülürse Toplam Hasılat (TR) nasıl değişir?", "answer": "Toplam Hasılat (TR) artar."}, {"id": 12, "unit": 3, "question": "Marjinal Ürün (MP) sıfır olduğunda Toplam Ürün (TP) hangi değere ulaşır?", "answer": "Maksimum (en yüksek) düzeyine ulaşır."}, {"id": 13, "unit": 3, "question": "Üretim miktarı arttıkça sürekli azalan ve yatay eksene yaklaşan maliyet eğrisi hangisidir?", "answer": "Ortalama Sabit Maliyet (AFC = TFC / Q)."}, {"id": 14, "unit": 3, "question": "Marjinal Maliyet (MC) eğrisi Ortalama Toplam Maliyet (ATC) eğrisini hangi noktasında keser?", "answer": "ATC'nin en dipteki MİNİMUM noktasında alttan keser."}, {"id": 15, "unit": 4, "question": "Tam rekabet piyasasında faaliyet gösteren bir firmanın karşılaştığı talep eğrisi nasıldır?", "answer": "Yatay bir doğrudur (Sonsuz esnektir: P = AR = MR)."}, {"id": 16, "unit": 4, "question": "Tam rekabet piyasasında firmanın üretimi durdurup piyasadan çekilme (kapanma) şartı nedir?", "answer": "Fiyatın Ortalama Değişken Maliyetin altına düşmesidir (P < AVC_min)."}, {"id": 17, "unit": 4, "question": "Monopol piyasasında firmanın belirlediği fiyat ile Marjinal Hasılat arasındaki ilişki nasıldır?", "answer": "Fiyat Marjinal Hasılattan büyüktür (P > MR)."}, {"id": 18, "unit": 4, "question": "Oligopol piyasasında fiyat katılığını açıklayan ve Paul Sweezy tarafından geliştirilen model hangisidir?", "answer": "Dirsekli Talep Modeli."}, {"id": 19, "unit": 5, "question": "'Her arz kendi talebini yaratır' görüşü kime ve hangi yasaya aittir?", "answer": "Jean-Baptiste Say (Say Yasası / Klasik İktisat)."}, {"id": 20, "unit": 5, "question": "Cari fiyatlarla hesaplanan GSYH'ye ne ad verilir?", "answer": "Nominal GSYH."}, {"id": 21, "unit": 5, "question": "İş değiştirenlerin veya okuldan yeni mezun olanların iş arama sürecindeki geçici işsizlik türü nedir?", "answer": "Friksiyonel (Arızi/Geçici) İşsizlik."}, {"id": 22, "unit": 6, "question": "Marjinal Tüketim Eğilimi (MPC) 0.80 olan bir ekonomide Basit Yatırım Çarpanı kaçtır?", "answer": "5'tir [k = 1 / (1 - 0.80) = 1 / 0.20 = 5]."}, {"id": 23, "unit": 6, "question": "Kamu harcamaları ile vergiler aynı miktarda artırıldığında denk bütçe çarpanı kaça eşittir?", "answer": "1'e eşittir (Haavelmo Teoremi)."}, {"id": 24, "unit": 6, "question": "Denge millî gelirinin tam istihdam millî gelirinin altında kalması durumunda oluşan açık türü nedir?", "answer": "Deflasyonist Açık (Durgunluk Açığı)."}, {"id": 25, "unit": 7, "question": "En likit para arzı büyüklüğü olan M1 neleri kapsar?", "answer": "Dolaşımdaki Nakit Para + Vadesiz Mevduatlar."}, {"id": 26, "unit": 7, "question": "Zorunlu karşılık oranı %10 (0.10) olduğunda basit mevduat (kredi) çarpanı kaçtır?", "answer": "10'dur (1 / 0.10 = 10)."}, {"id": 27, "unit": 7, "question": "Merkez Bankasının piyasadaki likiditeyi kısmak için tahvil/bono satması hangi para politikası aracıdır?", "answer": "Açık Piyasa İşlemleri (APİ)."}, {"id": 28, "unit": 7, "question": "Faiz oranlarının minimuma indiği ve para politikasının faizleri daha fazla düşüremediği kilitlenme durumuna ne ad verilir?", "answer": "Likidite Tuzağı."}, {"id": 29, "unit": 8, "question": "Uzun Dönem Toplam Arz Eğrisi (LRAS) neden dikey bir doğrudur?", "answer": "Ekonominin uzun dönemde tam istihdam (potansiyel GSYH) düzeyinde bulunması sebebiyle."}, {"id": 30, "unit": 8, "question": "Ekonomide yüksek enflasyon ile işsizlik ve durgunluğun aynı anda yaşanmasına ne ad verilir?", "answer": "Stagflasyon."}], "exams": [{"title": "Vize Deneme Sınavı 1", "filename": "Vize_Deneme_1.md", "questions": [{"id": 1, "unit": 1, "question": "İktisat biliminin ortaya çıkışına neden olan temel sorun aşağıdakilerden hangisidir?", "options": ["A) Nüfus artışı", "B) Kıtlık", "C) Enflasyon", "D) Para basımı", "E) İhracat fazlası"], "correct_answer": "B", "explanation": "İktisadın varlık sebebi sınırsız insan ihtiyaçları karşısında kaynakların KIT olmasıdır."}, {"id": 2, "unit": 1, "question": "Bir öğrencinin sinemaya gitmek yerine ders çalışmayı tercih etmesi durumunda vazgeçtiği sinema keyfi iktisadi olarak ne ile açıklanır?", "options": ["A) Marjinal fayda", "B) Fırsat maliyeti (Alternatif maliyet)", "C) Batık maliyet", "D) Muhasebe maliyeti", "E) Normatif maliyet"], "correct_answer": "B", "explanation": "Bir tercihi yaparken vazgeçilen en iyi ikinci alternatif Fırsat Maliyetidir."}, {"id": 3, "unit": 1, "question": "Artan fırsat maliyeti varsayımı altında Üretim İmkânları Eğrisi'nin (PPF) şekli nasıldır?", "options": ["A) Doğrusal bir çizgidir", "B) Orijine göre içbükeydir", "C) Orijine göre dışbükeydir", "D) U şeklinde bir eğridir", "E) Yatay bir doğrudur"], "correct_answer": "B", "explanation": "Fırsat maliyeti arttığı için PPF eğrisi orijine göre içbükeydir (konkavdır)."}, {"id": 4, "unit": 1, "question": "Toplam Fayda (TU) eğrisinin maksimum noktaya ulaştığı tüketim miktarında Marjinal Fayda (MU) kaç birimdir?", "options": ["A) 1", "B) 100", "C) Sıfır (0)", "D) Negatif", "E) Sonsuz"], "correct_answer": "C", "explanation": "TU maksimum olduğunda marjinal fayda sıfırdır (MU = 0)."}, {"id": 5, "unit": 1, "question": "Tüketiciye aynı tatmin düzeyini sağlayan farklı mal bileşimlerinin geometrik yerine ne ad verilir?", "options": ["A) Bütçe doğrusu", "B) Farksızlık (Kayıtsızlık) eğrisi", "C) Eşürün eğrisi", "D) Arz eğrisi", "E) Anlaşma eğrisi"], "correct_answer": "B", "explanation": "Aynı toplam faydayı veren sepetleri farksızlık (kayıtsızlık) eğrileri gösterir."}, {"id": 6, "unit": 2, "question": "Bir malın kendi fiyatındaki bir artış aşağıdaki etkilerden hangisine yol açar?", "options": ["A) Talep eğrisini tamamen sağa kaydırır.", "B) Talep eğrisini tamamen sola kaydırır.", "C) Talep eğrisi üzerinde yukarıya doğru harekete yol açar.", "D) Talebin gelir esnekliğini artırır.", "E) Arz eğrisini sola kaydırır."], "correct_answer": "C", "explanation": "Malın kendi fiyatındaki değişim eğriyi kaydırmaz; eğri üzerinde hareket ettirir."}, {"id": 7, "unit": 2, "question": "Tüketicinin geliri arttığında talebi azalan mallar iktisatta nasıl adlandırılır?", "options": ["A) Normal mal", "B) Lüks mal", "C) Düşük mal", "D) İkame mal", "E) Tamamlayıcı mal"], "correct_answer": "C", "explanation": "Gelir artışına karşın talebi düşen mallara Düşük Mal denir."}, {"id": 8, "unit": 2, "question": "Talebin fiyat esnekliği |ed| = 0 olan (tam inelastik) bir malın talep eğrisinin grafiği nasıldır?", "options": ["A) Yatay bir doğrudur", "B) Dikey bir doğrudur", "C) Pozitif eğimli bir doğrudur", "D) Hiperboldür", "E) U şeklindedir"], "correct_answer": "B", "explanation": "Fiyat ne kadar değişirse değişsin miktar hiç değişmiyorsa talep eğrisi dikey bir doğrudur (|ed| = 0)."}, {"id": 9, "unit": 2, "question": "Talebin fiyat esnekliği mutlak değerce 1'den büyük (|ed| > 1) olan esnek bir malda satıcılar fiyatı düşürürse Toplam Hasılat (TR) nasıl değişir?", "options": ["A) Azalır", "B) Değişmez", "C) Artar", "D) Sıfırlanır", "E) Önce artar sonra azalır"], "correct_answer": "C", "explanation": "Talep esnekse fiyattaki düşüş yüzdesinden daha fazla miktar artışı olur ve toplam hasılat artar."}, {"id": 10, "unit": 2, "question": "Devletin tarım üreticilerini korumak amacıyla piyasa denge fiyatının üzerinde belirlediği asgari fiyata ne denir ve piyasada ne yaratır?", "options": ["A) Tavan fiyat - Kıtlık yaratır", "B) Taban fiyat - Arz fazlası (Artık) yaratır", "C) Denge fiyatı - İstikrar yaratır", "D) Tavan fiyat - Karaborsa yaratır", "E) Müdahalesiz fiyat - İthalat yaratır"], "correct_answer": "B", "explanation": "Üreticiyi korumak için denge üstünde Taban Fiyat uygulanır ve bu durum arz fazlası doğurur."}, {"id": 11, "unit": 3, "question": "Kısa dönem üretim sürecinde değişken girdi miktarı artırıldıkça Marjinal Ürünün (MP) bir noktadan sonra azalmaya başlamasını ifade eden yasa nedir?", "options": ["A) Azalan Verimler Yasası", "B) Talep Yasası", "C) Gossen Yasası", "D) Say Yasası", "E) Pareto Yasası"], "correct_answer": "A", "explanation": "Kısa dönemde değişken girdinin veriminin düşmesi Azalan Verimler Yasasıdır."}, {"id": 12, "unit": 3, "question": "Marjinal Ürün (MP) eğrisi Ortalama Ürün (AP) eğrisini hangi noktasında keser?", "options": ["A) AP'nin minimum olduğu noktada", "B) AP'nin maksimum olduğu noktada", "C) AP'nin sıfır olduğu noktada", "D) TP'nin sıfır olduğu noktada", "E) Kesişmezler"], "correct_answer": "B", "explanation": "MP = AP olduğunda Ortalama Ürün (AP) maksimum düzeyindedir."}, {"id": 13, "unit": 3, "question": "Üretim miktarı sıfır olduğunda dahi katlanılmak zorunda olunan maliyet türü aşağıdakilerden hangisidir?", "options": ["A) Toplam Değişken Maliyet (TVC)", "B) Toplam Sabit Maliyet (TFC)", "C) Marjinal Maliyet (MC)", "D) Ortalama Değişken Maliyet (AVC)", "E) Batık Olmayan Maliyet"], "correct_answer": "B", "explanation": "Üretim olmasa bile kira, sigorta gibi Toplam Sabit Maliyetler (TFC) ödenmek zorundadır."}, {"id": 14, "unit": 3, "question": "Marjinal Maliyet (MC) eğrisi Ortalama Toplam Maliyet (ATC) eğrisini hangi noktasında keser?", "options": ["A) ATC'nin maksimum olduğu noktada", "B) ATC'nin minimum olduğu noktada", "C) ATC'nin ekseni kestiği noktada", "D) TFC'ye eşit olduğu noktada", "E) Asla kesmez"], "correct_answer": "B", "explanation": "MC eğrisi, ATC ve AVC eğrilerini minimum noktalarından alttan keser."}, {"id": 15, "unit": 3, "question": "Uzun dönemde firmanın üretim ölçeğini büyütmesiyle birlikte birim ürün maliyetinin (LRAC) düşmesine ne ad verilir?", "options": ["A) Ölçeğe göre artan getiri (Ölçek ekonomileri)", "B) Ölçeğe göre azalan getiri", "C) Azalan verimler", "D) Sabit getiri", "E) Değişken maliyet avantajı"], "correct_answer": "A", "explanation": "LRAC'ın üretim arttıkça düşmesi pozitif ölçek ekonomilerini (ölçeğe göre artan getiri) gösterir."}, {"id": 16, "unit": 4, "question": "Tam rekabet piyasasında faaliyet gösteren bir firmanın ürününü sattığı fiyat (P), Marjinal Hasılatına (MR) ve Ortalama Hasılatına (AR) nasıl bağlanır?", "options": ["A) P > AR > MR", "B) P = AR = MR", "C) P < MR = AR", "D) MR > P > AR", "E) P ile MR arasında ilişki yoktur"], "correct_answer": "B", "explanation": "Tam rekabette firma fiyat kabullenicidir ve P = AR = MR geçerlidir."}, {"id": 17, "unit": 4, "question": "Tam rekabet piyasasında kısa dönemde firmanın kapanma koşulu aşağıdakilerden hangisidir?", "options": ["A) P > ATC", "B) P < AVC_min", "C) P = MC", "D) TR > TC", "E) MR = MC"], "correct_answer": "B", "explanation": "Fiyat ortalama değişken maliyeti dahi karşılayamıyorsa (P < AVC_min), firma derhal kapanmalıdır."}, {"id": 18, "unit": 4, "question": "Tek bir satıcının bulunduğu, yakın ikamesi olmayan bir malın üretildiği ve piyasaya giriş engellerinin çok yüksek olduğu piyasa türü hangisidir?", "options": ["A) Tam Rekabet", "B) Monopolcü Rekabet", "C) Oligopol", "D) Monopol (Tekel)", "E) Düopol"], "correct_answer": "D", "explanation": "Tek satıcılı piyasa Monopoldür."}, {"id": 19, "unit": 4, "question": "Monopolcü bir firmanın kârını maksimize eden çıktı düzeyinde fiyat (P) ile Marjinal Maliyet (MC) arasındaki ilişki nasıldır?", "options": ["A) P = MC", "B) P > MC", "C) P < MC", "D) P = 0", "E) MC = 0"], "correct_answer": "B", "explanation": "Monopolde kâr maksimizasyonu MR = MC'de sağlanır; ancak P > MR olduğu için P > MC olur."}, {"id": 20, "unit": 4, "question": "Az sayıda büyük firmanın birbirlerinin kararlarını yakından takip ettiği ve karşılıklı bağımlılığın yüksek olduğu piyasa türü nedir?", "options": ["A) Tam Rekabet", "B) Monopol", "C) Oligopol", "D) Monopson", "E) Mükemmel Piyasa"], "correct_answer": "C", "explanation": "Az sayıda firmanın hakim olduğu karşılıklı bağımlı piyasa Oligopoldür."}]}, {"title": "Vize Deneme Sınavı 2", "filename": "Vize_Deneme_2.md", "questions": [{"id": 1, "unit": 1, "question": "Aşağıdaki ifadelerden hangisi 'Pozitif İktisat'a bir örnektir?", "options": ["A) Hükümet asgari ücreti enflasyonun üzerinde artırmalıdır.", "B) Dar gelirlilerden vergi alınmamalıdır.", "C) Bir malın fiyatı arttığında talep edilen miktarı azalır.", "D) Emeklilere daha yüksek ikramiye ödenmesi gerekir.", "E) Sağlık hizmetleri tamamen ücretsiz olmalıdır."], "correct_answer": "C", "explanation": "Pozitif iktisat objektif neden-sonuç ilişkilerini belirtir (C şıkkı)."}, {"id": 2, "unit": 1, "question": "Tüketicinin harcadığı son liranın marjinal faydalarının tüm mallar için eşitlendiğinde dengenin sağlandığını belirten yasa hangisidir?", "options": ["A) 1. Gossen Yasası", "B) 2. Gossen Yasası (Eşmarjinal İlkesi)", "C) Say Yasası", "D) Engel Yasası", "E) King Yasası"], "correct_answer": "B", "explanation": "MUx/Px = MUy/Py eşitliği 2. Gossen Yasası (Eşmarjinal İlkesi) olarak adlandırılır."}, {"id": 3, "unit": 1, "question": "Farksızlık eğrilerinin birbirini kesmemesi ve negatif eğimli olması hangi aksiyomun sonucudur?", "options": ["A) Doyumsuzluk ve geçişlilik aksiyomları", "B) Sayılamazlık", "C) Kıtlık ilkesi", "D) Fırsat maliyeti", "E) Dışsallık"], "correct_answer": "A", "explanation": "Tüketici tercihlerinin tutarlılığı (geçişlilik) ve daha çoğun daha aza tercih edilmesi (doyumsuzluk) farksızlık eğrilerinin kesişmesini engeller."}, {"id": 4, "unit": 1, "question": "Geliri I = 600 TL olan bir tüketicinin X malı fiyatı Px = 20 TL ve Y malı fiyatı Py = 30 TL ise bütçe doğrusunun eğimi kaçtır?", "options": ["A) -2/3", "B) -3/2", "C) -20", "D) -30", "E) -1"], "correct_answer": "A", "explanation": "Bütçe doğrusunun eğimi = -Px / Py = -20 / 30 = -2/3."}, {"id": 5, "unit": 1, "question": "Üretim İmkânları Eğrisi'nin (PPF) dışındaki bir nokta neyi ifade eder?", "options": ["A) Eksik istihdamı", "B) Kaynakların israf edildiğini", "C) Mevcut kaynak ve teknolojiyle ulaşılamaz üretim düzeyini", "D) Tam istihdam dengesini", "E) Sıfır maliyeti"], "correct_answer": "C", "explanation": "PPF'nin dışındaki noktalar mevcut kaynaklarla ulaşılamaz; ancak ekonomik büyüme ile ulaşılabilir."}, {"id": 6, "unit": 2, "question": "İki mal arasındaki çapraz fiyat esnekliği pozitif (exy > 0) çıkmışsa bu mallar ne tür mallardır?", "options": ["A) Tamamlayıcı mallar", "B) İkame mallar", "C) Düşük mallar", "D) Giffen malları", "E) Bağımsız mallar"], "correct_answer": "B", "explanation": "Birinin fiyatı arttığında diğerinin talebi artıyorsa çapraz esneklik pozitiftir ve mallar İKAME mallardır (Örn: Çay ve Kahve)."}, {"id": 7, "unit": 2, "question": "Bir malın gelir esnekliği eI = 1.8 olarak hesaplanmıştır. Bu mal ne tür bir maldır?", "options": ["A) Düşük mal", "B) Zorunlu mal", "C) Lüks normal mal", "D) İkame mal", "E) Tamamlayıcı mal"], "correct_answer": "C", "explanation": "Gelir esnekliği 1'den büyük (eI > 1) olan mallar Lüks Mallardır."}, {"id": 8, "unit": 2, "question": "Devletin kira artışlarını sınırlandırmak amacıyla piyasa denge kirasının altında bir üst sınır belirlemesi hangi fiyat politikasıdır?", "options": ["A) Taban fiyat", "B) Tavan fiyat", "C) Garanti fiyat", "D) Prim sistemi", "E) Destekleme fiyatı"], "correct_answer": "B", "explanation": "Denge fiyatının altında belirlenen azami fiyat Tavan Fiyattır; kıtlık ve karaborsaya yol açabilir."}, {"id": 9, "unit": 2, "question": "Bir malın fiyatı 10 TL iken talep miktarı 100 birimdir. Fiyat 12 TL'ye çıktığında talep miktarı 80 birime düşmüştür. Bu aralıkta talebin fiyat esnekliği kaçtır?", "options": ["A) -0.5", "B) -1.0", "C) -1.5", "D) -2.0", "E) -0.8"], "correct_answer": "B", "explanation": "%ΔQ = (80 - 100) / 100 = -%20. %ΔP = (12 - 10) / 10 = +%20. ed = -20 / 20 = -1.0 (Birim esnek)."}, {"id": 10, "unit": 2, "question": "Aşağıdakilerden hangisi arz eğrisini tamamen sağa kaydıran faktörlerden biridir?", "options": ["A) Girdi (hammadde) maliyetlerinin artması", "B) Üretim teknolojisindeki verimlilik artışı", "C) Üreticilere yeni vergiler konması", "D) Malın kendi satış fiyatının düşmesi", "E) Üretici sayısının azalması"], "correct_answer": "B", "explanation": "Teknolojik gelişme maliyetleri düşürür ve arz eğrisini sağa kaydırır."}, {"id": 11, "unit": 3, "question": "Bir firmanın üretim miktarı Q = 10 birim iken Toplam Sabit Maliyeti (TFC) 500 TL ise Ortalama Sabit Maliyeti (AFC) kaç TL'dir?", "options": ["A) 50 TL", "B) 500 TL", "C) 5.000 TL", "D) 10 TL", "E) 25 TL"], "correct_answer": "A", "explanation": "AFC = TFC / Q = 500 / 10 = 50 TL."}, {"id": 12, "unit": 3, "question": "Bir firmanın toplam maliyet fonksiyonu TC = 100 + 5Q + 2Q^2 olduğuna göre Marjinal Maliyet (MC) fonksiyonu nedir?", "options": ["A) 5 + 4Q", "B) 100 + 4Q", "C) 5 + 2Q", "D) 4Q", "E) 100 / Q + 5"], "correct_answer": "A", "explanation": "MC = d(TC)/dQ = 5 + 4Q."}, {"id": 13, "unit": 3, "question": "Ortalama Değişken Maliyet (AVC) ile Ortalama Toplam Maliyet (ATC) arasındaki fark aşağıdakilerden hangisine eşittir?", "options": ["A) Marjinal Maliyete (MC)", "B) Ortalama Sabit Maliyete (AFC)", "C) Toplam Maliyete (TC)", "D) Kâra", "E) Sıfıra"], "correct_answer": "B", "explanation": "ATC = AFC + AVC olduğuna göre ATC - AVC = AFC'dir."}, {"id": 14, "unit": 3, "question": "Uzun dönemde tüm girdiler %50 artırıldığında toplam üretim %30 artıyorsa ölçeğe göre getiri nasıldır?", "options": ["A) Ölçeğe göre artan getiri", "B) Ölçeğe göre azalan getiri", "C) Ölçeğe göre sabit getiri", "D) Sonsuz getiri", "E) Sıfır getiri"], "correct_answer": "B", "explanation": "Üretimdeki artış oranı (%30) girdilerdeki artış oranından (%50) küçükse 'Ölçeğe Göre Azalan Getiri' vardır."}, {"id": 15, "unit": 3, "question": "Aşağıdaki maliyet eğrilerinden hangisi U şeklinde DEĞİLDİR; aksine üretim arttıkça sürekli aşağı doğru iner?", "options": ["A) Ortalama Sabit Maliyet (AFC)", "B) Ortalama Değişken Maliyet (AVC)", "C) Ortalama Toplam Maliyet (ATC)", "D) Marjinal Maliyet (MC)", "E) Kısa Dönem Toplam Maliyet (TC)"], "correct_answer": "A", "explanation": "AFC = TFC / Q olduğundan ve sabit pay sürekli artan Q'ya bölündüğünden AFC sürekli azalır."}, {"id": 16, "unit": 4, "question": "Tam rekabet piyasasında uzun dönemde firmaların sadece 'Normal Kâr' elde etmesinin temel sebebi nedir?", "options": ["A) Piyasaya giriş ve çıkışların tamamen serbest olması", "B) Devletin tavan fiyat uygulaması", "C) Talebin inelastik olması", "D) Reklam harcamalarının yüksekliği", "E) Malların heterojen olması"], "correct_answer": "A", "explanation": "Serbest giriş-çıkış sayesinde aşırı kâr gören yeni firmalar piyasaya girer, arz artar, fiyat düşer ve aşırı kâr sıfırlanır."}, {"id": 17, "unit": 4, "question": "Monopolcü firmanın tüketici fazlasının tamamını elinden alarak her tüketiciye ödemeye razı olduğu en yüksek fiyattan satış yapmasına ne ad verilir?", "options": ["A) 1. Derece Fiyat Farklılaştırması (Tam Farklılaştırma)", "B) 2. Derece Fiyat Farklılaştırması (Miktar İndirimi)", "C) 3. Derece Fiyat Farklılaştırması (Pazar Bölümlendirme)", "D) Yıkıcı Fiyatlama", "E) Taban Fiyatlama"], "correct_answer": "A", "explanation": "Tüketici rantının tamamını üretici kârına dönüştüren uygulama 1. Derece Fiyat Farklılaştırmasıdır."}, {"id": 18, "unit": 4, "question": "Monopolcü rekabet piyasasını tam rekabet piyasasından ayıran en temel fark nedir?", "options": ["A) Çok sayıda firmanın olması", "B) Piyasaya girişin serbest olması", "C) Ürünlerin farklılaştırılmış (markalı/ambalajlı) olması", "D) Fiyatın sıfır olması", "E) Giriş engellerinin olması"], "correct_answer": "C", "explanation": "Monopolcü rekabette ürünler homojen değil, marka ve kaliteyle farklılaştırılmıştır."}, {"id": 19, "unit": 4, "question": "Oligopol piyasasında firmaların açıkça anlaşarak fiyatı ve üretim miktarını belirlemek üzere kurdukları tekel benzeri örgüte ne ad verilir?", "options": ["A) Kartel", "B) Holding", "C) Kooperatif", "D) Tröst", "E) Konsorsiyum"], "correct_answer": "A", "explanation": "OPEC gibi oligopolcülerin gizli veya açık birlik kurmasına Kartel denir."}, {"id": 20, "unit": 4, "question": "Monopolün varlığı nedeniyle ortaya çıkan ve ne üreticinin ne de tüketicinin alabildiği net toplumsal refah kaybına ne ad verilir?", "options": ["A) Sosyal maliyet", "B) Ölü dara kaybı (Harberger üçgeni)", "C) Enflasyonist açık", "D) Batık maliyet", "E) Negatif dışsallık"], "correct_answer": "B", "explanation": "Monopolün eksik üretim ve yüksek fiyat politikası sonucu toplumda yarattığı kayba Ölü Dara Kaybı (Deadweight Loss) denir."}]}, {"title": "Final Deneme Sınavı 1", "filename": "Final_Deneme_1.md", "questions": [{"id": 1, "unit": 1, "question": "(Vize Tekrarı) Tüketicinin sınırlı bütçesiyle satın alabileceği mal bileşimlerini gösteren doğruya ne ad verilir?", "options": ["A) Farksızlık eğrisi", "B) Bütçe doğrusu", "C) Talep eğrisi", "D) Eşürün eğrisi", "E) Phillips eğrisi"], "correct_answer": "B", "explanation": "Tüketicinin gelir sınırını gösteren doğru Bütçe Doğrusudur."}, {"id": 2, "unit": 2, "question": "(Vize Tekrarı) İki mal arasındaki çapraz talep esnekliği negatif (exy < 0) ise bu iki mal ne tür mallardır?", "options": ["A) İkame mallar", "B) Tamamlayıcı mallar", "C) Bağımsız mallar", "D) Lüks mallar", "E) Düşük mallar"], "correct_answer": "B", "explanation": "Çapraz esneklik negatif ise mallar Tamamlayıcıdır (Örn: Otomobil ve Benzin)."}, {"id": 3, "unit": 3, "question": "(Vize Tekrarı) Marjinal Maliyet (MC) eğrisi Ortalama Değişken Maliyet (AVC) eğrisini hangi noktasında keser?", "options": ["A) AVC'nin minimum noktasında", "B) AVC'nin maksimum noktasında", "C) Sıfır noktasında", "D) TFC ile kesiştiği yerde", "E) Kesmez"], "correct_answer": "A", "explanation": "MC eğrisi AVC'yi minimum noktasında alttan keser."}, {"id": 4, "unit": 4, "question": "(Vize Tekrarı) Tam rekabet piyasasında firmanın kısa dönem kâr maksimizasyonu koşulu nedir?", "options": ["A) P = MC", "B) P > ATC", "C) MR > MC", "D) TR = TC", "E) P = AFC"], "correct_answer": "A", "explanation": "Tam rekabette P = MR = MC geçerlidir."}, {"id": 5, "unit": 5, "question": "1936 yılında 'İstihdam, Faiz ve Paranın Genel Teorisi' kitabını yazarak modern makroekonominin kurucusu kabul edilen iktisatçı kimdir?", "options": ["A) Adam Smith", "B) David Ricardo", "C) John Maynard Keynes", "D) Milton Friedman", "E) Joseph Schumpeter"], "correct_answer": "C", "explanation": "Modern makroekonominin kurucusu John Maynard Keynes'tir."}, {"id": 6, "unit": 5, "question": "Bir ekonomide harcamalar yöntemiyle Gayri Safi Yurtiçi Hasıla (GSYH) hesaplanırken aşağıdakilerden hangisi formüle dahil EDİLMEZ?", "options": ["A) Tüketim Harcamaları (C)", "B) Yatırım Harcamaları (I)", "C) Kamu Harcamaları (G)", "D) Net İhracat (X - M)", "E) İkinci el otomobil satış bedelleri"], "correct_answer": "E", "explanation": "GSYH yalnızca o yıl üretilen nihai mal ve hizmetleri kapsar; ikinci el satışlar cari dönem üretimi olmadığından dahil edilmez."}, {"id": 7, "unit": 5, "question": "Nominal GSYH 1.200 milyar TL ve Reel GSYH 1.000 milyar TL olduğuna göre GSYH Deflatörü kaçtır?", "options": ["A) 83.3", "B) 100", "C) 120", "D) 200", "E) 12"], "correct_answer": "C", "explanation": "Deflatör = (Nominal / Reel) * 100 = (1200 / 1000) * 100 = 120."}, {"id": 8, "unit": 5, "question": "Ekonomik kriz ve durgunluk dönemlerinde toplam talep yetersizliği sebebiyle ortaya çıkan işsizlik türü hangisidir?", "options": ["A) Friksiyonel işsizlik", "B) Yapısal işsizlik", "C) Konjonktürel (Dönemsel/Keynesyen) işsizlik", "D) Mevsimsel işsizlik", "E) Gizli işsizlik"], "correct_answer": "C", "explanation": "Ekonomik daralmadan kaynaklanan işsizlik Konjonktürel (Dönemsel) işsizliktir."}, {"id": 9, "unit": 6, "question": "Marjinal Tüketim Eğilimi MPC = 0.75 olan bir ekonomide Basit Yatırım Çarpanı (k) kaçtır?", "options": ["A) 2", "B) 3", "C) 4", "D) 5", "E) 0.25"], "correct_answer": "C", "explanation": "k = 1 / (1 - MPC) = 1 / (1 - 0.75) = 1 / 0.25 = 4."}, {"id": 10, "unit": 6, "question": "Marjinal Tüketim Eğilimi (MPC) ile Marjinal Tasarruf Eğilimi (MPS) arasındaki matematiksel ilişki nedir?", "options": ["A) MPC * MPS = 1", "B) MPC + MPS = 1", "C) MPC - MPS = 0", "D) MPC / MPS = 1", "E) MPC + MPS = 0"], "correct_answer": "B", "explanation": "Gelir ya tüketilir ya tasarruf edilir: MPC + MPS = 1."}, {"id": 11, "unit": 6, "question": "Kamu harcamaları 20 milyar TL artırılırken aynı anda vergiler de 20 milyar TL artırılırsa, Denk Bütçe Çarpanına göre millî gelir nasıl değişir?", "options": ["A) Değişmez", "B) 20 milyar TL artar", "C) 20 milyar TL azalır", "D) 40 milyar TL artar", "E) 80 milyar TL artar"], "correct_answer": "B", "explanation": "Denk bütçe çarpanı k = 1'dir. Dolayısıyla harcama ve vergi 20 milyar artırılırsa millî gelir de tam 20 milyar TL artar."}, {"id": 12, "unit": 6, "question": "Ekonomide toplam harcamaların tam istihdam üretim kapasitesini aşması sonucu fiyatların yükselmesine neden olan durum nedir?", "options": ["A) Deflasyonist Açık", "B) Enflasyonist Açık", "C) Likidite Tuzağı", "D) Bütçe Açığı", "E) Cari Açık"], "correct_answer": "B", "explanation": "Harcamaların tam istihdam kapasitesini aşması Enflasyonist Açıktır."}, {"id": 13, "unit": 7, "question": "Dolaşımdaki nakit para ile bankalardaki vadesiz mevduatların toplamından oluşan en likit para arzı tanımı hangisidir?", "options": ["A) M1", "B) M2", "C) M3", "D) M0", "E) Emisyon"], "correct_answer": "A", "explanation": "M1 = Dolaşımdaki Nakit + Vadesiz Mevduatlar."}, {"id": 14, "unit": 7, "question": "Zorunlu karşılık oranı r = %20 (0.20) olan bir bankacılık sisteminde basit kredi (mevduat) çarpanı kaçtır?", "options": ["A) 2", "B) 4", "C) 5", "D) 10", "E) 20"], "correct_answer": "C", "explanation": "Çarpan = 1 / r = 1 / 0.20 = 5."}, {"id": 15, "unit": 7, "question": "Merkez Bankasının piyasadaki para arzını artırmak (genişletici para politikası uygulamak) için açık piyasada ne yapması gerekir?", "options": ["A) Hazine bonosu ve tahvil satın almalıdır.", "B) Hazine bonosu ve tahvil satmalıdır.", "C) Zorunlu karşılık oranlarını artırmalıdır.", "D) Reeskont faiz oranını yükseltmelidir.", "E) Vergi oranlarını artırmalıdır."], "correct_answer": "A", "explanation": "Bono satın aldığında piyasaya nakit para girer ve para arzı genişler."}, {"id": 16, "unit": 7, "question": "Keynes'e göre faiz oranları ile para talebinin spekülasyon güdüsü arasındaki ilişki nasıldır?", "options": ["A) Doğru yönlüdür (faiz artarsa spekülasyon para talebi artar)", "B) Ters yönlüdür (faiz artarsa spekülasyon para talebi azalır)", "C) Bağımsızdır", "D) Sıfırdır", "E) Önce artar sonra azalır"], "correct_answer": "B", "explanation": "Faizler yükseldiğinde parayı nakitte tutmanın fırsat maliyeti artar ve spekülatif para talebi düşer (ters yönlü ilişki)."}, {"id": 17, "unit": 8, "question": "Toplam Talep (AD) eğrisinin negatif eğimli olmasını açıklayan 'Faiz Oranı Etkisi' iktisat literatüründe kimin adıyla anılır?", "options": ["A) Pigou Etkisi", "B) Keynes Etkisi", "C) Mundell-Fleming Etkisi", "D) Fisher Etkisi", "E) Laffer Etkisi"], "correct_answer": "B", "explanation": "Fiyatlar düşünce faizlerin düşmesi ve yatırımların artması Keynes Etkisidir (Servet etkisi Pigou, dış ticaret ise Mundell-Fleming'dir)."}, {"id": 18, "unit": 8, "question": "Uzun Dönem Toplam Arz Eğrisi (LRAS) neden potansiyel GSYH düzeyinde dikey bir doğrudur?", "options": ["A) Fiyat ve ücretlerin uzun dönemde tamamen esnek olması nedeniyle", "B) Teknolojinin değişmemesi nedeniyle", "C) Faizlerin sıfır olması nedeniyle", "D) Devletin fiyatları belirlemesi nedeniyle", "E) İhracatın sıfır olması nedeniyle"], "correct_answer": "A", "explanation": "Uzun dönemde fiyat ve ücretler tam esnektir, ekonomi kapasite (tam istihdam) sınırındadır."}, {"id": 19, "unit": 8, "question": "Ekonomide yüksek enflasyon ile işsizlik ve ekonomik durgunluğun bir arada yaşanmasına ne ad verilir?", "options": ["A) Deflasyon", "B) Devalüasyon", "C) Stagflasyon", "D) Resesyon", "E) Hiperenflasyon"], "correct_answer": "C", "explanation": "Durgunluk (stagnation) ve enflasyonun (inflation) birleşimi Stagflasyondur."}, {"id": 20, "unit": 8, "question": "Ekonomik durgunluk (resesyon) döneminde hükümetin uygulayacağı genişletici maliye politikası aşağıdakilerden hangisidir?", "options": ["A) Kamu harcamalarını artırmak ve vergileri azaltmak", "B) Kamu harcamalarını kısmak ve vergileri artırmak", "C) Faiz oranlarını yükseltmek", "D) Para arzını kısmak", "E) İthalatı yasaklamak"], "correct_answer": "A", "explanation": "Genişletici maliye politikası kamu harcamalarını (G) artırmak ve vergileri (T) düşürmektir."}]}, {"title": "Final Deneme Sınavı 2", "filename": "Final_Deneme_2.md", "questions": [{"id": 1, "unit": 1, "question": "(Vize Tekrarı) Marjinal Fayda (MU) sıfır olduğunda Toplam Fayda (TU) nasıldır?", "options": ["A) Sıfırdır", "B) Minimumdur", "C) Maksimumdur", "D) Azalandır", "E) Tanımsızdır"], "correct_answer": "C", "explanation": "MU = 0 iken TU tepe noktasındadır (Maksimumdur)."}, {"id": 2, "unit": 2, "question": "(Vize Tekrarı) Fiyatı %10 artan bir malın talep edilen miktarı %20 azalıyorsa bu malın talebin fiyat esnekliği (|ed|) kaçtır?", "options": ["A) 0.5", "B) 1.0", "C) 2.0", "D) 3.0", "E) 0.2"], "correct_answer": "C", "explanation": "|ed| = %20 / %10 = 2.0."}, {"id": 3, "unit": 3, "question": "(Vize Tekrarı) Bir firmanın Toplam Maliyeti TC = 300 + 40Q olduğuna göre Sabit Maliyeti (TFC) kaç TL'dir?", "options": ["A) 40 TL", "B) 300 TL", "C) 340 TL", "D) 0 TL", "E) 120 TL"], "correct_answer": "B", "explanation": "Q'ya bağlı olmayan sabit terim TFC = 300 TL'dir."}, {"id": 4, "unit": 4, "question": "(Vize Tekrarı) Tekelci bir firmanın kârını maksimize eden temel kural hangisidir?", "options": ["A) MR = MC", "B) P = ATC", "C) TR = TC", "D) MR = 0", "E) MC = 0"], "correct_answer": "A", "explanation": "Tüm firmalar için kâr maksimizasyonu MR = MC koşulunda gerçekleşir."}, {"id": 5, "unit": 5, "question": "Friksiyonel işsizlik ile yapısal işsizliğin toplamına ne ad verilir?", "options": ["A) Döngüsel işsizlik", "B) Doğal işsizlik oranı", "C) Mevsimsel işsizlik", "D) Gizli işsizlik", "E) Efektif işsizlik"], "correct_answer": "B", "explanation": "Doğal İşsizlik = Friksiyonel + Yapısal işsizliktir."}, {"id": 6, "unit": 5, "question": "Enflasyonun arındırıldığı ve sabit baz yıl fiyatlarıyla hesaplanan GSYH büyüklüğüne ne ad verilir?", "options": ["A) Nominal GSYH", "B) Reel GSYH", "C) Potansiyel GSYH", "D) Net Yurtiçi Hasıla", "E) Kişi Başına Gelir"], "correct_answer": "B", "explanation": "Enflasyondan arındırılmış reel çıktıyı Reel GSYH gösterir."}, {"id": 7, "unit": 5, "question": "İşgücüne dahil olan 30 milyon kişinin bulunduğu bir ülkede 3 milyon işsiz varsa işsizlik oranı yüzde kaçtır?", "options": ["A) %5", "B) %10", "C) %15", "D) %20", "E) %3"], "correct_answer": "B", "explanation": "İşsizlik Oranı = (3 / 30) * 100 = %10."}, {"id": 8, "unit": 6, "question": "Bir ekonomide Marjinal Tüketim Eğilimi MPC = 0.80 olduğuna göre Marjinal Tasarruf Eğilimi (MPS) kaçtır?", "options": ["A) 0.20", "B) 0.50", "C) 0.80", "D) 1.20", "E) 0.10"], "correct_answer": "A", "explanation": "MPC + MPS = 1 => MPS = 1 - 0.80 = 0.20."}, {"id": 9, "unit": 6, "question": "Marjinal Tüketim Eğilimi MPC = 0.60 ise Kamu Harcamaları Çarpanı kaçtır?", "options": ["A) 1.5", "B) 2.0", "C) 2.5", "D) 4.0", "E) 5.0"], "correct_answer": "C", "explanation": "kg = 1 / (1 - 0.60) = 1 / 0.40 = 2.5."}, {"id": 10, "unit": 6, "question": "Gelir düzeyi sıfır iken yapılan zorunlu tüketime ne ad verilir?", "options": ["A) Uyarılmış tüketim", "B) Otonom tüketim (C0)", "C) Marjinal tüketim", "D) Negatif tasarruf", "E) Lüks tüketim"], "correct_answer": "B", "explanation": "Gelirden bağımsız yapılan asgari tüketime Otonom Tüketim denir."}, {"id": 11, "unit": 7, "question": "M1 para arzına bankalardaki vadeli mevduatların eklenmesiyle elde edilen para arzı büyüklüğü hangisidir?", "options": ["A) M0", "B) M2", "C) M3", "D) M4", "E) Rezerv para"], "correct_answer": "B", "explanation": "M2 = M1 + Vadeli Mevduatlar."}, {"id": 12, "unit": 7, "question": "Ticari bankaların topladıkları mevduatların belirli bir yüzdesini Merkez Bankası bünyesinde tutmak zorunda oldukları orana ne denir?", "options": ["A) Reeskont oranı", "B) Zorunlu Karşılık Oranı (Munzam Karşılık)", "C) Faiz koridoru", "D) Politika faizi", "E) Tasarruf oranı"], "correct_answer": "B", "explanation": "Bankaların Merkez Bankasında tuttuğu zorunlu oran Zorunlu Karşılık Oranıdır."}, {"id": 13, "unit": 7, "question": "Merkez Bankasının ticari bankalara reeskont kredisi verirken uyguladığı faiz oranına ne ad verilir?", "options": ["A) Reeskont Faiz Oranı", "B) Gecelik faiz", "C) Libor faizi", "D) Bono faizi", "E) Enflasyon oranı"], "correct_answer": "A", "explanation": "Merkez Bankasının senet kırdırma faizi Reeskont Oranıdır."}, {"id": 14, "unit": 7, "question": "Paranın mal ve hizmet alım-satımında takası ortadan kaldırarak kullanılması paranın hangi temel işlevidir?", "options": ["A) Değişim (Mübadele) aracı olma", "B) Değer saklama aracı olma", "C) Hesap birimi olma", "D) Değer standardı olma", "E) Yatırım aracı olma"], "correct_answer": "A", "explanation": "Alışverişte aracılık etmesi Değişim (Mübadele) aracı olma işlevidir."}, {"id": 15, "unit": 8, "question": "Fiyatlar genel düzeyinin düşmesi sonucunda yerli malların yabancı mallara göre ucuzlaması ve net ihracatın artması sebebiyle AD eğrisinin negatif eğimli olmasını açıklayan etki nedir?", "options": ["A) Pigou Etkisi (Servet Etkisi)", "B) Keynes Etkisi (Faiz Etkisi)", "C) Mundell-Fleming Etkisi (Uluslararası Ticaret Etkisi)", "D) Gelir Etkisi", "E) İkame Etkisi"], "correct_answer": "C", "explanation": "Net ihracat kanalı Mundell-Fleming (Uluslararası Ticaret) etkisidir."}, {"id": 16, "unit": 8, "question": "Kısa Dönem Toplam Arz (SRAS) eğrisini SOLA kaydırarak stagflasyona yol açan faktör hangisidir?", "options": ["A) Petrol ve enerji fiyatlarında ani ve büyük bir artış (Maliyet şoku)", "B) Teknolojik ilerleme", "C) Ücretlerin düşmesi", "D) Para arzının artması", "E) Kamu harcamalarının artması"], "correct_answer": "A", "explanation": "Negatif arz şokları (enerji fiyatlarının sıçraması) SRAS'ı sola kaydırır ve stagflasyona yol açar."}, {"id": 17, "unit": 8, "question": "Enflasyonist baskıların yaşandığı bir ekonomide Merkez Bankasının uygulayacağı daraltıcı para politikası adımı hangisidir?", "options": ["A) Politika faizini artırmak ve açık piyasada bono satmak", "B) Faizleri indirmek", "C) Piyasadan bono satın almak", "D) Zorunlu karşılıkları düşürmek", "E) Para basmak"], "correct_answer": "A", "explanation": "Daraltıcı para politikası faizleri yükseltmek ve bono satarak likidite çekmektir."}, {"id": 18, "unit": 8, "question": "Klasik iktisatçılara göre toplam arz eğrisi nasıldır?", "options": ["A) Yataydır", "B) Daima tam istihdam düzeyinde dikeydir", "C) Pozitif eğimlidir", "D) Negatif eğimlidir", "E) U şeklindedir"], "correct_answer": "B", "explanation": "Klasiklere göre ekonomi kendiliğinden tam istihdama gelir ve arz eğrisi dikeydir."}, {"id": 19, "unit": 8, "question": "Hükümetin vergi oranlarını artırması ve kamu yatırımlarını kısması hangi politika türüdür?", "options": ["A) Genişletici Maliye Politikası", "B) Daraltıcı Maliye Politikası", "C) Genişletici Para Politikası", "D) Daraltıcı Para Politikası", "E) Gelirler Politikası"], "correct_answer": "B", "explanation": "Harcamaları kısıp vergileri artırmak Daraltıcı Maliye Politikasıdır."}, {"id": 20, "unit": 8, "question": "Bir ülkede potansiyel GSYH düzeyinin üzerinde üretim yapıldığında ortaya çıkan açık türü nedir?", "options": ["A) Enflasyonist Açık", "B) Deflasyonist Açık", "C) Bütçe Açığı", "D) Cari Açık", "E) Tasarruf Açığı"], "correct_answer": "A", "explanation": "Fiili üretimin potansiyeli aşması Enflasyonist Açık oluşturur."}]}]}, "isletme_ilkeleri": {"course_name": "İŞLETME İLKELERİ", "course_code": "İŞL101U", "faculty": "İşletme / İktisat Fakültesi - Yönetim Bilişim Sistemleri (YBS)", "term": "1. Sınıf Güz Dönemi", "description": "İşletmecilik temel kavramları, işletme çevresi, işletme türleri, sosyal sorumluluk ve iş ahlakı, kuruluş süreci ve fizibilite araştırmaları, büyüme stratejileri, küresel rekabet ve işletme fonksiyonları.", "units": [{"unit_number": 1, "title": "İşletmecilik ve İşletmecilik ile İlgili Kavramlar", "is_vize": true, "key_topics": ["İşletme Tanımı ve Özellikleri", "Maslow İhtiyaçlar Hiyerarşisi", "4 Üretim Faktörü ve Getirileri", "Girişimci ve Profesyonel Yönetici", "Verimlilik, Etkililik ve İktisadilik"], "hap_bilgiler": ["İşletmenin Tanımı: İnsanların ihtiyaçlarını karşılamak üzere mal ve hizmet üreten, kâr veya sosyal fayda amacı güden, finansal ve operasyonel risk üstlenen ekonomik birimdir.", "Maslow'un İhtiyaçlar Hiyerarşisi (Aşağıdan Yukarıya 5 Basamak): 1. Fizyolojik İhtiyaçlar (Açlık, susuzluk, barınma - temel taban), 2. Güvenlik İhtiyaçları (İş güvencesi, can ve mal güvenliği), 3. Sosyal / Ait Olma İhtiyaçları (Sevgi, arkadaşlık, gruba kabul), 4. Saygınlık İhtiyaçları (Statü, takdir, itibar), 5. Kendini Gerçekleştirme (Potansiyelini tam kullanma - ZİRVEDEKİ İHTİYAÇTIR).", "4 Temel Üretim Faktörü ve Karşılıkları (Gelirleri):", "  - Emek (İşgücü): Karşılığı ÜCRET.", "  - Sermaye (Finansal ve fiziki araçlar): Karşılığı FAİZ.", "  - Doğal Kaynaklar (Toprak): Karşılığı RANT (Kira).", "  - Girişimci (Müteşebbis): Karşılığı KÂR (Zarar riskini üstlenir).", "Girişimci vs Profesyonel Yönetici:", "  - Girişimci: Fırsatları sezen, üretim faktörlerini bir araya getiren, sermaye koyan ve kâr/zarar riskini bizzat üstlenen kişidir.", "  - Profesyonel Yönetici: Kendi sermayesini koymak zorunda olmayan, işletme sahibi adına işletmeyi sevk ve idare eden, emeği karşılığı ücret veya prim alan profesyoneldir.", "İşletme Başarı Ölçütleri:", "  - Verimlilik (Productivity): Üretilen Çıktı / Kullanılan Girdi oranıdır.", "  - Etkililik (Effectiveness): İşletmenin önceden belirlenen amaç ve hedeflere ulaşma derecesidir ('Doğru işleri yapmak').", "  - İktisadilik (Karlılık): Satış Hasılatı / Katlanılan Gider oranıdır."]}, {"unit_number": 2, "title": "İşletme ve Çevresi", "is_vize": true, "key_topics": ["Sistem Olarak İşletme", "İç Çevre Faktörleri", "Yakın Dış Çevre (Sektörel / Porter)", "Genel Dış Çevre (PESTLE)", "Çevresel Belirsizlik"], "hap_bilgiler": ["Açık Sistem Olarak İşletme: İşletme çevresinden girdi alan (hammadde, işgücü, bilgi, sermaye), bunları üretim sürecinde dönüştüren, çevreye çıktı sunan (mal, hizmet, atık) ve geri bildirimle kendini güncelleyen açık bir sistemdir.", "İşletmenin 3 Çevre Katmanı:", "  1. İç Çevre (Örgütsel Çevre): İşletmenin doğrudan kontrol edebildiği iç faktörlerdir (Yönetim yapısı, kurum kültürü, insan kaynakları, finansal güç, fiziki tesisler).", "  2. Yakın Dış Çevre (Sektörel / Görev Çevresi): İşletmenin doğrudan etkileşimde bulunduğu paydaşlardır (Müşteriler, Rakipler, Tedarikçiler, İkame Ürünler, Finans Kuruluşları). Michael Porter'ın '5 Güç Modeli' bu çevreyi analiz eder.", "  3. Genel Dış Çevre (Makro Çevre - PESTLE): İşletmenin kontrol edemediği, uyum sağlamak zorunda olduğu geniş çevredir:", "     - Politik / Yasal Faktörler (Hükümet politikaları, mevzuat, vergiler).", "     - Ekonomik Faktörler (Enflasyon, döviz kuru, faiz oranları, millî gelir).", "     - Sosyo-Kültürel Faktörler (Demografi, yaşam tarzları, toplumsal değerler).", "     - Teknolojik Faktörler (Otomasyon, yapay zeka, Ar-Ge yenilikleri).", "     - Ekolojik / Doğal Faktörler (İklim değişikliği, hammadde kıtlığı).", "Çevresel Belirsizlik: Çevredeki faktör sayısı (basit/karmaşık) ve değişim hızı (durağan/dinamik) ile belirlenir. 'Karmaşık ve Dinamik' çevreler en yüksek belirsizliğe sahiptir."]}, {"unit_number": 3, "title": "İşletmelerin Sınıflandırılması ve Türleri", "is_vize": true, "key_topics": ["Faaliyet Alanına Göre İşletmeler", "Büyüklüklerine Göre (KOBİ)", "Şahıs Şirketleri", "Sermaye Şirketleri", "Kooperatifler"], "hap_bilgiler": ["Büyüklüklerine Göre İşletmeler (KOBİ Tanımı):", "  - Mikro İşletme: 1 - 9 çalışan.", "  - Küçük İşletme: 10 - 49 çalışan.", "  - Orta Büyüklükteki İşletme: 50 - 249 çalışan.", "  - Büyük İşletme: 250 ve üzeri çalışan.", "Şahıs Şirketleri (Ortakların sorumluluğu kural olarak sınırsız ve müteselsildir):", "  - Adi Şirket: Türk Borçlar Kanunu'na tabidir, tüzel kişiliği ve ticaret unvanı yoktur, ortaklar tüm malvarlıklarıyla sınırsız sorumludur.", "  - Kollektif Şirket: Yalnızca gerçek kişilerce kurulur, tüzel kişiliği vardır, ortakların sorumluluğu sınırsız ve zincirleme (müteselsil) sorumluluktur.", "  - Komandit Şirket: İki tür ortak vardır:", "    1. Komandite Ortak: Sorumluluğu sınırsız olan ortaktır (Yalnızca gerçek kişi olabilir, şirketi yönetir).", "    2. Komanditer Ortak: Sorumluluğu koyduğu sermaye payı ile SINIRLI olan ortaktır (Tüzel kişi de olabilir, şirketi yönetemez).", "Sermaye Şirketleri (Ortakların sorumluluğu koydukları sermaye ile sınırlıdır):", "  - Anonim Şirket (A.Ş.): Sermayesi belirli ve paylara bölünmüş olan, asgari 50.000 TL sermaye ile kurulabilen, pay devri çok kolay olan şirkettir.", "  - Limited Şirket (Ltd. Şti.): Ortak sayısı en çok 50 olabilen, asgari 10.000 TL sermaye ile kurulan, pay devri noter ve ticaret sicil tesciline tabi olan şirkettir.", "Kooperatifler: Amacı kâr elde etmek değil, ortaklarının meslek veya geçim ihtiyaçlarını karşılıklı yardım ve dayanışma yoluyla en uygun şartlarda karşılamaktır."]}, {"unit_number": 4, "title": "Sosyal Sorumluluk ve İş Ahlakı", "is_vize": true, "key_topics": ["Kurumsal Sosyal Sorumluluk (KSS)", "Carroll'ın Sosyal Sorumluluk Piramidi", "Paydaş Teorisi", "İş Etiği ve Whistleblowing", "Yeşil Yıkama (Greenwashing)"], "hap_bilgiler": ["Kurumsal Sosyal Sorumluluk (KSS): İşletmenin sadece yasalara uymakla kalmayıp, toplumun refahını artıracak ve çevreyi koruyacak gönüllü faaliyetlerde bulunmasıdır.", "Archie Carroll'ın Sosyal Sorumluluk Piramidi (4 Katman):", "  1. Ekonomik Sorumluluk (Taban): Kârlı olmak, istihdam yaratmak ve verimli üretmek (Tüm diğer sorumlulukların temelidir).", "  2. Yasal Sorumluluk: Kanunlara, kurallara ve mevzuata eksiksiz uymak.", "  3. Etik Sorumluluk: Yasalarda açıkça yazmasa bile doğru, adil, dürüst ve ahlaki olanı yapmak.", "  4. Filantropik (Gönüllü) Sorumluluk (Zirve): Eğitime, sanata, sağlığa bağış yapmak, topluma katkı sağlayan iyi bir kurumsal vatandaş olmak.", "Paydaş (Stakeholder) Teorisi: İşletmenin kararlarından etkilenen veya işletmeyi etkileyen tüm kişi ve gruplardır (Hissedarlar, çalışanlar, müşteriler, tedarikçiler, yerel toplum, sendikalar).", "İş Ahlakı (İş Etiği): İş hayatındaki davranışların doğru veya yanlış, adil veya haksız olarak değerlendirilmesine rehberlik eden ahlaki ilkeler ve standartlardır.", "Whistleblowing (İçeriden Bilgi İfşası / Etik Bildirim): Bir çalışanın şirket içinde yapılan yasadışı, hileli, tehlikeli veya etik dışı bir durumu yetkili mercilere veya kamuoyuna ifşa etmesidir.", "Yeşil Yıkama (Greenwashing): Bir işletmenin gerçekte çevre dostu olmadığı halde kendini reklam ve pazarlama yoluyla çevreci ve sürdürülebilir gibi göstermesi aldatmacasıdır."]}, {"unit_number": 5, "title": "İşletmelerin Kuruluşu", "is_vize": false, "key_topics": ["İşletme Kurma Süreci Aşamaları", "Fizibilite (Yapılabilirlik) Araştırması", "Ekonomik, Teknik ve Finansal Etüt", "Kuruluş Yeri Seçimi Kriterleri"], "hap_bilgiler": ["İşletme Kurma Süreci Kronolojik Adımları: Yatırım Düşüncesi -> Ön Fizibilite -> Fizibilite Araştırması (Yapılabilirlik Etüdü) -> Fizibilite Raporu ve Değerlendirme -> Yatırım Kararı -> Kesin Proje Hazırlama -> Tesisin Kurulması / Uygulama -> Deneme Üretimi -> Kesin İşletmeye Geçiş.", "Fizibilite Araştırmasının 4 Temel Boyutu:", "  1. Ekonomik Etüt: Pazar araştırması, talep tahmini, pazar payı, kapasite seçimi ve ürün fiyatlandırma analizi.", "  2. Teknik Etüt: Üretim teknolojisi, makine-ekipman seçimi, fabrika yerleşim planı, hammadde temin yöntemleri.", "  3. Finansal Etüt: Toplam yatırım tutarı, sermaye ihtiyacı, fon kaynakları, Net Bugünkü Değer (NBD), İç Verim Oranı (İVO), Kârlılık ve Başabaş Noktası analizi.", "  4. Yasal ve Örgütsel Etüt: Şirket türünün seçimi, resmi izinler, teşvikler, çevre etki değerlendirmesi (ÇED) ve organizasyon şeması.", "Kuruluş Yeri Faktörleri: Hammaddeye yakınlık (çabuk bozulan veya nakliyesi pahalı girdilerde), Pazara yakınlık (tüketiciye hızla ulaşma), İşgücü temini, Enerji ve su kaynakları, Ulaşım ve lojistik olanakları, Devlet teşvikleri.", "Optimum Kuruluş Yeri: İşletmenin maliyetlerini en aza indirirken kârını ve verimliliğini en üst düzeye çıkaran ideal coğrafi konumdur."]}, {"unit_number": 6, "title": "İşletmelerin Büyümesi", "is_vize": false, "key_topics": ["Büyüme Nedenleri", "İç Büyüme ve Dış Büyüme", "Yatay, Dikey ve Konglomerat Büyüme", "Ortak Girişim (Joint Venture) ve Birleşmeler"], "hap_bilgiler": ["İşletmelerin Büyüme Nedenleri: Ölçek ekonomilerinden yararlanarak birim maliyeti düşürmek, pazar payını artırmak, finansal güç kazanmak, riski dağıtmak ve prestij sağlamak.", "Büyüme Biçimleri:", "  - İç Büyüme: İşletmenin kendi özkaynakları, kâr birikimi (otofinansman) ve AR-GE'si ile mevcut kapasitesini artırması, yeni ürün veya pazarlar geliştirmesidir.", "  - Dış Büyüme: Başka işletmelerle birleşme (Merger) veya başka şirketleri satın alma (Acquisition / M&A) yoluyla hızlı büyümedir.", "Büyüme Yönleri:", "  - Yatay Büyüme: Aynı sektörde ve aynı üretim aşamasındaki rakipleri bünyesine katarak veya aynı ürünü üreten yeni fabrikalar açarak büyümedir (Örn: Bir tekstilcinin başka bir tekstil firmasını satın alması).", "  - Dikey Büyüme:", "    * Geriye Doğru Dikey Büyüme: İşletmenin hammadde veya girdi tedarikçisini bünyesine katması (Örn: Lastik üreticisinin kauçuk çiftliği satın alması).", "    * İleriye Doğru Dikey Büyüme: İşletmenin dağıtım kanalını, toptancıları veya perakende satış mağazalarını bünyesine katması (Örn: Fabrikanın kendi mağaza zincirini açması).", "  - Çapraz / Karma (Konglomerat) Büyüme: Birbirleriyle hiçbir teknolojik veya sektörel bağı bulunmayan tamamen farklı sektörlere girerek büyümedir (Holding yapılanmaları; amaç riski çeşitlendirmektir).", "İş Birlikleri:", "  - Joint Venture (Ortak Girişim): İki veya daha fazla bağımsız şirketin belirli bir amaç doğrultusunda bir araya gelerek 'YENİ VE BAĞIMSIZ BİR TÜZEL KİŞİLİK (ŞİRKET)' kurmasıdır.", "  - Konsorsiyum: Büyük bir altyapı ihalesini (köprü, baraj) gerçekleştirmek üzere kurulan geçici işbirliğidir.", "  - Kartel: Aynı sektördeki firmaların rekabeti ortadan kaldırmak için fiyat veya kota anlaşması yapmasıdır (Hukuken yasaktır)."]}, {"unit_number": 7, "title": "Küresel Çevrede İşletmecilik ve Rekabet", "is_vize": false, "key_topics": ["Küreselleşme Kavramı", "Uluslararasılaşma Aşamaları", "Çokuluslu Şirket Stratejileri", "Michael Porter'ın Jenerik Rekabet Stratejileri"], "hap_bilgiler": ["Uluslararasılaşma Aşamaları (Düşük Riskten Yüksek Risklere Doğru Sıralama):", "  1. İhracat (Exporting): Dolaylı veya doğrudan ihracat (En az riskli ve en yaygın ilk adımdır).", "  2. Lisans Anlaşmaları ve Franchise Verme: Marka veya teknolojinin kullanım hakkını devretme.", "  3. Stratejik İttifaklar ve Ortak Girişimler (Joint Venture): Yerel bir ortakla ortak şirket kurma.", "  4. Doğrudan Yabancı Yatırım (FDI): Yabancı ülkede sıfırdan tesis kurma (Greenfield yatırım) veya yerel bir şirketi doğrudan satın alma (En yüksek risk ve en yüksek kontrole sahiptir).", "Çokuluslu Şirketlerin Stratejik Yaklaşımları:", "  - Çok Uluslu (Multidomestic) Strateji: Her ülkenin yerel tüketici tercihlerine göre ürün ve pazarlamayı uyarlamak (Yüksek yerel uyum).", "  - Küresel (Global) Strateji: Tüm dünyada standartlaştırılmış tek bir ürün satarak küresel maliyet avantajı yakalamak (Düşük yerel uyum, yüksek entegrasyon).", "  - Ulusötesi (Transnational) Strateji: Hem küresel ölçek ekonomilerini hem de yerel farklılıklara uyumu birleştiren karma stratejidir.", "Michael Porter'ın 3 Jenerik Rekabet Stratejisi:", "  1. Maliyet Liderliği: Sektördeki en düşük maliyetle üretim yaparak geniş pazara ucuz fiyatla hakim olmak (Örn: BİM, IKEA).", "  2. Farklılaştırma: Müşterilerin benzersiz algıladığı üstün tasarım, kalite veya marka imajı yaratarak primli fiyat uygulamak (Örn: Apple, BMW).", "  3. Odaklanma (Niş) Stratejisi: Tüm pazara değil, dar bir tüketici veya coğrafya segmentine odaklanarak orada maliyet liderliği ya da farklılaştırma uygulamak (Örn: Ferrari, lüks saatler)."]}, {"unit_number": 8, "title": "İşletme Fonksiyonları", "is_vize": false, "key_topics": ["Yönetim Fonksiyonları (POLC)", "Üretim Fonksiyonu ve Kalite", "Pazarlama Fonksiyonu (4P ve STP)", "Finansman ve İnsan Kaynakları Fonksiyonları"], "hap_bilgiler": ["Yönetim Fonksiyonları (POLC Döngüsü):", "  - Planlama: Amaç ve hedeflerin belirlenmesi, bunlara nasıl ulaşılacağının kararlaştırılmasıdır (Yönetimin İLK fonksiyonudur).", "  - Örgütleme (Organize Etme): İnsanların, görevlerin, yetkilerin ve fiziki kaynakların amaca uygun şekilde yapılandırılmasıdır.", "  - Yöneltme (Yürütme / Liderlik): Çalışanların motive edilmesi, liderlik yapılması ve ortak hedefe doğru yönlendirilmesidir.", "  - Denetim (Kontrol): Standartların belirlenmesi, gerçekleşen sonuçların ölçülmesi, sapmaların tespit edilip düzeltici tedbirlerin alınmasıdır (Yönetimin SON fonksiyonudur).", "Pazarlama Fonksiyonu ve Pazarlama Karması (4P):", "  - Product (Ürün): Mal, hizmet, ambalaj, marka, garanti.", "  - Price (Fiyat): Maliyet, rekabet ve tüketici algısına göre belirlenen bedel.", "  - Place (Dağıtım): Ürünün üreticiden tüketiciye ulaştırıldığı kanallar.", "  - Promotion (Tutundurma): Reklam, halkla ilişkiler, kişisel satış, satış promosyonları.", "  - Modern Hizmet Pazarlaması Ek 3P'si: People (İnsan), Process (Süreç), Physical Evidence (Fiziksel Kanıtlar).", "Finansman Fonksiyonu: İşletmenin ihtiyaç duyduğu fonları en uygun maliyetle temin etmesi ve bu fonları en verimli alanlara yatırmasıdır. Temel amaç işletmenin piyasa değerini maksimize etmektir.", "İnsan Kaynakları Yönetimi (İKY): İnsan kaynağının planlanması, iş analizi, personel seçimi, eğitim, performans değerleme ve ücret yönetimini kapsar."]}], "sinav_tuzaklari": [{"id": 1, "title": "Maslow Hiyerarşisinin Zirvesindeki İhtiyaç", "mistake": "Zirvede 'Saygınlık' veya 'Sosyal' ihtiyaçların yer aldığını düşünmek.", "truth": "Maslow hiyerarşisinin en tepesindeki (zirvedeki) 5. basamak KENDİNİ GERÇEKLEŞTİRME (Self-Actualization) ihtiyacıdır.", "tip": "En altta Fizyolojik, en tepede Kendini Gerçekleştirme vardır."}, {"id": 2, "title": "Girişimci ile Yönetici (Profesyonel Yönetici) Ayrımı", "mistake": "Yöneticinin de kâr ve zarara doğrudan ortak olduğunu varsaymak.", "truth": "Girişimci sermayesini koyar ve kâr/zarar riskini bizzat üstlenir. Profesyonel yönetici ise başkası adına işletmeyi yönetir ve emeği karşılığı maaş/ücret alır.", "tip": "Risk ve kâr-zarar girişimcinindir; yönetici maaşlı profesyoneldir."}, {"id": 3, "title": "Komandite Ortak ile Komanditer Ortak Sorumluluk Farkı", "mistake": "İkisinin sorumluluklarını birbirine karıştırmak.", "truth": "Komandite ortak: Sorumluluğu SINIRSIZDIR, gerçek kişi olmak zorundadır ve şirketi yönetir. Komanditer ortak: Sorumluluğu koyduğu sermaye ile SINIRLIDIR ve şirketi yönetemez.", "tip": "KomanditE = 'Esas sorumlu' (Sınırsız); KomanditeR = 'Rahat ortak' (Sermayesi kadar sınırlı)."}, {"id": 4, "title": "Anonim Şirket ile Limited Şirket Farkları", "mistake": "Limited şirkette pay devrinin elden serbestçe yapılabileceğini sanmak.", "truth": "Anonim şirkette hisse devri çok kolay ve serbesttir. Limited şirkette ise ortak sayısı en çok 50'dir ve pay devri genel kurul onayı, noter ve ticaret sicil tesciline tabidir.", "tip": "A.Ş. = Kolay hisse devri, asgari 50.000 TL; Ltd. = Zor pay devri, en çok 50 ortak."}, {"id": 5, "title": "Carroll'ın Sosyal Sorumluluk Piramidinin Tabanı", "mistake": "Piramidin temelinde 'Yasal' veya 'Ahlaki' sorumluluğun olduğunu sanmak.", "truth": "Archie Carroll'a göre piramidin en tabanında EKONOMİK SORUMLULUK (kârlı olmak ve ayakta kalmak) yer alır. İşletme kâr etmezse diğer sorumlulukları yerine getiremez.", "tip": "Piramidin temeli daima Ekonomik Sorumluluktur."}, {"id": 6, "title": "Joint Venture (Ortak Girişim) ile Konsorsiyum Farkı", "mistake": "Konsorsiyumda da yeni bir tüzel şirket kurulduğunu zannetmek.", "truth": "Joint Venture'da ortaklar bir araya gelerek YENİ BİR TÜZEL KİŞİLİK (ayrı bir şirket) kurarlar. Konsorsiyumda ise büyük bir iş için sadece sözleşmeye dayalı geçici ortaklık kurulur, yeni bir şirket doğmaz.", "tip": "Yeni tüzel şirket varsa = Joint Venture; Geçici işbirliğiyse = Konsorsiyum."}, {"id": 7, "title": "Geriye Doğru Dikey Büyüme ile İleriye Doğru Dikey Büyüme", "mistake": "Kendi mağaza zincirini açmayı geriye doğru büyüme sanmak.", "truth": "Hammadde ve girdi tedarikçisine doğru gitmek GERİYE doğru dikey büyümedir. Dağıtım kanallarına ve nihai satış mağazalarına doğru gitmek İLERİYE doğru dikey büyümedir.", "tip": "Tedarikçiye = Geriye; Müşteriye/Mağazaya = İleriye."}, {"id": 8, "title": "Konglomerat (Çapraz / Karma) Büyüme Amacı", "mistake": "Konglomerat büyümenin aynı sektörde pazar payı kazanmak için yapıldığını düşünmek.", "truth": "Konglomerat büyüme, birbiriyle HİÇBİR İLİŞKİSİ OLMAYAN tamamen farklı sektörlere girilmesidir (Örn: İnşaat firmasının gıda ve bankacılık sektörüne girmesi). Temel amaç sektörel riskleri dağıtmaktır.", "tip": "Farklı sektörler = Konglomerat (Holding) büyüme; amaç risk dağıtımı."}, {"id": 9, "title": "Yönetim Fonksiyonlarının Sıralaması (POLC)", "mistake": "Yönetimin ilk fonksiyonunun örgütleme veya yöneltme olduğunu sanmak.", "truth": "Yönetimin İLK fonksiyonu PLANLAMA, SON fonksiyonu ise DENETİM'dir (Kontrol). Planlama olmadan hiçbir yönetim faaliyeti başlayamaz.", "tip": "Sıralama: Planlama -> Örgütleme -> Yöneltme -> Denetim."}, {"id": 10, "title": "Pazarlamanın 4P'sindeki 'Tutundurma' (Promotion) Kapsamı", "mistake": "Tutundurmanın sadece fiyat indirimi yapmak olduğunu düşünmek.", "truth": "Tutundurma (Promotion); Reklam, Halkla İlişkiler (PR), Kişisel Satış ve Satış Geliştirme (promosyon) unsurlarını içeren geniş bir iletişim karmasıdır.", "tip": "Tutundurma = Müşteriyle iletişim kurulan tüm reklam ve PR faaliyetleridir."}], "formuller_ve_kavramlar": [{"term": "Verimlilik Formülü", "description": "Verimlilik = Üretilen Çıktı / Tüketilen Girdi."}, {"term": "Etkililik (Effectiveness)", "description": "İşletmenin önceden belirlediği stratejik hedeflere ve amaçlara ulaşma derecesidir."}, {"term": "İktisadilik (Karlılık)", "description": "İktisadilik = Satış Hasılatı / Katlanılan Toplam Maliyet."}, {"term": "Maslow İhtiyaçlar Piramidi", "description": "Fizyolojik -> Güvenlik -> Sosyal -> Saygınlık -> Kendini Gerçekleştirme."}, {"term": "Üretim Faktörleri ve Getirileri", "description": "Emek -> Ücret, Sermaye -> Faiz, Doğal Kaynaklar -> Rant, Girişimci -> Kâr."}, {"term": "Carroll KSS Piramidi", "description": "Ekonomik (Taban) -> Yasal -> Etik -> Filantropik/Gönüllü (Zirve)."}, {"term": "PESTLE Analizi", "description": "Politik, Ekonomik, Sosyo-kültürel, Teknolojik, Yasal, Ekolojik makro çevre faktörleri analizi."}, {"term": "Porter'ın 5 Güç Modeli", "description": "Sektörel rekabet, potansiyel rakiplerin tehdidi, tedarikçilerin pazarlık gücü, alıcıların pazarlık gücü, ikame ürünlerin tehdidi."}, {"term": "KOBİ Çalışan Sınırları", "description": "Mikro: 1-9, Küçük: 10-49, Orta: 50-249 çalışan."}, {"term": "Joint Venture (Ortak Girişim)", "description": "İki şirketin belirli bir amaçla bir araya gelerek yeni bir tüzel kişilik oluşturması."}, {"term": "Whistleblowing", "description": "Kurum içindeki yasadışı veya etik dışı eylemlerin yetkililere ihbar edilmesi."}, {"term": "Greenwashing (Yeşil Yıkama)", "description": "Çevre dostu olmayan ürünlerin aldatıcı reklamlarla çevreci gibi pazarlanması."}, {"term": "Michael Porter Jenerik Stratejileri", "description": "Maliyet Liderliği, Farklılaştırma, Odaklanma."}, {"term": "Pazarlamanın 4P'si", "description": "Product (Ürün), Price (Fiyat), Place (Dağıtım), Promotion (Tutundurma)."}, {"term": "Yönetim Fonksiyonları (POLC)", "description": "Planlama, Örgütleme, Yöneltme, Denetim."}], "flashcards": [{"id": 1, "unit": 1, "question": "Maslow'un ihtiyaçlar hiyerarşisinin en tepesinde (zirvesinde) hangi ihtiyaç yer alır?", "answer": "Kendini Gerçekleştirme (Self-Actualization)."}, {"id": 2, "unit": 1, "question": "Girişimcinin üretim faktörlerini bir araya getirmesi karşılığında elde ettiği gelir payı nedir?", "answer": "Kâr (Aynı zamanda zarar riskini de üstlenir)."}, {"id": 3, "unit": 1, "question": "İşletmenin önceden belirlediği amaç ve hedeflere ulaşma derecesine ne ad verilir?", "answer": "Etkililik (Effectiveness)."}, {"id": 4, "unit": 1, "question": "Üretilen çıktı miktarının kullanılan girdi miktarına bölünmesiyle hangi ölçüt hesaplanır?", "answer": "Verimlilik (Productivity)."}, {"id": 5, "unit": 2, "question": "İşletmenin PESTLE analiziyle incelediği çevre katmanı hangisidir?", "answer": "Genel Dış Çevre (Makro Çevre)."}, {"id": 6, "unit": 2, "question": "Michael Porter'ın 5 Güç Modeli hangi çevrenin analizinde kullanılır?", "answer": "Yakın Dış Çevre (Sektörel / Görev Çevresi)."}, {"id": 7, "unit": 2, "question": "Hem faktör sayısı çok fazla olan hem de faktörlerin çok hızlı değiştiği çevreye ne denir?", "answer": "Karmaşık ve Dinamik Çevre (En yüksek belirsizlik düzeyi)."}, {"id": 8, "unit": 3, "question": "10 ile 49 arasında çalışanı olan işletmeler KOBİ sınıflandırmasında hangi gruptadır?", "answer": "Küçük İşletme."}, {"id": 9, "unit": 3, "question": "Komandit şirkette sorumluluğu koyduğu sermaye payı ile sınırlı olan ortağa ne ad verilir?", "answer": "Komanditer Ortak."}, {"id": 10, "unit": 3, "question": "En fazla 50 ortağa sahip olabilen ve pay devri noter/sicil onayına tabi olan sermaye şirketi hangisidir?", "answer": "Limited Şirket (Ltd. Şti.)."}, {"id": 11, "unit": 3, "question": "Amacı kâr elde etmek değil, ortakların geçim ve meslek ihtiyaçlarını karşılıklı yardımlaşmayla karşılamak olan kuruluş nedir?", "answer": "Kooperatif."}, {"id": 12, "unit": 4, "question": "Carroll'ın Sosyal Sorumluluk Piramidinin en tabanında hangi sorumluluk yer alır?", "answer": "Ekonomik Sorumluluk (Kârlı olmak ve verimli üretmek)."}, {"id": 13, "unit": 4, "question": "Şirket içindeki yolsuzluk veya ahlak dışı uygulamaların bir çalışan tarafından ifşa edilmesine ne denir?", "answer": "Whistleblowing (İçeriden İhbar / Etik Bildirim)."}, {"id": 14, "unit": 4, "question": "Bir işletmenin gerçekte çevreci olmadığı halde kendini öyle göstermesine ne ad verilir?", "answer": "Yeşil Yıkama (Greenwashing)."}, {"id": 15, "unit": 5, "question": "Bir yatırım kararının verilmesinden önce yapılan kapsamlı yapılabilirlik araştırmasına ne denir?", "answer": "Fizibilite Etüdü (Araştırması)."}, {"id": 16, "unit": 5, "question": "Pazar araştırması, talep tahmini ve kapasite seçimi fizibilite araştırmasının hangi boyutundadır?", "answer": "Ekonomik Etüt boyutundadır."}, {"id": 17, "unit": 5, "question": "İşletmenin maliyetlerini en aza indirip kârını en üst düzeye çıkaran ideal konuma ne denir?", "answer": "Optimum Kuruluş Yeri."}, {"id": 18, "unit": 6, "question": "Aynı sektörde ve aynı üretim aşamasındaki bir rakip firmayı satın alarak büyümeye ne ad verilir?", "answer": "Yatay Büyüme."}, {"id": 19, "unit": 6, "question": "Bir fabrikanın kendi hammadde üreticisini satın alması ne tür bir büyümedir?", "answer": "Geriye Doğru Dikey Büyüme."}, {"id": 20, "unit": 6, "question": "Birbirleriyle hiçbir sektörel ve teknolojik bağı olmayan farklı sektörlere girerek büyüme türü nedir?", "answer": "Konglomerat (Çapraz / Karma) Büyüme."}, {"id": 21, "unit": 6, "question": "İki bağımsız şirketin birleşip yeni bir üçüncü tüzel şirket kurmasıyla oluşan işbirliği nedir?", "answer": "Joint Venture (Ortak Girişim)."}, {"id": 22, "unit": 7, "question": "Bir firmanın yabancı pazarlara açılırken başvurduğu en düşük riskli ilk adım genellikle nedir?", "answer": "İhracat (Exporting)."}, {"id": 23, "unit": 7, "question": "Tüm dünyada standartlaştırılmış tek bir ürün satarak ölçek ekonomisi yakalayan strateji nedir?", "answer": "Küresel (Global) Strateji."}, {"id": 24, "unit": 7, "question": "Michael Porter'a göre sektördeki en düşük üretim maliyetini yakalamayı amaçlayan strateji nedir?", "answer": "Maliyet Liderliği Stratejisi."}, {"id": 25, "unit": 7, "question": "Müşterilerin üstün algıladığı benzersiz tasarım ve kalite yaratarak primli fiyat uygulayan strateji nedir?", "answer": "Farklılaştırma Stratejisi."}, {"id": 26, "unit": 8, "question": "Yönetim fonksiyonlarının ilk ve en temel adımı hangisidir?", "answer": "Planlama."}, {"id": 27, "unit": 8, "question": "Yönetim sürecinin gerçekleşen sonuçları standartlarla karşılaştırıp sapmaları düzelten son adımı nedir?", "answer": "Denetim (Kontrol)."}, {"id": 28, "unit": 8, "question": "Pazarlamanın 4P'si nelerdir?", "answer": "Product (Ürün), Price (Fiyat), Place (Dağıtım), Promotion (Tutundurma)."}, {"id": 29, "unit": 8, "question": "Hizmet pazarlamasında geleneksel 4P'ye eklenen 3P nedir?", "answer": "People (İnsan), Process (Süreç), Physical Evidence (Fiziksel Kanıtlar)."}, {"id": 30, "unit": 8, "question": "İşletmenin ihtiyaç duyduğu fonları en uygun şartlarda bulup yatırıma yönlendiren fonksiyon nedir?", "answer": "Finansman Fonksiyonu."}], "exams": [{"title": "Vize Deneme Sınavı 1", "filename": "Vize_Deneme_1.md", "questions": [{"id": 1, "unit": 1, "question": "Maslow'un İhtiyaçlar Hiyerarşisinde bireyin potansiyelini tam olarak ortaya koyma ve geliştirme arzusu piramidin hangi basamağında yer alır?", "options": ["A) Fizyolojik ihtiyaçlar", "B) Güvenlik ihtiyaçları", "C) Sosyal ihtiyaçlar", "D) Saygınlık ihtiyaçları", "E) Kendini gerçekleştirme ihtiyaçları"], "correct_answer": "E", "explanation": "Maslow'un ihtiyaçlar piramidinin en tepesinde (5. basamak) 'Kendini Gerçekleştirme' yer alır."}, {"id": 2, "unit": 1, "question": "Üretim faktörlerinden biri olan 'Doğal Kaynaklar'ın (Toprak) üretim sürecine katılması karşılığında elde ettiği gelir payı nedir?", "options": ["A) Ücret", "B) Faiz", "C) Rant (Kira)", "D) Kâr", "E) Prim"], "correct_answer": "C", "explanation": "Doğal kaynakların payı Rant (Kira), emeğin payı Ücret, sermayenin payı Faiz, girişimcinin payı Kârdır."}, {"id": 3, "unit": 1, "question": "Bir işletmenin önceden belirlediği stratejik hedeflere ve amaçlara ulaşabilme derecesini ifade eden başarı ölçütü hangisidir?", "options": ["A) Verimlilik", "B) Etkililik", "C) İktisadilik", "D) Likidite", "E) Esneklik"], "correct_answer": "B", "explanation": "Hedeflere ulaşma derecesi 'Etkililik' (Effectiveness / Doğru işi yapmak) olarak adlandırılır."}, {"id": 4, "unit": 1, "question": "Girişimci ile profesyonel yönetici arasındaki en temel ayrım aşağıdakilerden hangisidir?", "options": ["A) Yöneticinin üniversite mezunu olması", "B) Girişimcinin kâr ve zarar riskini bizzat üstlenmesi", "C) Yöneticinin daha çok çalışması", "D) Girişimcinin emir vermemesi", "E) Aralarında hiçbir fark olmaması"], "correct_answer": "B", "explanation": "Girişimci sermayesini ortaya koyarak kâr ve zarar riskini üstlenir; yönetici ise ücret karşılığı başkaları adına çalışır."}, {"id": 5, "unit": 1, "question": "Üretilen toplam çıktı miktarının kullanılan girdi miktarına bölünmesiyle hesaplanan oran hangisidir?", "options": ["A) Verimlilik (Productivity)", "B) Kârlılık", "C) Finansal kaldıraç", "D) İktisadilik", "E) Başabaş oranı"], "correct_answer": "A", "explanation": "Çıktı / Girdi oranı Verimliliktir."}, {"id": 6, "unit": 2, "question": "İşletmenin kontrol edemediği; faiz, enflasyon, döviz kurları ve ekonomik büyüme gibi unsurları kapsayan makro çevre faktörü hangisidir?", "options": ["A) Sektörel çevre", "B) Ekonomik çevre", "C) Sosyo-kültürel çevre", "D) Örgütsel çevre", "E) Teknolojik çevre"], "correct_answer": "B", "explanation": "Faiz, kur, enflasyon ve millî gelir Ekonomik Çevre faktörleridir."}, {"id": 7, "unit": 2, "question": "Michael Porter'ın Sektörel Rekabeti analiz eden '5 Güç Modeli'nde aşağıdakilerden hangisi yer almaz?", "options": ["A) Mevcut rakipler arasındaki rekabet", "B) Tedarikçilerin pazarlık gücü", "C) Alıcıların pazarlık gücü", "D) İkame ürünlerin tehdidi", "E) İşletmenin örgüt kültürü"], "correct_answer": "E", "explanation": "Örgüt kültürü işletmenin 'İç Çevresi'ne aittir; Porter'ın 5 Güç Modeli sektörel dış çevreyi inceler."}, {"id": 8, "unit": 2, "question": "Çevredeki faktör sayısının çok fazla olduğu ve bu faktörlerin sürekli ve öngörülemez şekilde değiştiği çevre tipi hangisidir?", "options": ["A) Basit - Durağan Çevre", "B) Karmaşık - Durağan Çevre", "C) Basit - Dinamik Çevre", "D) Karmaşık - Dinamik Çevre", "E) Kapalı Çevre"], "correct_answer": "D", "explanation": "En yüksek belirsizlik 'Karmaşık ve Dinamik' çevrede görülür."}, {"id": 9, "unit": 2, "question": "Bir işletmenin açık sistem yaklaşımında müşterilerine sunduğu ürün, hizmet ve atıklar sistemin hangi parçasını oluşturur?", "options": ["A) Girdiler", "B) Dönüşüm süreci", "C) Çıktılar", "D) Geri bildirim", "E) İç çevre"], "correct_answer": "C", "explanation": "Üretilen mal, hizmet ve ortaya çıkan atıklar sistemin 'Çıktıları'dır."}, {"id": 10, "unit": 2, "question": "Nüfusun yaş yapısı, eğitim düzeyi, kadınların işgücüne katılımı ve tüketim alışkanlıkları PESTLE analizinde hangi başlık altında incelenir?", "options": ["A) Politik çevre", "B) Sosyo-Kültürel çevre", "C) Teknolojik çevre", "D) Yasal çevre", "E) Ekolojik çevre"], "correct_answer": "B", "explanation": "Demografi, yaşam biçimleri ve toplumsal değerler Sosyo-Kültürel çevre unsurlarıdır."}, {"id": 11, "unit": 3, "question": "KOBİ sınıflandırmasına göre çalışan sayısı 10 ile 49 kişi arasında olan işletmeler hangi kategoriye girer?", "options": ["A) Mikro işletme", "B) Küçük işletme", "C) Orta büyüklükte işletme", "D) Büyük işletme", "E) Dev işletme"], "correct_answer": "B", "explanation": "1-9 Mikro, 10-49 Küçük, 50-249 Orta büyüklükte işletmedir."}, {"id": 12, "unit": 3, "question": "Komandit şirkette sorumluluğu şirkete koyduğu sermaye payı ile sınırlı olan ve şirketi yönetme yetkisi bulunmayan ortak hangisidir?", "options": ["A) Komandite ortak", "B) Komanditer ortak", "C) Kollektif ortak", "D) Hâkim ortak", "E) Murahhas aza"], "correct_answer": "B", "explanation": "Komanditer ortağın sorumluluğu sermayesiyle sınırlıdır."}, {"id": 13, "unit": 3, "question": "Türk Ticaret Kanunu'na göre ortak sayısı en çok 50 olabilen ve pay devri noter tasdiki ile genel kurul onayına tabi olan sermaye şirketi hangisidir?", "options": ["A) Anonim Şirket", "B) Limited Şirket", "C) Kollektif Şirket", "D) Komandit Şirket", "E) Kooperatif"], "correct_answer": "B", "explanation": "Limited şirketlerde ortak sayısı en fazla 50 olabilir ve pay devri sıkı şekil şartlarına bağlıdır."}, {"id": 14, "unit": 3, "question": "Ortaklarının karşılıklı yardımlaşma ve dayanışma yoluyla meslek veya geçim ihtiyaçlarını uygun şartlarda karşılamak amacıyla kurulan kuruluş hangisidir?", "options": ["A) Anonim Şirket", "B) Kooperatif", "C) Limited Şirket", "D) Holding", "E) Joint Venture"], "correct_answer": "B", "explanation": "Kooperatifler kâr değil karşılıklı yardım ve hizmet amaçlıdır."}, {"id": 15, "unit": 3, "question": "Sermayesi paylara bölünmüş olan ve pay senetlerinin devri en kolay olan sermaye şirketi türü hangisidir?", "options": ["A) Anonim Şirket (A.Ş.)", "B) Limited Şirket", "C) Kollektif Şirket", "D) Adi Şirket", "E) Adi Komandit Şirket"], "correct_answer": "A", "explanation": "Anonim Şirketlerde hisse senedi devri kural olarak serbest ve son derece kolaydır."}, {"id": 16, "unit": 4, "question": "Archie Carroll'ın Sosyal Sorumluluk Piramidinin en temelinde (tabanında) yer alan sorumluluk düzeyi hangisidir?", "options": ["A) Yasal sorumluluk", "B) Etik sorumluluk", "C) Ekonomik sorumluluk", "D) Filantropik sorumluluk", "E) Çevresel sorumluluk"], "correct_answer": "C", "explanation": "Carroll'ın piramidinin tabanında Ekonomik Sorumluluk (kârlı olmak) yer alır."}, {"id": 17, "unit": 4, "question": "Bir kurumda çalışan kişinin kurum içindeki yolsuzluk, hile veya yasadışı uygulamaları yetkili makamlara bildirmesine ne ad verilir?", "options": ["A) Whistleblowing (İçeriden Bilgi İfşası)", "B) Greenwashing", "C) Lobicilik", "D) Konsolidasyon", "E) Sosyal denetim"], "correct_answer": "A", "explanation": "Yasadışı veya etik dışı durumların yetkililere ifşa edilmesine Whistleblowing denir."}, {"id": 18, "unit": 4, "question": "Bir şirketin çevreye zararlı uygulamalarını gizlemek için reklam ve halkla ilişkiler yoluyla kendini çevreci göstermesi aldatmacasına ne ad verilir?", "options": ["A) Sosyal sorumluluk", "B) Yeşil Yıkama (Greenwashing)", "C) Çevresel sürdürülebilirlik", "D) Karbon ayak izi", "E) Filantropi"], "correct_answer": "B", "explanation": "Sahte çevrecilik propagandası 'Yeşil Yıkama (Greenwashing)' olarak adlandırılır."}, {"id": 19, "unit": 4, "question": "Bir işletmenin kararlarından ve faaliyetlerinden doğrudan ya da dolaylı etkilenen kişi ve gruplara ne ad verilir?", "options": ["A) Hissedar (Shareholder)", "B) Paydaş (Stakeholder)", "C) Komandite ortak", "D) Yönetim kurulu", "E) Girişimci"], "correct_answer": "B", "explanation": "Tüm etkilenen ve etkileyen gruplar 'Paydaş' (Stakeholder) olarak tanımlanır."}, {"id": 20, "unit": 4, "question": "Carroll'ın piramidinin en üst basamağında yer alan, eğitime ve topluma gönüllü katkı sağlamayı ifade eden sorumluluk nedir?", "options": ["A) Ekonomik sorumluluk", "B) Yasal sorumluluk", "C) Etik sorumluluk", "D) Filantropik (Gönüllü) sorumluluk", "E) Zorunlu sorumluluk"], "correct_answer": "D", "explanation": "En üst basamaktaki gönüllü katkılar Filantropik sorumluluktur."}]}, {"title": "Vize Deneme Sınavı 2", "filename": "Vize_Deneme_2.md", "questions": [{"id": 1, "unit": 1, "question": "Maslow hiyerarşisinde düzenli bir işe sahip olma ve sosyal güvenlik kapsamına girme hangi basamaktaki ihtiyacı karşılar?", "options": ["A) Fizyolojik ihtiyaçlar", "B) Güvenlik ihtiyaçları", "C) Saygınlık ihtiyaçları", "D) Sosyal ihtiyaçlar", "E) Kendini gerçekleştirme"], "correct_answer": "B", "explanation": "Gelecek kaygısını azaltma ve iş güvencesi Güvenlik İhtiyaçlarıdır."}, {"id": 2, "unit": 1, "question": "Sermaye faktörünün üretim faaliyetine katılması karşılığında aldığı gelir payı aşağıdakilerden hangisidir?", "options": ["A) Ücret", "B) Rant", "C) Faiz", "D) Kâr", "E) Temettü"], "correct_answer": "C", "explanation": "Sermayenin getirisi Faizdir."}, {"id": 3, "unit": 1, "question": "Satış hasılatının katlanılan toplam maliyet giderlerine bölünmesiyle elde edilen oran nedir?", "options": ["A) Verimlilik", "B) İktisadilik (Karlılık)", "C) Etkililik", "D) Esneklik", "E) Kapasite kullanım oranı"], "correct_answer": "B", "explanation": "Hasılat / Gider oranı İktisadilik olarak adlandırılır."}, {"id": 4, "unit": 1, "question": "Aşağıdakilerden hangisi bir işletmenin 'Birincil (Temel)' amaçları arasında yer alır?", "options": ["A) Çevreye ağaç dikmek", "B) Uzun dönemde kâr maksimizasyonu ve varlığını sürdürme", "C) Şirket içi spor turnuvası düzenlemek", "D) Çalışanlara ücretsiz sinema bileti vermek", "E) Şehir kütüphanesine kitap bağışlamak"], "correct_answer": "B", "explanation": "Kâr elde etmek, süreklilik ve piyasa değerini artırmak işletmenin birincil amaçlarıdır."}, {"id": 5, "unit": 1, "question": "Verimlilik kavramı aşağıdaki ifadelerden hangisiyle özetlenebilir?", "options": ["A) Doğru işi yapmak", "B) İşi doğru ve en az kaynakla yapmak", "C) Sadece kâr etmek", "D) Çok personel çalıştırmak", "E) Reklam vermek"], "correct_answer": "B", "explanation": "Verimlilik aynı girdiyle en yüksek çıktıyı almak, yani 'işi en az kaynakla doğru yapmaktır'."}, {"id": 6, "unit": 2, "question": "İşletmenin yönetim kadrosu, şirket kültürü, çalışanları ve fiziki kaynakları hangi çevre katmanında yer alır?", "options": ["A) İç Çevre", "B) Yakın Dış Çevre", "C) Genel Dış Çevre", "D) Makro Çevre", "E) Sektörel Çevre"], "correct_answer": "A", "explanation": "İşletmenin kendi bünyesinde kontrol edebildiği faktörler İç Çevredir."}, {"id": 7, "unit": 2, "question": "Rakipler, tedarikçiler ve ikame mallar işletmenin hangi çevresine aittir?", "options": ["A) İç Çevre", "B) Yakın Dış Çevre (Sektörel Çevre)", "C) Makro Çevre", "D) Doğal Çevre", "E) Yasal Çevre"], "correct_answer": "B", "explanation": "Sektör içindeki paydaşlar Yakın Dış Çevreyi oluşturur."}, {"id": 8, "unit": 2, "question": "Girdi alan, bunları işleyip çevreye çıktı veren ve çevresiyle sürekli etkileşimde olan sistem türü hangisidir?", "options": ["A) Kapalı Sistem", "B) Açık Sistem", "C) Statik Sistem", "D) Yalıtılmış Sistem", "E) Lineer Sistem"], "correct_answer": "B", "explanation": "İşletmeler çevresiyle sürekli veri ve kaynak alışverişinde olan Açık Sistemlerdir."}, {"id": 9, "unit": 2, "question": "Yapay zeka, nesnelerin interneti ve otomasyondaki gelişmeler PESTLE analizinde hangi başlık altında değerlendirilir?", "options": ["A) Politik faktörler", "B) Teknolojik faktörler", "C) Ekolojik faktörler", "D) Yasal faktörler", "E) Sosyal faktörler"], "correct_answer": "B", "explanation": "Bilişim ve üretimdeki teknik yenilikler Teknolojik faktörlerdir."}, {"id": 10, "unit": 2, "question": "İşletme açısından çevresel belirsizliğin en düşük olduğu çevre türü hangisidir?", "options": ["A) Karmaşık - Dinamik", "B) Basit - Durağan", "C) Karmaşık - Durağan", "D) Basit - Dinamik", "E) Değişken"], "correct_answer": "B", "explanation": "Faktör sayısının az (basit) ve değişim hızının yavaş (durağan) olduğu durum belirsizliğin en az olduğu durumdur."}, {"id": 11, "unit": 3, "question": "Çalışan sayısı 1 ile 9 kişi arasında olan mikro işletmeler KOBİ mevzuatında hangi büyüklük grubunu oluşturur?", "options": ["A) Mikro İşletme", "B) Küçük İşletme", "C) Orta İşletme", "D) Büyük İşletme", "E) Aile İşletmesi"], "correct_answer": "A", "explanation": "1-9 çalışan arası Mikro İşletmedir."}, {"id": 12, "unit": 3, "question": "Aşağıdaki şirket türlerinden hangisi bir 'Şahıs Şirketi'dir?", "options": ["A) Anonim Şirket", "B) Limited Şirket", "C) Kollektif Şirket", "D) Sermayesi Paylara Bölünmüş Komandit Şirket", "E) Kooperatif"], "correct_answer": "C", "explanation": "Kollektif ve Adi şirketler şahıs şirketleridir; ortakların sorumluluğu sınırsızdır."}, {"id": 13, "unit": 3, "question": "Komandit şirkette şirketi yönetme yetkisine sahip olan ve tüm mal varlığıyla sınırsız sorumlu olan ortak hangisidir?", "options": ["A) Komanditer ortak", "B) Komandite ortak", "C) Hissedar", "D) Murahhas aza", "E) Komisyoncu"], "correct_answer": "B", "explanation": "Komandite ortak sınırsız sorumlu olan ve şirketi yöneten ortaktır."}, {"id": 14, "unit": 3, "question": "Tüzel kişiliği bulunmayan ve Türk Borçlar Kanunu hükümlerine göre faaliyet gösteren şirket türü hangisidir?", "options": ["A) Adi Şirket", "B) Anonim Şirket", "C) Limited Şirket", "D) Kollektif Şirket", "E) Kooperatif"], "correct_answer": "A", "explanation": "Adi şirketin tüzel kişiliği ve ticaret unvanı yoktur, Borçlar Kanununa tabidir."}, {"id": 15, "unit": 3, "question": "Sermaye Piyasası Kuruluna kaydolarak hisse senetlerini Borsa İstanbul'da (BIST) halka arz edebilen şirket türü hangisidir?", "options": ["A) Kollektif Şirket", "B) Limited Şirket", "C) Anonim Şirket", "D) Adi Şirket", "E) Komandit Şirket"], "correct_answer": "C", "explanation": "Yalnızca Anonim Şirketler (A.Ş.) hisselerini halka arz edebilirler."}, {"id": 16, "unit": 4, "question": "Kanunlara ve düzenlemelere tam uyum sağlamak Carroll'ın piramidinde hangi sorumluluk düzeyini ifade eder?", "options": ["A) Ekonomik", "B) Yasal", "C) Etik", "D) Gönüllü", "E) Çevresel"], "correct_answer": "B", "explanation": "Yasalara uymak Yasal Sorumluluktur."}, {"id": 17, "unit": 4, "question": "Kanunlarda cezai yaptırımı olmasa bile toplum vicdanında kabul görmüş dürüstlük ve adalet ilkelerine uygun hareket etmek hangi sorumluluktur?", "options": ["A) Ekonomik", "B) Yasal", "C) Etik Sorumluluk", "D) Vergi sorumluluğu", "E) Şirket içi disiplin"], "correct_answer": "C", "explanation": "Yazılı kural ötesinde ahlaki olanı yapmak Etik Sorumluluktur."}, {"id": 18, "unit": 4, "question": "Aşağıdakilerden hangisi bir işletmenin 'İç Paydaşları' arasında yer alır?", "options": ["A) Müşteriler", "B) Tedarikçiler", "C) Çalışanlar", "D) Rakipler", "E) Devlet"], "correct_answer": "C", "explanation": "Çalışanlar ve yöneticiler şirketin iç paydaşlarıdır; müşteriler ve tedarikçiler dış paydaştır."}, {"id": 19, "unit": 4, "question": "Bir gıda firmasının ürünlerinde zararlı kimyasallar tespit eden laboratuvar uzmanının bunu kamu denetçilerine bildirmesi neye örnektir?", "options": ["A) Whistleblowing", "B) Greenwashing", "C) Lobicilik", "D) Endüstriyel casusluk", "E) Haksız rekabet"], "correct_answer": "A", "explanation": "İçerideki yasadışı veya halk sağlığını tehdit eden durumu ifşa etmek Whistleblowing'dir."}, {"id": 20, "unit": 4, "question": "İşletmelerin topluma yönelik kütüphane yaptırması, okul ve hastane bağışlarında bulunması hangi sorumluluk türüdür?", "options": ["A) Ekonomik sorumluluk", "B) Yasal sorumluluk", "C) Filantropik (Gönüllü) sorumluluk", "D) Cezai sorumluluk", "E) Finansal sorumluluk"], "correct_answer": "C", "explanation": "Bağış ve sosyal yardımlar Filantropik (hayırseverlik) sorumluluktur."}]}, {"title": "Final Deneme Sınavı 1", "filename": "Final_Deneme_1.md", "questions": [{"id": 1, "unit": 1, "question": "(Vize Tekrarı) Maslow ihtiyaçlar hiyerarşisinde yemek yeme ve uyku hangi düzey ihtiyaçtır?", "options": ["A) Fizyolojik", "B) Güvenlik", "C) Sosyal", "D) Saygınlık", "E) Kendini gerçekleştirme"], "correct_answer": "A", "explanation": "Temel biyolojik ihtiyaçlar Fizyolojik ihtiyaçlardır."}, {"id": 2, "unit": 2, "question": "(Vize Tekrarı) İşletmenin kontrol edemediği makro çevreyi analiz eden çerçeve hangisidir?", "options": ["A) PESTLE", "B) Porter 5 Güç", "C) 4P", "D) BCG Matrisi", "E) SMART Analizi"], "correct_answer": "A", "explanation": "Genel dış çevre PESTLE analizi ile incelenir."}, {"id": 3, "unit": 3, "question": "(Vize Tekrarı) Ortak sayısı 50 ile sınırlandırılmış olan sermaye şirketi hangisidir?", "options": ["A) Anonim Şirket", "B) Limited Şirket", "C) Kollektif Şirket", "D) Komandit Şirket", "E) Kooperatif"], "correct_answer": "B", "explanation": "Limited şirketlerde ortak sayısı en fazla 50 olabilir."}, {"id": 4, "unit": 4, "question": "(Vize Tekrarı) Carroll piramidinde kanunlara eksiksiz uymak hangi sorumluluktur?", "options": ["A) Yasal sorumluluk", "B) Ekonomik sorumluluk", "C) Etik sorumluluk", "D) Gönüllü sorumluluk", "E) Çevresel sorumluluk"], "correct_answer": "A", "explanation": "Kanunlara uyum Yasal Sorumluluktur."}, {"id": 5, "unit": 5, "question": "Bir işletme kurma sürecinde yatırım kararını vermeden önce yapılan pazar, teknik ve finansal değerlendirmelerin tümüne ne ad verilir?", "options": ["A) Fizibilite (Yapılabilirlik) Araştırması", "B) Deneme üretimi", "C) Kesin proje", "D) ÇED raporu", "E) Tescil işlemi"], "correct_answer": "A", "explanation": "Kapsamlı yapılabilirlik etüdüne Fizibilite Araştırması denir."}, {"id": 6, "unit": 5, "question": "Fizibilite araştırmasında pazarın büyüklüğü, hedef müşteri kitlesi, talep tahmini ve kapasite büyüklüğü hangi etüt kapsamında incelenir?", "options": ["A) Teknik Etüt", "B) Ekonomik Etüt", "C) Finansal Etüt", "D) Yasal Etüt", "E) Örgütsel Etüt"], "correct_answer": "B", "explanation": "Pazar, talep ve kapasite analizleri Ekonomik Etüt içindedir."}, {"id": 7, "unit": 5, "question": "İşletmenin üretim maliyetlerini en aza indirirken kârını ve verimliliğini en üst düzeye çıkaran coğrafi yere ne ad verilir?", "options": ["A) Optimum Kuruluş Yeri", "B) Organize Sanayi Bölgesi", "C) Serbest Bölge", "D) Liman bölgesi", "E) Teknopark"], "correct_answer": "A", "explanation": "Maliyetleri minimize eden en uygun yer Optimum Kuruluş Yeridir."}, {"id": 8, "unit": 6, "question": "Aynı sektörde ve aynı üretim aşamasında yer alan rakip bir firmanın satın alınması veya birleşilmesi ne tür bir büyümedir?", "options": ["A) Dikey Büyüme", "B) Yatay Büyüme", "C) Çapraz (Konglomerat) Büyüme", "D) İç Büyüme", "E) Dairesel Büyüme"], "correct_answer": "B", "explanation": "Aynı sektördeki rakiplerle birleşme Yatay Büyümedir."}, {"id": 9, "unit": 6, "question": "Bir otomobil fabrikasının kendi lastik ve cam tedarikçilerini bünyesine katması hangi büyüme stratejisidir?", "options": ["A) Geriye Doğru Dikey Büyüme", "B) İleriye Doğru Dikey Büyüme", "C) Yatay Büyüme", "D) Konglomerat Büyüme", "E) İç Büyüme"], "correct_answer": "A", "explanation": "Girdi ve hammadde tedarikçilerine doğru genişleme Geriye Doğru Dikey Büyümedir."}, {"id": 10, "unit": 6, "question": "Birbirleriyle hiçbir sektörel ve teknolojik ilişkisi olmayan tamamen farklı sektörlerdeki şirketleri bünyesinde toplayan holding yapılanmalarına ne ad verilir?", "options": ["A) Dikey Büyüme", "B) Yatay Büyüme", "C) Konglomerat (Çapraz/Karma) Büyüme", "D) Tekel", "E) Kartel"], "correct_answer": "C", "explanation": "İlişkisiz sektörlerde büyüme Konglomerat (Çapraz) Büyümedir; amaç risk dağıtımıdır."}, {"id": 11, "unit": 6, "question": "İki veya daha fazla bağımsız şirketin belirli bir ticari hedef için sermayelerini birleştirerek YENİ VE BAĞIMSIZ BİR TÜZEL ŞİRKET kurması işbirliği hangisidir?", "options": ["A) Konsorsiyum", "B) Joint Venture (Ortak Girişim)", "C) Kartel", "D) Tröst", "E) Centilmenlik Anlaşması"], "correct_answer": "B", "explanation": "Yeni bir tüzel kişilik kurulması Joint Venture (Ortak Girişim) modelidir."}, {"id": 12, "unit": 7, "question": "Bir firmanın yurtdışı pazarlara açılırken başvurduğu en az riskli ve en yaygın ilk aşama hangisidir?", "options": ["A) Doğrudan Yabancı Yatırım (FDI)", "B) İhracat (Exporting)", "C) Yurtdışında fabrika kurma", "D) Yabancı şirket satın alma", "E) Joint Venture"], "correct_answer": "B", "explanation": "İhracat en düşük sermaye riski taşıyan ilk uluslararasılaşma adımıdır."}, {"id": 13, "unit": 7, "question": "Tüm dünyada yerel farklılıkları dikkate almayıp standartlaştırılmış tek bir ürün satarak küresel maliyet liderliği elde etmeyi hedefleyen strateji nedir?", "options": ["A) Çok Uluslu Strateji", "B) Küresel (Global) Strateji", "C) Ulusötesi Strateji", "D) Odaklanma Stratejisi", "E) Niş Strateji"], "correct_answer": "B", "explanation": "Standart tek ürün ve yüksek küresel entegrasyon Küresel (Global) Stratejidir."}, {"id": 14, "unit": 7, "question": "Michael Porter'ın Jenerik Rekabet Stratejilerinden hangisi sektördeki en düşük üretim maliyetine ulaşarak geniş pazara hakim olmayı hedefler?", "options": ["A) Farklılaştırma", "B) Maliyet Liderliği", "C) Odaklanma", "D) İnovasyon", "E) Çeşitlendirme"], "correct_answer": "B", "explanation": "En düşük maliyetle üretim yapmak 'Maliyet Liderliği' stratejisidir."}, {"id": 15, "unit": 7, "question": "Müşterinin zihninde benzersiz bir ürün kalitesi, tasarımı veya marka imajı yaratarak yüksek primli fiyattan satış yapma stratejisi nedir?", "options": ["A) Maliyet Liderliği", "B) Farklılaştırma", "C) Fiyat Kırma", "D) Taklitçilik", "E) Kartel"], "correct_answer": "B", "explanation": "Benzersizlik ve marka algısı Farklılaştırma stratejisidir (Örn: Apple)."}, {"id": 16, "unit": 8, "question": "Yönetim fonksiyonlarının İLK basamağı olan, gelecekteki amaç ve hedefleri belirleyip bunlara nasıl ulaşılacağını tasarlayan fonksiyon hangisidir?", "options": ["A) Planlama", "B) Örgütleme", "C) Yöneltme", "D) Denetim", "E) Koordinasyon"], "correct_answer": "A", "explanation": "Yönetimin ilk fonksiyonu Planlamadır."}, {"id": 17, "unit": 8, "question": "Gerçekleşen sonuçları belirlenen standartlarla karşılaştırıp sapmaları tespit eden ve düzeltici önlemler alan SON yönetim fonksiyonu hangisidir?", "options": ["A) Planlama", "B) Örgütleme", "C) Yöneltme", "D) Denetim (Kontrol)", "E) Motivasyon"], "correct_answer": "D", "explanation": "Yönetimin son adımı Denetimdir (Kontrol)."}, {"id": 18, "unit": 8, "question": "Pazarlama karmasını oluşturan 4P bileşenleri arasında aşağıdakilerden hangisi yer almaz?", "options": ["A) Product (Ürün)", "B) Price (Fiyat)", "C) Place (Dağıtım)", "D) Promotion (Tutundurma)", "E) Production (Üretim)"], "correct_answer": "E", "explanation": "4P: Product, Price, Place ve Promotion'dır. Production (Üretim) pazarlama karması içinde yer almaz."}, {"id": 19, "unit": 8, "question": "Hizmet sektöründe geleneksel 4P'ye eklenen 3 yeni pazarlama bileşeni (7P) hangileridir?", "options": ["A) Personel, Süreç, Fiziki Kanıtlar", "B) Planlama, Para, Pazar", "C) Patent, Performans, Politika", "D) Paydaş, Portföy, Promosyon", "E) Paketleme, Prestij, Pozisyon"], "correct_answer": "A", "explanation": "Hizmet pazarlamasında People (İnsan/Personel), Process (Süreç) ve Physical Evidence (Fiziki Kanıtlar) eklenir."}, {"id": 20, "unit": 8, "question": "İşletmenin ihtiyaç duyduğu fonları en uygun maliyetle bulup en kârlı yatırımlara yönlendiren temel işletme fonksiyonu nedir?", "options": ["A) Pazarlama", "B) Finansman", "C) Üretim", "D) İnsan Kaynakları", "E) Halkla İlişkiler"], "correct_answer": "B", "explanation": "Fon sağlama ve yatırım yönetimi Finansman fonksiyonunun görevidir."}]}, {"title": "Final Deneme Sınavı 2", "filename": "Final_Deneme_2.md", "questions": [{"id": 1, "unit": 1, "question": "(Vize Tekrarı) Emek üretim faktörünün getirisini ifade eden kavram nedir?", "options": ["A) Faiz", "B) Rant", "C) Ücret", "D) Kâr", "E) Prim"], "correct_answer": "C", "explanation": "Emeğin karşılığı Ücrettir."}, {"id": 2, "unit": 2, "question": "(Vize Tekrarı) Doğrudan işletme içinde yer alan kurum kültürü ve yönetim yapısı hangi çevreye aittir?", "options": ["A) İç Çevre", "B) Dış Çevre", "C) Görev Çevresi", "D) Makro Çevre", "E) Genel Çevre"], "correct_answer": "A", "explanation": "Kurum kültürü İç Çevrenin unsurudur."}, {"id": 3, "unit": 3, "question": "(Vize Tekrarı) Anonim şirket kurmak için gereken yasal asgari sermaye tutarı kaç TL'dir?", "options": ["A) 10.000 TL", "B) 50.000 TL", "C) 100.000 TL", "D) 500.000 TL", "E) Sermaye şartı yoktur"], "correct_answer": "B", "explanation": "TTK'ye göre Anonim şirket için asgari sermaye 50.000 TL'dir (Limited için 10.000 TL)."}, {"id": 4, "unit": 4, "question": "(Vize Tekrarı) Bir işletmenin çevreci olmadığı halde aldatıcı reklamlarla öyle görünmesine ne ad verilir?", "options": ["A) Whistleblowing", "B) Yeşil Yıkama (Greenwashing)", "C) Lobicilik", "D) Sosyal denetim", "E) Karbon ticareti"], "correct_answer": "B", "explanation": "Aldatıcı çevreci pazarlamaya Greenwashing denir."}, {"id": 5, "unit": 5, "question": "Fizibilite araştırmasında işletmenin kullanacağı teknoloji, makineler ve fabrika yerleşim planı hangi etütle belirlenir?", "options": ["A) Ekonomik Etüt", "B) Teknik Etüt", "C) Finansal Etüt", "D) Yasal Etüt", "E) Sosyal Etüt"], "correct_answer": "B", "explanation": "Makine, teçhizat ve bina yerleşimi Teknik Etüt konusudur."}, {"id": 6, "unit": 5, "question": "İşletmenin yatırım tutarı, kârlılığı ve başabaş noktası analizleri hangi fizibilite etüdünde incelenir?", "options": ["A) Finansal Etüt", "B) Teknik Etüt", "C) Ekonomik Etüt", "D) Hukuki Etüt", "E) Çevresel Etüt"], "correct_answer": "A", "explanation": "Yatırım tutarı, NBD ve kârlılık Finansal Etüt kapsamındadır."}, {"id": 7, "unit": 5, "question": "Çabuk bozulan veya nakliyesi çok pahalı olan hammaddeleri kullanan işletmeler kuruluş yeri seçiminde neye öncelik verirler?", "options": ["A) Pazara yakınlık", "B) Hammaddeye yakınlık", "C) Finans merkezlerine yakınlık", "D) Limanlara yakınlık", "E) Başkente yakınlık"], "correct_answer": "B", "explanation": "Çabuk bozulan hammadde kullanan fabrikalar (konserve, şeker pancarı vb.) Hammaddeye yakın kurulur."}, {"id": 8, "unit": 6, "question": "Bir süt ve yoğurt üreticisinin kendi zincir marketlerini açarak doğrudan tüketiciye satış yapması hangi büyüme stratejisidir?", "options": ["A) Geriye doğru dikey büyüme", "B) İleriye doğru dikey büyüme", "C) Yatay büyüme", "D) Konglomerat büyüme", "E) Dışsal büyüme"], "correct_answer": "B", "explanation": "Dağıtım ve satış mağazalarını açmak İleriye Doğru Dikey Büyümedir."}, {"id": 9, "unit": 6, "question": "İşletmenin kendi kârlarını dağıtmayıp işletmede bırakarak (otofinansman) kapasitesini artırması hangi büyüme türüdür?", "options": ["A) İç Büyüme", "B) Dış Büyüme", "C) Satın Alma", "D) Birleşme", "E) Ortak Girişim"], "correct_answer": "A", "explanation": "Kendi iç kaynakları ve otofinansmanla büyüme İç Büyümedir."}, {"id": 10, "unit": 6, "question": "Aynı sektördeki iki bağımsız havayolu şirketinin güçlerini birleştirerek tek bir şirket çatısı altında birleşmesine ne ad verilir?", "options": ["A) Yatay Birleşme (Merger)", "B) Dikey Birleşme", "C) Çapraz Birleşme", "D) Konsorsiyum", "E) Franchise"], "correct_answer": "A", "explanation": "Aynı sektördeki rakiplerin birleşmesi Yatay Birleşmedir."}, {"id": 11, "unit": 7, "question": "Bir firmanın yurtdışında sıfırdan fabrika ve tesis kurarak yatırım yapmasına ne ad verilir?", "options": ["A) Dolaylı İhracat", "B) Lisans Verme", "C) Greenfield (Sıfırdan) Yatırım", "D) Konsorsiyum", "E) Portföy Yatırımı"], "correct_answer": "C", "explanation": "Sıfırdan tesis kurarak yapılan doğrudan yabancı yatırım Greenfield Yatırımdır."}, {"id": 12, "unit": 7, "question": "Farklı ülkelerdeki tüketici tercihlerinin ve kültürlerin çok farklı olduğu durumlarda her ülkeye özel ürün geliştiren strateji nedir?", "options": ["A) Çok Uluslu (Multidomestic) Strateji", "B) Küresel Strateji", "C) Standartlaşma Stratejisi", "D) Maliyet Liderliği", "E) Odaklanma"], "correct_answer": "A", "explanation": "Yerel şartlara tam uyum sağlayan yaklaşım Çok Uluslu (Multidomestic) Stratejidir."}, {"id": 13, "unit": 7, "question": "Piyasanın geneline hitap etmek yerine çok dar ve özel bir müşteri grubuna (örneğin sadece solaklar için makas üretenler) odaklanan strateji nedir?", "options": ["A) Maliyet Liderliği", "B) Farklılaştırma", "C) Odaklanma (Niş) Stratejisi", "D) Küresel Strateji", "E) Çapraz Büyüme"], "correct_answer": "C", "explanation": "Dar bir pazar segmentine hizmet etme Odaklanma (Niş) stratejisidir."}, {"id": 14, "unit": 8, "question": "İşletmede görevlerin, yetkilerin, departmanların ve raporlama hiyerarşisinin belirlendiği yönetim fonksiyonu hangisidir?", "options": ["A) Planlama", "B) Örgütleme (Organize Etme)", "C) Yöneltme", "D) Denetim", "E) Bütçeleme"], "correct_answer": "B", "explanation": "İşbölümü, yetki dağıtımı ve departmanlaşma Örgütleme fonksiyonudur."}, {"id": 15, "unit": 8, "question": "Çalışanların motivasyonunu artıran, onları ortak amaca yönlendiren ve liderlik eden yönetim fonksiyonu hangisidir?", "options": ["A) Planlama", "B) Örgütleme", "C) Yöneltme (Liderlik / Yürütme)", "D) Denetim", "E) Raporlama"], "correct_answer": "C", "explanation": "Liderlik ve motivasyon Yöneltme fonksiyonudur."}, {"id": 16, "unit": 8, "question": "Pazarlamada 'Tutundurma' (Promotion) karması içerisinde aşağıdakilerden hangisi yer almaz?", "options": ["A) Reklam", "B) Halkla İlişkiler (PR)", "C) Kişisel Satış", "D) Satış Promosyonları", "E) Ürünün fabrikada paketlenmesi"], "correct_answer": "E", "explanation": "Ürünün fiziksel paketlenmesi Product (Ürün) bileşenine aittir."}, {"id": 17, "unit": 8, "question": "Üretim sürecinde sıfır hata, sürekli iyileştirme (Kaizen) ve müşteri odaklılığı temel alan yönetim felsefesi hangisidir?", "options": ["A) Toplam Kalite Yönetimi (TKY)", "B) Klasik Yönetim", "C) Taylorizm", "D) Bürokratik Yönetim", "E) Matris Yönetim"], "correct_answer": "A", "explanation": "Sürekli iyileştirme ve sıfır hata felsefesi Toplam Kalite Yönetimidir (TKY)."}, {"id": 18, "unit": 8, "question": "İşletmenin personel ihtiyacını belirleme, işe alma, performans değerleme ve kariyer planlamasını yürüten fonksiyon hangisidir?", "options": ["A) İnsan Kaynakları Yönetimi (İKY)", "B) Muhasebe", "C) Pazarlama", "D) Finansman", "E) Lojistik"], "correct_answer": "A", "explanation": "İşe alım ve çalışan gelişimi İnsan Kaynakları Yönetiminin sorumluluğudur."}, {"id": 19, "unit": 8, "question": "İşletmede yeni bir ürün tasarlanması veya mevcut üretim süreçlerinin yenilenmesi hangi fonksiyonun temel görevidir?", "options": ["A) Araştırma ve Geliştirme (AR-GE)", "B) Halkla İlişkiler", "C) Satış", "D) Muhasebe", "E) Tedarik"], "correct_answer": "A", "explanation": "Ürün ve süreç yenilikleri AR-GE fonksiyonu tarafından yürütülür."}, {"id": 20, "unit": 8, "question": "İşletmenin dönen varlıkları ile kısa vadeli borçlarını ödeyebilme gücünü ifade eden finansal kavram nedir?", "options": ["A) Likidite", "B) Kârlılık", "C) Verimlilik", "D) Kaldıraç", "E) Özkaynak"], "correct_answer": "A", "explanation": "Kısa vadeli borç ödeme gücü Likiditedir."}]}]}};
